-- Mirror live Comunhao functions, indexes, triggers and RLS policies.
BEGIN;
SET LOCAL search_path = comunhao, public, auth, extensions;
CREATE TABLE IF NOT EXISTS core.migration_programmability_issues (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  migration_name text NOT NULL,
  object_kind text NOT NULL,
  object_name text NOT NULL,
  error_message text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
DELETE FROM core.migration_programmability_issues WHERE migration_name = '309_comunhao_programmability_and_rls';
DO $objects$
BEGIN
  BEGIN
    EXECUTE $obj1$CREATE OR REPLACE FUNCTION comunhao.accept_legal_document(p_document_key text, p_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  document_exists boolean;
begin
  if auth.uid() is null then
    raise exception 'authentication_required';
  end if;

  select exists (
    select 1
    from comunhao.legal_documents
    where document_key = p_document_key
      and version = p_version
      and published = true
  )
  into document_exists;

  if not document_exists then
    raise exception 'legal_document_not_found';
  end if;

  insert into comunhao.legal_acceptances (profile_id, document_key, version)
  values (auth.uid(), p_document_key, p_version)
  on conflict (profile_id, document_key, version) do update
  set accepted_at = now();

  return jsonb_build_object(
    'document_key', p_document_key,
    'version', p_version,
    'accepted', true,
    'accepted_at', now()
  );
end;
$function$
$obj1$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'accept_legal_document(p_document_key text, p_version text)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj2$CREATE OR REPLACE FUNCTION comunhao.admin_set_church_active_state(p_church_id uuid, p_active boolean, p_notes text DEFAULT NULL::text)
 RETURNS churches
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  church_row comunhao.churches%rowtype;
  notification_title text;
  notification_message text;
begin
  if not comunhao.is_super_admin(auth.uid()) then
    raise exception 'Only super admins can update church active state.';
  end if;

  update comunhao.churches
  set
    active = p_active,
    updated_at = now()
  where id = p_church_id
  returning * into church_row;

  if not found then
    raise exception 'Church not found.';
  end if;

  notification_title := case
    when p_active then 'Igreja reativada'
    else 'Igreja desativada'
  end;
  notification_message := case
    when p_active then 'A igreja ' || church_row.name || ' foi reativada pela equipa Comunhao.'
    else 'A igreja ' || church_row.name || ' foi temporariamente desativada pela equipa Comunhao.'
  end;

  if nullif(trim(coalesce(p_notes, '')), '') is not null then
    notification_message := notification_message || ' Motivo: ' || trim(p_notes);
  end if;

  perform comunhao.notify_church_members(
    p_church_id,
    notification_title,
    notification_message,
    case when p_active then 'church_reactivated' else 'church_deactivated' end,
    case when p_active then 'normal' else 'high' end,
    jsonb_build_object(
      'church_id', p_church_id,
      'church_name', church_row.name,
      'active', p_active,
      'notes', p_notes
    )
  );

  perform comunhao.create_platform_audit_log(
    'church.active_state.updated',
    'church',
    p_church_id,
    p_church_id,
    'Igreja ' || church_row.name || case when p_active then ' reativada.' else ' desativada.' end,
    jsonb_build_object(
      'church_id', p_church_id,
      'church_name', church_row.name,
      'active', p_active,
      'notes', p_notes
    )
  );

  return church_row;
end;
$function$
$obj2$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'admin_set_church_active_state(p_church_id uuid, p_active boolean, p_notes text)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj3$CREATE OR REPLACE FUNCTION comunhao.admin_update_church_subscription(p_church_id uuid, p_status text, p_plan_code text DEFAULT NULL::text, p_period_days integer DEFAULT NULL::integer, p_grace_days integer DEFAULT NULL::integer, p_notes text DEFAULT NULL::text)
 RETURNS church_subscriptions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  existing_record comunhao.church_subscriptions%rowtype;
  effective_plan text;
  result comunhao.church_subscriptions;
  church_row comunhao.churches%rowtype;
  now_value timestamptz := now();
  effective_period_days integer := greatest(coalesce(p_period_days, 30), 1);
  effective_grace_days integer := greatest(coalesce(p_grace_days, 7), 1);
  period_end timestamptz;
  grace_end timestamptz;
  title text;
  message text;
  notification_type text;
  priority text := 'normal';
begin
  if not comunhao.is_super_admin(auth.uid()) then
    raise exception 'Only super admins can update subscriptions.';
  end if;

  if p_status not in ('trial', 'active', 'grace_period', 'suspended', 'cancelled') then
    raise exception 'Invalid subscription status: %', p_status;
  end if;

  select *
  into church_row
  from comunhao.churches
  where id = p_church_id;

  if not found then
    raise exception 'Church not found.';
  end if;

  select *
  into existing_record
  from comunhao.church_subscriptions
  where church_id = p_church_id
  for update;

  effective_plan := coalesce(p_plan_code, existing_record.plan_code, 'starter');

  if not exists (
    select 1
    from comunhao.subscription_plans
    where code = effective_plan
  ) then
    raise exception 'Unknown subscription plan: %', effective_plan;
  end if;

  period_end := case
    when p_status in ('trial', 'active')
      then now_value + make_interval(days => effective_period_days)
    else existing_record.current_period_ends_at
  end;

  grace_end := case
    when p_status = 'grace_period'
      then now_value + make_interval(days => effective_grace_days)
    else null
  end;

  insert into comunhao.church_subscriptions (
    church_id,
    plan_code,
    status,
    trial_started_at,
    trial_ends_at,
    current_period_started_at,
    current_period_ends_at,
    grace_period_ends_at,
    activated_at,
    suspended_at,
    cancelled_at,
    updated_at,
    updated_by,
    admin_notes
  )
  values (
    p_church_id,
    effective_plan,
    p_status,
    case when p_status = 'trial' then now_value else existing_record.trial_started_at end,
    case when p_status = 'trial' then period_end else existing_record.trial_ends_at end,
    case when p_status in ('trial', 'active') then now_value else existing_record.current_period_started_at end,
    case when p_status in ('trial', 'active') then period_end else existing_record.current_period_ends_at end,
    grace_end,
    case when p_status = 'active' then now_value else existing_record.activated_at end,
    case when p_status = 'suspended' then now_value else null end,
    case when p_status = 'cancelled' then now_value else null end,
    now_value,
    auth.uid(),
    p_notes
  )
  on conflict (church_id) do update
    set
      plan_code = excluded.plan_code,
      status = excluded.status,
      trial_started_at = excluded.trial_started_at,
      trial_ends_at = excluded.trial_ends_at,
      current_period_started_at = excluded.current_period_started_at,
      current_period_ends_at = excluded.current_period_ends_at,
      grace_period_ends_at = excluded.grace_period_ends_at,
      activated_at = excluded.activated_at,
      suspended_at = excluded.suspended_at,
      cancelled_at = excluded.cancelled_at,
      updated_at = excluded.updated_at,
      updated_by = excluded.updated_by,
      admin_notes = excluded.admin_notes
  returning * into result;

  perform comunhao.sync_church_subscription_state(p_church_id);

  if p_status = 'suspended' then
    title := 'Igreja suspensa';
    message := 'A igreja ' || church_row.name || ' foi suspensa pela equipa Comunhao.';
    notification_type := 'church_suspended';
    priority := 'urgent';
  elsif p_status = 'grace_period' then
    title := 'Mais 7 dias concedidos';
    message := 'A igreja ' || church_row.name || ' recebeu mais ' || effective_grace_days || ' dias de tolerancia.';
    notification_type := 'subscription_grace_period';
    priority := 'high';
  elsif p_status in ('active', 'trial') then
    title := 'Igreja reativada';
    message := 'A subscricao da igreja ' || church_row.name || ' foi ativada pela equipa Comunhao.';
    notification_type := 'subscription_reactivated';
  elsif p_status = 'cancelled' then
    title := 'Subscricao cancelada';
    message := 'A subscricao da igreja ' || church_row.name || ' foi cancelada pela equipa Comunhao.';
    notification_type := 'subscription_cancelled';
    priority := 'high';
  end if;

  if title is not null then
    if nullif(trim(coalesce(p_notes, '')), '') is not null then
      message := message || ' Motivo: ' || trim(p_notes);
    end if;

    perform comunhao.notify_church_members(
      p_church_id,
      title,
      message,
      notification_type,
      priority,
      jsonb_build_object(
        'church_id', p_church_id,
        'church_name', church_row.name,
        'status', p_status,
        'plan_code', result.plan_code,
        'notes', p_notes,
        'grace_days', case when p_status = 'grace_period' then effective_grace_days else null end
      )
    );
  end if;

  perform comunhao.create_platform_audit_log(
    'church.subscription.updated',
    'church',
    p_church_id,
    p_church_id,
    'Subscricao da igreja ' || church_row.name || ' atualizada para ' || p_status || '.',
    jsonb_build_object(
      'church_id', p_church_id,
      'church_name', church_row.name,
      'status', p_status,
      'plan_code', result.plan_code,
      'period_days', p_period_days,
      'grace_days', p_grace_days,
      'notes', p_notes
    )
  );

  return result;
end;
$function$
$obj3$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'admin_update_church_subscription(p_church_id uuid, p_status text, p_plan_code text, p_period_days integer, p_grace_days integer, p_notes text)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj4$CREATE OR REPLACE FUNCTION comunhao.archive_internal_notification(p_notification_id uuid)
 RETURNS void
 LANGUAGE sql
