$function$
$obj4$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'archive_internal_notification(p_notification_id uuid)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj5$CREATE OR REPLACE FUNCTION comunhao.can_manage_community_feed(p_church_id uuid, check_user uuid DEFAULT auth.uid())
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
  select comunhao.has_church_role(
    p_church_id,
    array['pastor', 'church_admin', 'leader']::text[],
    coalesce(check_user, auth.uid())
  );
$function$
$obj5$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'can_manage_community_feed(p_church_id uuid, check_user uuid)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj6$CREATE OR REPLACE FUNCTION comunhao.can_view_event(p_event_id uuid, check_user uuid DEFAULT auth.uid())
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  event_row comunhao.events%rowtype;
begin
  select *
  into event_row
  from comunhao.events
  where id = p_event_id;

  if not found then
    return false;
  end if;

  if event_row.status in ('draft', 'archived') then
    return comunhao.user_has_calendar_permission(event_row.church_id, 'calendar.view', check_user);
  end if;

  if event_row.visibility in ('all', 'visitors') and event_row.is_public = true then
    return true;
  end if;

  if not exists (
    select 1
    from comunhao.memberships membership
    where membership.church_id = event_row.church_id
      and membership.profile_id = coalesce(check_user, auth.uid())
      and membership.status = 'active'
  ) then
    return false;
  end if;

  if event_row.visibility in ('members', 'leaders', 'pastors') then
    return true;
  end if;

  if event_row.visibility = 'ministry' then
    return event_row.ministry_id is null
      or exists (
        select 1
        from comunhao.ministry_members mm
        join comunhao.memberships m on m.id = mm.membership_id
        where mm.ministry_id = event_row.ministry_id
          and m.profile_id = coalesce(check_user, auth.uid())
          and m.status = 'active'
      )
      or comunhao.user_has_calendar_permission(event_row.church_id, 'calendar.view', check_user);
  end if;

  return comunhao.user_has_calendar_permission(event_row.church_id, 'calendar.view', check_user);
end;
$function$
$obj6$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'can_view_event(p_event_id uuid, check_user uuid)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj7$CREATE OR REPLACE FUNCTION comunhao.can_view_pastoral_publication(p_publication_id uuid, check_user uuid DEFAULT auth.uid())
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
  with publication as (
    select *
    from comunhao.pastoral_publications
    where id = p_publication_id
  ),
  viewer_membership as (
    select m.*
    from comunhao.memberships m
    join publication p on p.church_id = m.church_id
    where m.profile_id = coalesce(check_user, auth.uid())
      and m.status = 'active'
    limit 1
  )
  select exists (
    select 1
    from publication p
    where (
      comunhao.has_church_role(
        p.church_id,
        array['pastor', 'church_admin', 'leader']::text[],
        coalesce(check_user, auth.uid())
      )
      or (
        p.status = 'published'
        and (p.published_at is null or p.published_at <= now())
        and (p.expires_at is null or p.expires_at > now())
        and exists (select 1 from viewer_membership)
        and (
          p.visibility in ('all', 'members', 'visitors', 'youth', 'men', 'women', 'children')
          or (p.visibility = 'pastors' and exists (
            select 1 from viewer_membership vm
            where vm.role in ('pastor', 'church_admin')
          ))
          or (p.visibility = 'leaders' and exists (
            select 1 from viewer_membership vm
            where vm.role in ('pastor', 'church_admin', 'leader')
          ))
          or exists (
            select 1
            from comunhao.pastoral_publication_segments s
            left join viewer_membership vm on true
            where s.publication_id = p.id
              and (
                (s.segment_type = 'role' and s.segment_value = vm.role)
                or (s.segment_type = 'membership' and s.membership_id = vm.id)
                or (s.segment_type = 'ministry' and exists (
                  select 1
                  from comunhao.ministry_members mm
                  where mm.ministry_id = s.ministry_id
                    and mm.membership_id = vm.id
                ))
              )
          )
        )
      )
    )
  );
$function$
$obj7$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'can_view_pastoral_publication(p_publication_id uuid, check_user uuid)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj8$CREATE OR REPLACE FUNCTION comunhao.cancel_church_join_request(p_request_id uuid)
 RETURNS church_join_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  request_row comunhao.church_join_requests%rowtype;
begin
  update comunhao.church_join_requests
  set status = 'cancelled'
  where id = p_request_id
    and profile_id = auth.uid()
    and status in ('pending', 'under_review', 'more_information_required')
  returning * into request_row;

  if request_row.id is null then
    raise exception 'Join request not available.';
  end if;

  insert into comunhao.church_request_timeline (
    church_id,
    request_table,
    request_id,
    actor_profile_id,
    action,
    public_message
  )
  values (
    request_row.church_id,
    'church_join_requests',
    request_row.id,
    auth.uid(),
    'cancelled',
    'Pedido cancelado pelo utilizador.'
  );

  return request_row;
end;
$function$
$obj8$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'cancel_church_join_request(p_request_id uuid)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj9$CREATE OR REPLACE FUNCTION comunhao.cancel_event_registration(p_event_id uuid)
 RETURNS event_registrations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  event_row comunhao.events%rowtype;
  registration_row comunhao.event_registrations%rowtype;
  promoted_row comunhao.event_registrations%rowtype;
  occupied_count integer := 0;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required.';
  end if;

  select *
  into event_row
  from comunhao.events
  where id = p_event_id
  limit 1;

  update comunhao.event_registrations
  set
    status = 'cancelled',
    checked_in_at = null,
    cancelled_at = now()
  where event_id = p_event_id
    and profile_id = auth.uid()
  returning *
  into registration_row;

  if registration_row.id is null then
    raise exception 'Registration not found.';
  end if;

  if event_row.capacity is not null then
    select coalesce(sum(coalesce(attendee_count, 1)), 0)
    into occupied_count
    from comunhao.event_registrations
    where event_id = p_event_id
      and status in ('registered', 'confirmed', 'checked_in');

    if occupied_count < event_row.capacity then
      select *
      into promoted_row
      from comunhao.event_registrations
      where event_id = p_event_id
        and status = 'waiting_list'
      order by waiting_list_position nulls last, created_at
      limit 1;

      if promoted_row.id is not null then
        update comunhao.event_registrations
        set
          status = 'confirmed',
          waiting_list_position = null,
          promoted_at = now()
        where id = promoted_row.id;
      end if;
    end if;
  end if;

  return registration_row;
end;
$function$
$obj9$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'cancel_event_registration(p_event_id uuid)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj10$CREATE OR REPLACE FUNCTION comunhao.canonical_mz_phone(p_phone text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
  select case
    when regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g') like '258%'
      and length(regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g')) = 12
      then substring(regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g') from 4)
    when length(regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g')) = 9
      then regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g')
    else regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g')
  end;
$function$
$obj10$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'canonical_mz_phone(p_phone text)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj11$CREATE OR REPLACE FUNCTION comunhao.check_in_event_with_token(p_qr_payload text)
 RETURNS event_attendance
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  occurrence_uuid uuid;
  raw_token text;
  occurrence_row comunhao.event_occurrences%rowtype;
  registration_row comunhao.event_registrations%rowtype;
  attendee comunhao.event_attendance;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required.';
  end if;

  occurrence_uuid := split_part(p_qr_payload, ':', 1)::uuid;
  raw_token := split_part(p_qr_payload, ':', 2);

  select *
  into occurrence_row
  from comunhao.event_occurrences
  where id = occurrence_uuid
  for update;

  if not found then
    raise exception 'Occurrence not found.';
  end if;

  if occurrence_row.qr_closed_at is not null
    or occurrence_row.qr_expires_at is null
    or occurrence_row.qr_expires_at < now()
    or occurrence_row.qr_token_hash is distinct from encode(digest(raw_token, 'sha256'), 'hex') then
    raise exception 'Invalid or expired check-in token.';
  end if;

  if not exists (
    select 1
    from comunhao.memberships
    where church_id = occurrence_row.church_id
      and profile_id = auth.uid()
      and status = 'active'
  ) then
    raise exception 'Only active members can check in.';
  end if;

  select *
  into registration_row
  from comunhao.event_registrations
  where event_id = occurrence_row.event_id
    and profile_id = auth.uid()
  limit 1;

  if not found then
    insert into comunhao.event_registrations (
      event_id,
      occurrence_id,
      profile_id,
      status,
      checked_in_at,
      check_in_method
    )
    values (
      occurrence_row.event_id,
      occurrence_row.id,
      auth.uid(),
      'checked_in',
      now(),
      'qr'
    )
    returning * into registration_row;
  else
    update comunhao.event_registrations
    set
      occurrence_id = occurrence_row.id,
      status = 'checked_in',
      checked_in_at = coalesce(checked_in_at, now()),
      check_in_method = 'qr',
      updated_at = now()
    where id = registration_row.id
    returning * into registration_row;
  end if;

  insert into comunhao.event_attendance (
    event_id,
    occurrence_id,
    church_id,
    profile_id,
    registration_id,
    participant_type,
    check_in_method,
    checked_in_at,
    status
  )
  values (
    occurrence_row.event_id,
    occurrence_row.id,
    occurrence_row.church_id,
    auth.uid(),
    registration_row.id,
    'member',
    'qr',
    now(),
    'checked_in'
  )
  on conflict do nothing;

  select *
  into attendee
  from comunhao.event_attendance
  where event_id = occurrence_row.event_id
    and occurrence_id = occurrence_row.id
    and profile_id = auth.uid()
  limit 1;

  return attendee;
end;
