  BEGIN
    EXECUTE $obj15$CREATE OR REPLACE FUNCTION comunhao.cleanup_church_demo_data(p_church_id uuid, p_confirmation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  org_id uuid;
  summary jsonb;
begin
  if p_confirmation <> 'LIMPAR DEMO' then
    raise exception 'Confirmation text is required.';
  end if;

  select organization_id into org_id
  from comunhao.churches
  where id = p_church_id;

  if not comunhao.user_can_access_church(p_church_id, 'organization.manage', auth.uid()) then
    raise exception 'Not allowed to clean demo data.';
  end if;

  summary := comunhao.get_demo_cleanup_summary(p_church_id);

  delete from comunhao.executive_report_exports
  where organization_id = org_id
    and report_id in (select id from comunhao.executive_reports where organization_id = org_id and is_demo = true);

  delete from comunhao.executive_reports where organization_id = org_id and is_demo = true;
  delete from comunhao.executive_alerts where organization_id = org_id and is_demo = true;
  delete from comunhao.executive_goal_updates
  where goal_id in (select id from comunhao.executive_goals where organization_id = org_id and is_demo = true);
  delete from comunhao.executive_goals where organization_id = org_id and is_demo = true;
  delete from comunhao.member_transfer_requests where organization_id = org_id and is_demo = true;
  delete from comunhao.church_unit_leaderships where organization_id = org_id and is_demo = true;
  delete from comunhao.churches
  where organization_id = org_id
    and is_demo = true
    and parent_church_id is not null;

  perform comunhao.create_organization_audit_log(
    org_id,
    'demo.cleaned',
    'church_organization',
    org_id,
    p_church_id,
    'Dados de demonstracao removidos com confirmacao explicita.',
    summary,
    false
  );

  return summary;
end;
