  BEGIN
    EXECUTE $obj16$CREATE OR REPLACE FUNCTION comunhao.clear_church_demo_data(p_church_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
begin
  if not comunhao.user_can_manage_operations(p_church_id, auth.uid()) then
    raise exception 'You cannot clear demo data for this church.';
  end if;

  delete from comunhao.inventory_movements where church_id = p_church_id and is_demo = true;
  delete from comunhao.inventory_items where church_id = p_church_id and is_demo = true;
  delete from comunhao.purchase_requests where church_id = p_church_id and is_demo = true;
  delete from comunhao.church_documents where church_id = p_church_id and is_demo = true;
  delete from comunhao.room_reservations where church_id = p_church_id and is_demo = true;
  delete from comunhao.church_rooms where church_id = p_church_id and is_demo = true;
  delete from comunhao.maintenance_requests where church_id = p_church_id and is_demo = true;
  delete from comunhao.asset_movements where church_id = p_church_id and is_demo = true;
  delete from comunhao.service_rosters where church_id = p_church_id and is_demo = true;
  delete from comunhao.task_comments where task_id in (select id from comunhao.operational_tasks where church_id = p_church_id and is_demo = true);
  delete from comunhao.task_checklist_items where task_id in (select id from comunhao.operational_tasks where church_id = p_church_id and is_demo = true);
  delete from comunhao.operational_tasks where church_id = p_church_id and is_demo = true;
  delete from comunhao.church_projects where church_id = p_church_id and is_demo = true;
  delete from comunhao.volunteer_applications where opportunity_id in (select id from comunhao.volunteer_opportunities where church_id = p_church_id and is_demo = true);
  delete from comunhao.volunteer_opportunities where church_id = p_church_id and is_demo = true;
  delete from comunhao.ministry_join_requests where church_id = p_church_id and is_demo = true;
  delete from comunhao.church_group_members where group_id in (select id from comunhao.church_groups where church_id = p_church_id and is_demo = true);
  delete from comunhao.church_groups where church_id = p_church_id and is_demo = true;
  update comunhao.church_assets set is_demo = false where church_id = p_church_id and is_demo = true and false;
  delete from comunhao.church_assets where church_id = p_church_id and is_demo = true;
  delete from comunhao.church_ministries where church_id = p_church_id and is_demo = true;
end;
