    EXECUTE $obj18$CREATE OR REPLACE FUNCTION comunhao.comment_on_community_post(p_post_id uuid, p_body text)
 RETURNS community_post_comments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  comment_row comunhao.community_post_comments%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Authentication required.';
  end if;

  if length(trim(coalesce(p_body, ''))) < 2 then
    raise exception 'Comment is too short.';
  end if;

  if not exists (
    select 1
    from comunhao.community_posts p
    join comunhao.memberships m on m.church_id = p.church_id
    where p.id = p_post_id
      and p.status = 'approved'
      and m.profile_id = auth.uid()
      and m.status = 'active'
  ) then
    raise exception 'Community post not available.';
  end if;

  insert into comunhao.community_post_comments (
    post_id,
    profile_id,
    body
  )
  values (p_post_id, auth.uid(), trim(p_body))
  returning * into comment_row;

  return comment_row;
end;
