    EXECUTE $obj19$CREATE OR REPLACE FUNCTION comunhao.comment_on_community_post(p_post_id uuid, p_body text, p_parent_comment_id uuid DEFAULT NULL::uuid)
 RETURNS community_post_comments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
