  BEGIN
    EXECUTE $obj21$CREATE OR REPLACE FUNCTION comunhao.confirm_church_contribution(p_donation_id uuid, p_internal_note text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS donations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  donation_row comunhao.donations%rowtype;
  wallet_id uuid;
  balance_before_value numeric;
  balance_after_value numeric;
  ledger_id uuid;
  receipt_no text;
  validation text;
  pastor_id uuid;
begin
  select *
  into donation_row
  from comunhao.donations
  where id = p_donation_id
  for update;

  if not found then
    raise exception 'Contribution not found.';
  end if;

  if not comunhao.user_has_finance_permission(donation_row.church_id, 'finance.confirm_contribution', auth.uid()) then
    raise exception 'You cannot confirm contributions for this church.';
  end if;

  if donation_row.status = 'confirmed' then
    if exists (
      select 1
      from comunhao.wallet_ledger_entries
      where reference_table = 'donations'
        and reference_id = donation_row.id
        and status = 'posted'
    ) then
      raise exception 'Contribution is already confirmed.';
    end if;
  end if;

  if donation_row.status in ('rejected', 'cancelled', 'refunded', 'failed') then
    raise exception 'Cannot confirm a contribution with status %.', donation_row.status;
  end if;

  perform comunhao.ensure_wallet_accounts('church', donation_row.church_id, (
    select name from comunhao.churches where id = donation_row.church_id
  ));

  select id
  into wallet_id
  from comunhao.wallet_accounts
  where owner_type = 'church'
    and church_id = donation_row.church_id
    and provider = case
      when donation_row.provider in ('emola', 'mpesa') then donation_row.provider
      else 'mpesa'
    end
  limit 1;

  balance_before_value := comunhao.finance_wallet_balance(wallet_id);
  balance_after_value := balance_before_value + donation_row.amount;

  select id
  into ledger_id
  from comunhao.wallet_ledger_entries
  where reference_table = 'donations'
    and reference_id = donation_row.id
    and status = 'posted'
  limit 1;

  if ledger_id is null then
    insert into comunhao.wallet_ledger_entries (
      wallet_account_id,
      church_id,
      created_by,
      direction,
      entry_type,
      amount,
      currency,
      status,
      description,
      reference_table,
      reference_id,
      metadata,
      posted_at,
      balance_before,
      balance_after,
      idempotency_key,
      is_demo
    )
    values (
      wallet_id,
      donation_row.church_id,
      auth.uid(),
      'credit',
      donation_row.donation_type,
      donation_row.amount,
      donation_row.currency,
      'posted',
      'Contribuicao confirmada',
      'donations',
      donation_row.id,
      jsonb_build_object(
        'provider', donation_row.provider,
        'payment_method', donation_row.payment_method,
        'provider_reference', donation_row.provider_reference
      ),
      now(),
      balance_before_value,
      balance_after_value,
      coalesce(p_idempotency_key, 'donation:' || donation_row.id::text || ':confirm'),
      donation_row.is_demo
    )
    returning id into ledger_id;
  end if;

  receipt_no := coalesce(
    donation_row.receipt_number,
    'RCB-' || to_char(now(), 'YYYYMMDD') || '-' || upper(substr(replace(donation_row.id::text, '-', ''), 1, 8))
  );
  validation := coalesce(
    donation_row.validation_code,
    upper(substr(md5(donation_row.id::text || now()::text), 1, 12))
  );

  update comunhao.donations
  set
    status = 'confirmed',
    confirmed_by = auth.uid(),
    confirmed_at = coalesce(confirmed_at, now()),
    receipt_number = receipt_no,
    validation_code = validation,
    internal_notes = coalesce(nullif(trim(coalesce(p_internal_note, '')), ''), internal_notes),
    updated_at = now()
  where id = donation_row.id
  returning * into donation_row;

  insert into comunhao.finance_receipts (
    church_id,
    donation_id,
    receipt_number,
    validation_code,
    issued_by,
    payload,
    is_demo
  )
  values (
    donation_row.church_id,
    donation_row.id,
    receipt_no,
    validation,
    auth.uid(),
    jsonb_build_object(
      'amount', donation_row.amount,
      'currency', donation_row.currency,
      'type', donation_row.donation_type,
      'method', donation_row.payment_method,
      'reference', donation_row.provider_reference
    ),
    donation_row.is_demo
  )
  on conflict (receipt_number) do nothing;

  perform comunhao.finance_log_event(
    donation_row.church_id,
    'contribution.confirmed',
    'donations',
    donation_row.id,
    donation_row.amount,
    coalesce(p_idempotency_key, 'donation:' || donation_row.id::text || ':confirm'),
    jsonb_build_object('ledger_entry_id', ledger_id, 'receipt_number', receipt_no)
  );

  if donation_row.profile_id is not null then
    perform comunhao.create_internal_notification(
      donation_row.profile_id,
      'Contribuicao confirmada',
      'A sua contribuicao foi confirmada e o recibo foi emitido.',
      'contribution_confirmed',
      donation_row.church_id,
      auth.uid(),
      'normal',
      'donations',
      donation_row.id,
      '/donations',
      jsonb_build_object('receipt_number', receipt_no)
    );
  end if;

  return donation_row;
end;
$function$
$obj21$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'confirm_church_contribution(p_donation_id uuid, p_internal_note text, p_idempotency_key text)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj22$CREATE OR REPLACE FUNCTION comunhao.confirm_member_donation(p_donation_id uuid, p_provider_reference text DEFAULT NULL::text)
 RETURNS donations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  donation_row comunhao.donations%rowtype;
begin
  select *
  into donation_row
  from comunhao.donations
  where id = p_donation_id
  for update;

  if donation_row.id is null then
    raise exception 'Donation not found.';
  end if;

  if not comunhao.has_church_role(
    donation_row.church_id,
    array['pastor', 'church_admin']::text[],
    auth.uid()
  ) then
    raise exception 'Only church finance admins can confirm donations.';
  end if;

  update comunhao.donations
  set
    status = 'confirmed',
    provider_reference = coalesce(nullif(trim(coalesce(p_provider_reference, '')), ''), provider_reference),
    confirmed_at = now(),
    confirmed_by = auth.uid()
  where id = p_donation_id
  returning * into donation_row;

  update comunhao.wallet_ledger_entries
  set
    status = 'posted',
    posted_at = now(),
    description = replace(coalesce(description, 'Contribuicao'), 'aguardando confirmacao', 'confirmada')
  where reference_table = 'donations'
    and reference_id = p_donation_id
    and status = 'pending';

  update comunhao.member_wallet_ledger_entries
  set
    status = 'posted',
    posted_at = now(),
    description = 'Contribuicao confirmada.'
  where reference_table = 'donations'
    and reference_id = p_donation_id
    and status = 'pending';

  update comunhao.member_wallet_accounts mwa
  set
    pending_balance = greatest(mwa.pending_balance - donation_row.amount, 0),
    total_contributed = mwa.total_contributed + donation_row.amount,
    updated_at = now()
  where mwa.profile_id = donation_row.profile_id;

  return donation_row;
end;
$function$
$obj22$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'confirm_member_donation(p_donation_id uuid, p_provider_reference text)', SQLERRM);
  END;
  BEGIN
