  BEGIN
    EXECUTE $obj24$CREATE OR REPLACE FUNCTION comunhao.create_branch_unit(p_parent_church_id uuid, p_name text, p_unit_type text DEFAULT 'congregation'::text, p_city text DEFAULT NULL::text, p_province text DEFAULT NULL::text, p_pastor_phone text DEFAULT NULL::text, p_leader_phone text DEFAULT NULL::text, p_unit_status text DEFAULT 'active'::text, p_is_demo boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  org_id uuid;
  parent_row comunhao.churches%rowtype;
  branch_id uuid;
  pastor_id uuid;
  leader_id uuid;
  base_slug text;
begin
  select * into parent_row
  from comunhao.churches
  where id = p_parent_church_id
  limit 1;

  if parent_row.id is null then
    raise exception 'Parent church not found.';
  end if;

  org_id := comunhao.ensure_church_organization(p_parent_church_id);

  if not comunhao.user_can_access_organization(org_id, 'branch.create', auth.uid()) then
    raise exception 'Not allowed to create a congregation.';
  end if;

  base_slug := lower(regexp_replace(coalesce(nullif(trim(p_name), ''), 'congregacao'), '[^a-zA-Z0-9]+', '-', 'g'));

  insert into comunhao.churches (
    name,
    slug,
    app_name,
    tagline,
    logo_url,
    primary_color,
    secondary_color,
    phone,
    city,
    country,
    active,
    organization_id,
    parent_church_id,
    unit_type,
    unit_code,
    province,
    unit_status,
    is_demo,
    settings
  )
  values (
    trim(p_name),
    base_slug || '-' || substr(gen_random_uuid()::text, 1, 8),
    trim(p_name),
    'Congregacao ligada a ' || parent_row.name,
    parent_row.logo_url,
    parent_row.primary_color,
    parent_row.secondary_color,
    coalesce(p_pastor_phone, p_leader_phone, parent_row.phone),
    coalesce(nullif(trim(p_city), ''), parent_row.city),
    coalesce(parent_row.country, 'Mozambique'),
    p_unit_status in ('active', 'preparation', 'reorganization'),
    org_id,
    p_parent_church_id,
    coalesce(nullif(trim(p_unit_type), ''), 'congregation'),
    upper(substr(base_slug, 1, 16)) || '-' || substr(gen_random_uuid()::text, 1, 4),
    coalesce(nullif(trim(p_province), ''), parent_row.province),
    coalesce(nullif(trim(p_unit_status), ''), 'active'),
    coalesce(p_is_demo, false),
    jsonb_build_object('created_from', 'create_branch_unit')
  )
  returning id into branch_id;

  pastor_id := comunhao.profile_id_by_phone(p_pastor_phone);
  leader_id := comunhao.profile_id_by_phone(coalesce(p_leader_phone, p_pastor_phone));

  if pastor_id is not null then
    insert into comunhao.memberships (church_id, profile_id, role, status)
    values (branch_id, pastor_id, 'pastor', 'active')
    on conflict (church_id, profile_id) do update
    set role = 'pastor', status = 'active';

    insert into comunhao.church_unit_leaderships (
      church_id,
      organization_id,
      profile_id,
      role,
      permissions,
      is_demo
    )
    values (
      branch_id,
      org_id,
      pastor_id,
      'pastor_local',
      array['reports.branch.view', 'goals.manage']::text[],
      coalesce(p_is_demo, false)
    )
    on conflict (church_id, profile_id, role) do update
    set status = 'active', permissions = excluded.permissions;

    perform comunhao.create_internal_notification(
      pastor_id,
      'Congregacao atribuida',
      'Foi nomeado responsavel por ' || trim(p_name) || '.',
      'branch_assigned',
      branch_id,
      auth.uid(),
      'normal',
      'churches',
      branch_id,
      '/church/branches',
      jsonb_build_object('organization_id', org_id)
    );
  end if;

  if leader_id is not null and leader_id is distinct from pastor_id then
    insert into comunhao.memberships (church_id, profile_id, role, status)
    values (branch_id, leader_id, 'church_admin', 'active')
    on conflict (church_id, profile_id) do update
    set role = 'church_admin', status = 'active';
  end if;

  perform comunhao.create_organization_audit_log(
    org_id,
    'branch.created',
    'church',
    branch_id,
    branch_id,
    'Congregacao criada: ' || trim(p_name),
    jsonb_build_object('parent_church_id', p_parent_church_id, 'is_demo', coalesce(p_is_demo, false)),
    false
  );

  return branch_id;
end;
