      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'create_branch_unit(p_parent_church_id uuid, p_name text, p_unit_type text, p_city text, p_province text, p_pastor_phone text, p_leader_phone text, p_unit_status text, p_is_demo boolean)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj25$CREATE OR REPLACE FUNCTION comunhao.create_church_contribution(p_church_id uuid, p_contribution_type text, p_amount numeric, p_method text, p_provider text DEFAULT NULL::text, p_campaign_id uuid DEFAULT NULL::uuid, p_member_profile_id uuid DEFAULT NULL::uuid, p_payer_phone text DEFAULT NULL::text, p_reference text DEFAULT NULL::text, p_proof_url text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_confirm_immediately boolean DEFAULT false, p_idempotency_key text DEFAULT NULL::text)
 RETURNS donations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  result comunhao.donations;
  effective_status text := 'pending';
  creator uuid := auth.uid();
begin
  if creator is null then
    raise exception 'Authentication is required.';
  end if;

  if not comunhao.user_has_finance_permission(p_church_id, 'finance.view', creator)
    and not exists (
      select 1
      from comunhao.memberships
      where church_id = p_church_id
        and profile_id = creator
        and status = 'active'
    ) then
    raise exception 'You cannot create contributions for this church.';
  end if;

  if coalesce(p_amount, 0) <= 0 then
    raise exception 'Amount must be greater than zero.';
  end if;

  if p_contribution_type not in (
    'tithe',
    'offering',
    'campaign',
    'missions',
    'construction',
    'social_support',
    'event',
    'special',
    'other'
  ) then
    raise exception 'Invalid contribution type: %', p_contribution_type;
  end if;

  if p_contribution_type = 'campaign' and p_campaign_id is null then
    raise exception 'campaign_id is required for campaign contributions.';
  end if;

  if p_confirm_immediately then
    if not comunhao.user_has_finance_permission(p_church_id, 'finance.confirm_contribution', creator) then
      raise exception 'You cannot confirm contributions.';
    end if;
    effective_status := 'confirmed';
  elsif p_method in ('mpesa', 'emola') and nullif(trim(coalesce(p_reference, '')), '') is null then
    effective_status := 'provider_not_configured';
  elsif p_method in ('manual_transfer', 'bank') then
    effective_status := 'pending_manual_confirmation';
  end if;

  insert into comunhao.donations (
    church_id,
    profile_id,
    campaign_id,
    amount,
    currency,
    payment_method,
    provider,
    provider_reference,
    status,
    metadata,
    donation_type,
    contribution_type,
    proof_url,
    payer_phone,
    registered_by,
    confirmed_by,
    confirmed_at,
    internal_notes
  )
  values (
    p_church_id,
    coalesce(p_member_profile_id, creator),
    p_campaign_id,
    p_amount,
    'MZN',
    p_method,
    coalesce(p_provider, p_method),
    nullif(trim(coalesce(p_reference, '')), ''),
    effective_status,
    jsonb_build_object(
      'source', 'professional_finance',
      'idempotency_key', p_idempotency_key
    ),
    p_contribution_type,
    p_contribution_type,
    nullif(trim(coalesce(p_proof_url, '')), ''),
    nullif(trim(coalesce(p_payer_phone, '')), ''),
    creator,
    case when effective_status = 'confirmed' then creator else null end,
    case when effective_status = 'confirmed' then now() else null end,
    nullif(trim(coalesce(p_notes, '')), '')
  )
  returning * into result;

  perform comunhao.finance_log_event(
    p_church_id,
    'contribution.created',
    'donations',
    result.id,
    p_amount,
    p_idempotency_key,
    jsonb_build_object('status', effective_status, 'method', p_method)
  );

  if effective_status = 'confirmed' then
    perform comunhao.confirm_church_contribution(result.id, 'Confirmacao imediata autorizada.', p_idempotency_key);
    select * into result from comunhao.donations where id = result.id;
  end if;

  return result;
end;
