  BEGIN
    EXECUTE $obj26$CREATE OR REPLACE FUNCTION comunhao.create_church_join_request(p_church_id uuid, p_full_name text, p_phone text, p_birth_date date DEFAULT NULL::date, p_gender text DEFAULT NULL::text, p_neighborhood text DEFAULT NULL::text, p_previous_church text DEFAULT NULL::text, p_reason text DEFAULT NULL::text, p_ministry_interest text DEFAULT NULL::text, p_observation text DEFAULT NULL::text, p_consent_data_processing boolean DEFAULT false)
 RETURNS church_join_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  request_row comunhao.church_join_requests%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Authentication required.';
  end if;

  if p_consent_data_processing is not true then
    raise exception 'Consent is required.';
  end if;

  perform comunhao.ensure_member_wallet(auth.uid(), p_phone);

  insert into comunhao.church_join_requests (
    church_id,
    profile_id,
    full_name,
    phone,
    birth_date,
    gender,
    neighborhood,
    previous_church,
    reason,
    ministry_interest,
    observation,
    consent_data_processing,
    message,
    status
  )
  values (
    p_church_id,
    auth.uid(),
    trim(p_full_name),
    trim(p_phone),
    p_birth_date,
    nullif(trim(coalesce(p_gender, '')), ''),
    nullif(trim(coalesce(p_neighborhood, '')), ''),
    nullif(trim(coalesce(p_previous_church, '')), ''),
    nullif(trim(coalesce(p_reason, '')), ''),
    nullif(trim(coalesce(p_ministry_interest, '')), ''),
    nullif(trim(coalesce(p_observation, '')), ''),
    p_consent_data_processing,
    nullif(trim(coalesce(p_reason, '')), ''),
    'pending'
  )
  on conflict (church_id, profile_id) do update
  set
    full_name = excluded.full_name,
    phone = excluded.phone,
    birth_date = excluded.birth_date,
    gender = excluded.gender,
    neighborhood = excluded.neighborhood,
    previous_church = excluded.previous_church,
    reason = excluded.reason,
    ministry_interest = excluded.ministry_interest,
    observation = excluded.observation,
    consent_data_processing = excluded.consent_data_processing,
    status = case
      when comunhao.church_join_requests.status in ('approved', 'under_review', 'more_information_required') then comunhao.church_join_requests.status
      else 'pending'
    end,
    member_response = null,
    updated_at = now()
  where comunhao.church_join_requests.status not in ('approved')
  returning * into request_row;

  if request_row.id is null then
    select * into request_row
    from comunhao.church_join_requests
    where church_id = p_church_id
      and profile_id = auth.uid();
  end if;

  insert into comunhao.church_request_timeline (
    church_id,
    request_table,
    request_id,
    actor_profile_id,
    action,
    public_message
  )
  values (
    p_church_id,
    'church_join_requests',
    request_row.id,
    auth.uid(),
    'created_or_updated',
    'Pedido de entrada enviado.'
  );

  return request_row;
end;
