    EXECUTE $obj27$CREATE OR REPLACE FUNCTION comunhao.create_church_join_request(p_church_id uuid, p_request_kind text DEFAULT 'ministry'::text, p_full_name text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_birth_date date DEFAULT NULL::date, p_gender text DEFAULT NULL::text, p_neighborhood text DEFAULT NULL::text, p_previous_church text DEFAULT NULL::text, p_reason text DEFAULT NULL::text, p_ministry_interest text DEFAULT NULL::text, p_observation text DEFAULT NULL::text, p_consent_data_processing boolean DEFAULT false)
