  BEGIN
    EXECUTE $obj28$CREATE OR REPLACE FUNCTION comunhao.create_community_post(p_church_id uuid, p_post_type text, p_title text, p_body text, p_image_url text DEFAULT NULL::text)
 RETURNS community_posts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  post_row comunhao.community_posts%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Authentication required.';
  end if;

  if not exists (
    select 1
    from comunhao.memberships m
    where m.church_id = p_church_id
      and m.profile_id = auth.uid()
      and m.status = 'active'
  ) then
    raise exception 'Member is not active in this church.';
  end if;

  if length(trim(coalesce(p_title, ''))) < 3 then
    raise exception 'Title is too short.';
  end if;

  if length(trim(coalesce(p_body, ''))) < 5 then
    raise exception 'Body is too short.';
  end if;

  insert into comunhao.community_posts (
    church_id,
    author_profile_id,
    post_type,
    title,
    body,
    image_url,
    status
  )
  values (
    p_church_id,
    auth.uid(),
    coalesce(nullif(trim(p_post_type), ''), 'testimony'),
    trim(p_title),
    trim(p_body),
    nullif(trim(coalesce(p_image_url, '')), ''),
    case
      when comunhao.can_manage_community_feed(p_church_id, auth.uid()) then 'approved'
      else 'pending'
    end
  )
  returning * into post_row;

  return post_row;
end;
