    EXECUTE $obj30$CREATE OR REPLACE FUNCTION comunhao.create_community_post(p_church_id uuid, p_post_type text, p_title text, p_body text, p_image_url text DEFAULT NULL::text, p_community_space text DEFAULT NULL::text, p_media_url text DEFAULT NULL::text, p_media_type text DEFAULT NULL::text, p_media_mime_type text DEFAULT NULL::text)
 RETURNS community_posts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  post_row comunhao.community_posts%rowtype;
  normalized_space text := nullif(trim(coalesce(p_community_space, '')), '');
  normalized_media_type text := nullif(trim(coalesce(p_media_type, '')), '');
  normalized_post_type text := lower(coalesce(nullif(trim(p_post_type), ''), 'testimony'));
begin
  if auth.uid() is null then
    raise exception 'Authentication required.';
  end if;

  if normalized_space is null then
    normalized_space := 'general';
  end if;

  if normalized_post_type not in (
    'testimony',
    'verse',
    'reflection',
    'photo',
    'prayer',
    'gratitude',
    'evangelism',
    'invitation',
    'video',
    'audio',
    'document',
    'live_stream',
    'external_link',
    'announcement',
    'event',
    'campaign',
    'sermon',
    'devotional',
    'bible_study',
    'pastoral_message',
    'urgent_notice'
  ) then
    normalized_post_type := 'testimony';
  end if;

  if normalized_media_type is not null
     and normalized_media_type not in (
       'image',
       'video',
       'audio',
       'document',
       'external_link',
       'live_stream'
     ) then
    raise exception 'Unsupported community media type.';
  end if;

  if not exists (
    select 1
    from comunhao.memberships m
    where m.church_id = p_church_id
      and m.profile_id = auth.uid()
      and m.status = 'active'
  ) then
    raise exception 'Member is not active in this church.';
  end if;

  if length(trim(coalesce(p_title, ''))) < 3 then
    raise exception 'Title is too short.';
  end if;

  if length(trim(coalesce(p_body, ''))) < 3 then
    raise exception 'Body is too short.';
  end if;

  insert into comunhao.community_posts (
    church_id,
    author_profile_id,
    post_type,
    title,
    body,
    image_url,
    community_space,
    media_url,
    media_type,
    media_mime_type,
    status
  )
  values (
    p_church_id,
    auth.uid(),
    normalized_post_type,
    trim(p_title),
    trim(p_body),
    nullif(trim(coalesce(p_image_url, '')), ''),
    normalized_space,
    nullif(trim(coalesce(p_media_url, '')), ''),
    normalized_media_type,
    nullif(trim(coalesce(p_media_mime_type, '')), ''),
    'approved'
  )
  returning * into post_row;

  return post_row;
end;
