  BEGIN
    EXECUTE $obj31$CREATE OR REPLACE FUNCTION comunhao.create_internal_notification(p_recipient_profile_id uuid, p_title text, p_message text, p_notification_type text, p_church_id uuid DEFAULT NULL::uuid, p_actor_profile_id uuid DEFAULT NULL::uuid, p_priority text DEFAULT 'normal'::text, p_reference_table text DEFAULT NULL::text, p_reference_id uuid DEFAULT NULL::uuid, p_action_route text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  notification_id uuid;
  preferences_row comunhao.notification_preferences%rowtype;
begin
  if p_recipient_profile_id is null then
    raise exception 'recipient_profile_id is required.';
  end if;

  perform comunhao.ensure_notification_preferences(p_recipient_profile_id);

  select *
  into preferences_row
  from comunhao.notification_preferences
  where profile_id = p_recipient_profile_id;

  if coalesce(preferences_row.internal_enabled, true) = false
    and p_notification_type not in (
      'security',
      'payment',
      'account',
      'contribution_confirmed',
      'contribution_rejected',
      'subscription_expired'
    ) then
    return null;
  end if;

  insert into comunhao.internal_notifications (
    recipient_profile_id,
    church_id,
    actor_profile_id,
    title,
    message,
    notification_type,
    priority,
    reference_table,
    reference_id,
    action_route,
    delivery_status,
    metadata
  )
  values (
    p_recipient_profile_id,
    p_church_id,
    p_actor_profile_id,
    p_title,
    p_message,
    p_notification_type,
    p_priority,
    p_reference_table,
    p_reference_id,
    p_action_route,
    'delivered',
    coalesce(p_metadata, '{}'::jsonb)
  )
  on conflict (
    recipient_profile_id,
    notification_type,
    reference_table,
    reference_id
  )
  where reference_table is not null
    and reference_id is not null
    and archived_at is null
  do update
  set
    title = excluded.title,
    message = excluded.message,
    delivery_status = excluded.delivery_status,
    metadata = internal_notifications.metadata || excluded.metadata,
    created_at = now()
  returning id into notification_id;

  insert into comunhao.notification_delivery_attempts (
    notification_id,
    channel,
    provider,
    delivery_status,
    attempt_count,
    sent_at,
    delivered_at
  )
  values (
    notification_id,
    'in_app',
    'internal',
    'delivered',
    1,
    now(),
    now()
  )
  on conflict do nothing;

  if coalesce(preferences_row.push_enabled, true) then
    insert into comunhao.notification_delivery_attempts (
      notification_id,
      channel,
      provider,
      delivery_status,
      last_error
    )
    values (
      notification_id,
      'push',
      null,
      'provider_not_configured',
      'Push provider is not configured.'
    );
  end if;

  if coalesce(preferences_row.sms_enabled, false) then
    insert into comunhao.notification_delivery_attempts (
      notification_id,
      channel,
      provider,
      delivery_status,
      last_error
    )
    values (
      notification_id,
      'sms',
      null,
      'provider_not_configured',
      'SMS provider is not configured.'
    );
  end if;

  if coalesce(preferences_row.whatsapp_enabled, false) then
    insert into comunhao.notification_delivery_attempts (
      notification_id,
      channel,
      provider,
      delivery_status,
      last_error
    )
    values (
      notification_id,
      'whatsapp',
      null,
      'provider_not_configured',
      'WhatsApp provider is not configured.'
    );
  end if;

  if coalesce(preferences_row.email_enabled, false) then
    insert into comunhao.notification_delivery_attempts (
      notification_id,
      channel,
      provider,
      delivery_status,
      last_error
    )
    values (
      notification_id,
      'email',
      null,
      'provider_not_configured',
      'Email provider is not configured.'
    );
  end if;

  return notification_id;
end;
$function$
$obj31$;
