      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'create_internal_notification(p_recipient_profile_id uuid, p_title text, p_message text, p_notification_type text, p_church_id uuid, p_actor_profile_id uuid, p_priority text, p_reference_table text, p_reference_id uuid, p_action_route text, p_metadata jsonb)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj32$CREATE OR REPLACE FUNCTION comunhao.create_member_transfer_request(p_member_phone text, p_origin_church_id uuid, p_destination_church_id uuid, p_reason text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_is_demo boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  org_id uuid;
  member_id uuid;
  request_id uuid;
begin
  select organization_id into org_id
  from comunhao.churches
  where id = p_origin_church_id
  limit 1;

  if org_id is null then
    org_id := comunhao.ensure_church_organization(p_origin_church_id);
  end if;

  if not exists (
    select 1
    from comunhao.churches
    where id = p_destination_church_id
      and organization_id = org_id
  ) then
    raise exception 'Destination church is not in the same organization.';
  end if;

  if not comunhao.user_can_access_organization(org_id, 'branch.transfer_member', auth.uid()) then
    raise exception 'Not allowed to transfer members.';
  end if;

  member_id := comunhao.profile_id_by_phone(p_member_phone);
  if member_id is null then
    raise exception 'Member profile not found.';
  end if;

  if not exists (
    select 1
    from comunhao.memberships
    where church_id = p_origin_church_id
      and profile_id = member_id
      and status = 'active'
  ) then
    raise exception 'Active origin membership not found.';
  end if;

  insert into comunhao.member_transfer_requests (
    organization_id,
    member_profile_id,
    origin_church_id,
    destination_church_id,
    requested_by_profile_id,
    reason,
    notes,
    status,
    is_demo
  )
  values (
    org_id,
    member_id,
    p_origin_church_id,
    p_destination_church_id,
    auth.uid(),
    p_reason,
    p_notes,
    'submitted',
    coalesce(p_is_demo, false)
  )
  returning id into request_id;

  perform comunhao.create_organization_audit_log(
    org_id,
    'member_transfer.requested',
    'member_transfer_request',
    request_id,
    p_origin_church_id,
    'Transferencia de membro solicitada.',
    jsonb_build_object('destination_church_id', p_destination_church_id, 'member_profile_id', member_id),
    true
  );

  return request_id;
end;
