    EXECUTE $obj34$CREATE OR REPLACE FUNCTION comunhao.create_pastoral_request(p_church_id uuid, p_category text, p_title text, p_message text, p_urgency text DEFAULT 'normal'::text, p_privacy_level text DEFAULT 'pastor_only'::text, p_preferred_contact text DEFAULT NULL::text, p_contact_availability text DEFAULT NULL::text, p_attachment_url text DEFAULT NULL::text, p_consent_forwarding boolean DEFAULT false)
 RETURNS pastoral_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  request_row comunhao.pastoral_requests%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Authentication required.';
  end if;

  insert into comunhao.pastoral_requests (
    church_id,
    profile_id,
    request_area,
    category,
    title,
    subject,
    message,
    urgency,
    confidentiality,
    privacy_level,
    preferred_contact,
    contact_availability,
    attachment_url,
    consent_forwarding,
    hide_body_in_notifications,
    status
  )
  values (
    p_church_id,
    auth.uid(),
    'pastoral',
    p_category,
    trim(p_title),
    trim(p_title),
    trim(p_message),
    p_urgency,
    p_privacy_level,
    p_privacy_level,
    nullif(trim(coalesce(p_preferred_contact, '')), ''),
    nullif(trim(coalesce(p_contact_availability, '')), ''),
    nullif(trim(coalesce(p_attachment_url, '')), ''),
    p_consent_forwarding,
    true,
    'new'
  )
  returning * into request_row;

  insert into comunhao.church_request_timeline (
    church_id,
    request_table,
    request_id,
    actor_profile_id,
    action,
    public_message
  )
  values (
    request_row.church_id,
    'pastoral_requests',
    request_row.id,
    auth.uid(),
    'created',
    'Pedido pastoral criado.'
  );

  return request_row;
end;
