  BEGIN
    EXECUTE $obj35$CREATE OR REPLACE FUNCTION comunhao.create_platform_audit_log(p_action text, p_target_type text, p_target_id uuid DEFAULT NULL::uuid, p_church_id uuid DEFAULT NULL::uuid, p_summary text DEFAULT NULL::text, p_details jsonb DEFAULT '{}'::jsonb)
 RETURNS platform_audit_logs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  actor_row comunhao.profiles%rowtype;
  church_label text;
  result comunhao.platform_audit_logs;
begin
  if not comunhao.has_platform_role(
    array['super_admin', 'finance', 'support_agent', 'marketing', 'developer', 'auditor']::text[],
    auth.uid()
  ) then
    raise exception 'Only the platform team can write audit logs.';
  end if;

  select *
  into actor_row
  from comunhao.profiles
  where id = auth.uid()
  limit 1;

  if p_church_id is not null then
    select name
    into church_label
    from comunhao.churches
    where id = p_church_id
    limit 1;
  end if;

  insert into comunhao.platform_audit_logs (
    actor_profile_id,
    actor_name,
    actor_phone,
    action,
    target_type,
    target_id,
    church_id,
    church_name,
    summary,
    details
  )
  values (
    auth.uid(),
    actor_row.full_name,
    actor_row.phone,
    p_action,
    p_target_type,
    p_target_id,
    p_church_id,
    church_label,
    coalesce(nullif(trim(coalesce(p_summary, '')), ''), p_action),
    coalesce(p_details, '{}'::jsonb)
  )
  returning *
  into result;

  return result;
end;
