      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'create_platform_audit_log(p_action text, p_target_type text, p_target_id uuid, p_church_id uuid, p_summary text, p_details jsonb)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj36$CREATE OR REPLACE FUNCTION comunhao.create_wallet_withdrawal_request(p_owner_type text, p_provider text, p_amount numeric, p_destination_number text, p_church_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text)
 RETURNS wallet_withdrawal_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  wallet_id uuid;
  holder_name text;
  available_balance numeric;
  reserved_balance numeric;
  result comunhao.wallet_withdrawal_requests;
  receiving_method comunhao.church_receiving_methods%rowtype;
begin
  if p_owner_type not in ('platform', 'church') then
    raise exception 'Invalid wallet owner type: %', p_owner_type;
  end if;

  if p_provider not in ('mpesa', 'emola') then
    raise exception 'Invalid wallet provider: %', p_provider;
  end if;

  if coalesce(p_amount, 0) <= 0 then
    raise exception 'Amount must be greater than zero.';
  end if;

  if not comunhao.user_can_access_wallet_scope(p_owner_type, p_church_id, true, auth.uid()) then
    raise exception 'You do not have permission to request a withdrawal for this wallet.';
  end if;

  holder_name := case
    when p_owner_type = 'platform' then 'Comunhao'
    else (select name from comunhao.churches where id = p_church_id limit 1)
  end;

  perform comunhao.ensure_wallet_accounts(p_owner_type, p_church_id, holder_name);

  select id
  into wallet_id
  from comunhao.wallet_accounts
  where owner_type = p_owner_type
    and provider = p_provider
    and (
      (p_owner_type = 'platform' and church_id is null)
      or (p_owner_type = 'church' and church_id = p_church_id)
    )
  limit 1;

  if p_owner_type = 'church' then
    select *
    into receiving_method
    from comunhao.church_receiving_methods
    where church_id = p_church_id
      and method = p_provider
      and destination = trim(p_destination_number)
      and is_verified = true
    limit 1;

    if not found then
      raise exception 'Destino de levantamento nao verificado para esta igreja.';
    end if;
  end if;

  available_balance := comunhao.finance_wallet_balance(wallet_id);
  reserved_balance := comunhao.finance_reserved_balance(wallet_id);

  if (available_balance - reserved_balance) < p_amount then
    raise exception 'Insufficient balance. Available to withdraw: %', (available_balance - reserved_balance);
  end if;

  insert into comunhao.wallet_withdrawal_requests (
    wallet_account_id,
    owner_type,
    church_id,
    requested_by,
    provider,
    amount,
    currency,
    destination_number,
    destination_holder,
    destination_method_id,
    estimated_fee,
    net_amount,
    status,
    notes,
    reason,
    reserved_amount
  )
  values (
    wallet_id,
    p_owner_type,
    p_church_id,
    auth.uid(),
    p_provider,
    p_amount,
    'MZN',
    trim(p_destination_number),
    coalesce(receiving_method.holder_name, holder_name),
    receiving_method.id,
    0,
    p_amount,
    'pending',
    p_notes,
    p_notes,
    p_amount
  )
  returning * into result;

  perform comunhao.finance_log_event(
    p_church_id,
    'withdrawal.requested',
    'wallet_withdrawal_requests',
    result.id,
    p_amount,
    null,
    jsonb_build_object('provider', p_provider, 'destination', p_destination_number)
  );

  return result;
end;
$function$
$obj36$;
