    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'create_wallet_withdrawal_request(p_owner_type text, p_provider text, p_amount numeric, p_destination_number text, p_church_id uuid, p_notes text)', SQLERRM);
  END;
