  BEGIN
    EXECUTE $obj38$CREATE OR REPLACE FUNCTION comunhao.delete_my_account()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions', 'auth', 'extensions'
AS $function$
declare
  current_profile_id uuid := auth.uid();
  deleted_phone text;
  target_church_id uuid;
  church_name text;
  member_wallet comunhao.member_wallet_accounts%rowtype;
  transfer_amount numeric(12,2) := 0;
  wallet_provider text;
  church_wallet_id uuid;
begin
  if current_profile_id is null then
    raise exception 'Sessao invalida.';
  end if;

  select phone
  into deleted_phone
  from auth.users
  where id = current_profile_id
    and deleted_at is null
  limit 1;

  if not found then
    raise exception 'Conta nao encontrada ou ja apagada.';
  end if;

  select m.church_id, c.name
  into target_church_id, church_name
  from comunhao.memberships m
  join comunhao.churches c on c.id = m.church_id
  where m.profile_id = current_profile_id
  order by
    case m.status when 'active' then 0 else 1 end,
    m.created_at desc nulls last
  limit 1;

  select *
  into member_wallet
  from comunhao.member_wallet_accounts
  where profile_id = current_profile_id
  for update;

  if found then
    transfer_amount := greatest(coalesce(member_wallet.available_balance, 0), 0);
    wallet_provider := comunhao.member_wallet_provider(coalesce(member_wallet.phone, deleted_phone));
  end if;

  if transfer_amount > 0 and target_church_id is not null then
    perform comunhao.ensure_wallet_accounts('church', target_church_id, church_name);

    select id
    into church_wallet_id
    from comunhao.wallet_accounts
    where owner_type = 'church'
      and church_id = target_church_id
      and provider = wallet_provider
    limit 1;

    insert into comunhao.member_wallet_ledger_entries (
      wallet_account_id,
      profile_id,
      church_id,
      direction,
      entry_type,
      amount,
      currency,
      status,
      description,
      reference_table,
      posted_at
    )
    values (
      member_wallet.id,
      current_profile_id,
      target_church_id,
      'debit',
      'account_closure_transfer',
      transfer_amount,
      member_wallet.currency,
      'posted',
      'Saldo transferido para a conta da igreja ao apagar a conta do membro.',
      'wallet_accounts',
      now()
    );

    update comunhao.member_wallet_accounts
    set
      available_balance = 0,
      total_withdrawn = total_withdrawn + transfer_amount,
      status = 'closed',
      updated_at = now()
    where id = member_wallet.id;

    if church_wallet_id is not null then
      insert into comunhao.wallet_ledger_entries (
        wallet_account_id,
        church_id,
        created_by,
        direction,
        entry_type,
        amount,
        currency,
        status,
        description,
        reference_table,
        reference_id,
        metadata,
        posted_at
      )
      values (
        church_wallet_id,
        target_church_id,
        current_profile_id,
        'credit',
        'adjustment',
        transfer_amount,
        member_wallet.currency,
        'posted',
        'Saldo de membro transferido automaticamente ao apagar conta.',
        'member_wallet_accounts',
        member_wallet.id,
        jsonb_build_object(
          'source', 'member_account_deletion',
          'member_profile_id', current_profile_id,
          'member_phone', deleted_phone
        ),
        now()
      );
    end if;
  elsif found then
    update comunhao.member_wallet_accounts
    set status = 'closed', updated_at = now()
    where id = member_wallet.id;
  end if;

  update comunhao.memberships
  set status = 'removed'
  where profile_id = current_profile_id
    and status <> 'removed';

  delete from comunhao.push_tokens
  where profile_id = current_profile_id;

  delete from comunhao.phone_auth_otps
  where auth_user_id = current_profile_id;

  update comunhao.profiles
  set
    full_name = 'Conta apagada',
    phone = null,
    email = null,
    avatar_url = null,
    avatar_storage_path = null
  where id = current_profile_id;

  update auth.identities
  set
    provider_id = current_profile_id::text,
    identity_data = jsonb_build_object(
      'sub', current_profile_id::text,
      'deleted', true,
      'deleted_at', now()
    ),
    updated_at = now()
  where user_id = current_profile_id;

  update auth.users
  set
    phone = null,
    encrypted_password = extensions.crypt(gen_random_uuid()::text, extensions.gen_salt('bf')),
    phone_confirmed_at = null,
    raw_user_meta_data = jsonb_build_object(
      'deleted', true,
      'deleted_at', now()
    ),
    raw_app_meta_data = jsonb_build_object(
      'provider', 'phone',
      'providers', jsonb_build_array('phone'),
      'deleted', true
    ),
    deleted_at = now(),
    updated_at = now()
  where id = current_profile_id;

  return jsonb_build_object(
    'deleted', true,
    'profile_id', current_profile_id,
    'phone', deleted_phone,
    'transferred_balance', transfer_amount,
    'transfer_church_id', target_church_id
  );
end;
