  BEGIN
    EXECUTE $obj41$CREATE OR REPLACE FUNCTION comunhao.deposit_member_wallet(p_amount numeric, p_provider text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  wallet_id uuid;
  profile_phone text;
  provider text;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required.';
  end if;

  if coalesce(p_amount, 0) <= 0 then
    raise exception 'Amount must be greater than zero.';
  end if;

  select phone into profile_phone
  from comunhao.profiles
  where id = auth.uid();

  wallet_id := comunhao.ensure_member_wallet(auth.uid(), profile_phone);
  provider := coalesce(nullif(trim(coalesce(p_provider, '')), ''), comunhao.member_wallet_provider(profile_phone));

  insert into comunhao.member_wallet_ledger_entries (
    wallet_account_id,
    profile_id,
    direction,
    entry_type,
    amount,
    currency,
    status,
    description,
    reference_table,
    posted_at
  )
  values (
    wallet_id,
    auth.uid(),
    'credit',
    'deposit',
    p_amount,
    'MZN',
    'posted',
    'Deposito na conta Comunhao via ' || upper(provider) || ' usando o numero registado.',
    'member_wallet_accounts',
    now()
  );

  update comunhao.member_wallet_accounts
  set
    available_balance = available_balance + p_amount,
    total_received = total_received + p_amount,
    phone = coalesce(profile_phone, phone),
    updated_at = now()
  where id = wallet_id;

  return comunhao.get_member_wallet_summary();
end;
