  END;
  BEGIN
    EXECUTE $obj42$CREATE OR REPLACE FUNCTION comunhao.dispatch_due_event_internal_reminders(p_limit integer DEFAULT 50)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  reminder_row record;
  inserted_total integer := 0;
  inserted_count integer := 0;
begin
  for reminder_row in
    select
      er.id,
      er.event_id,
      er.occurrence_id,
      er.church_id,
      e.title,
      eo.occurrence_start_at
    from comunhao.event_reminders er
    join comunhao.events e
      on e.id = er.event_id
    left join comunhao.event_occurrences eo
      on eo.id = er.occurrence_id
    where er.channel = 'internal'
      and er.status = 'queued'
      and er.scheduled_for <= now()
      and er.provider_status = 'internal_only'
    order by er.scheduled_for
    limit greatest(coalesce(p_limit, 50), 1)
  loop
    insert into comunhao.internal_notifications (
      recipient_profile_id,
      church_id,
      title,
      message,
      notification_type,
      priority,
      reference_table,
      reference_id,
      action_route,
      delivery_status,
      metadata
    )
    select
      m.profile_id,
      reminder_row.church_id,
      'Lembrete de evento',
      'A igreja tem um evento programado: ' || reminder_row.title,
      'event_reminder',
      'normal',
      'event_reminders',
      reminder_row.id,
      '/events',
      'queued',
      jsonb_build_object(
        'event_id', reminder_row.event_id,
        'occurrence_id', reminder_row.occurrence_id,
        'occurrence_start_at', reminder_row.occurrence_start_at,
        'external_channels', 'not_configured'
      )
    from comunhao.memberships m
    where m.church_id = reminder_row.church_id
      and m.status = 'active'
      and m.profile_id is not null
    on conflict do nothing;

    get diagnostics inserted_count = row_count;
    inserted_total := inserted_total + inserted_count;

    update comunhao.event_reminders
    set
      status = 'sent',
      sent_at = now(),
      provider_status = 'internal_sent'
    where id = reminder_row.id;
  end loop;

  return inserted_total;
end;
$function$
$obj42$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'dispatch_due_event_internal_reminders(p_limit integer)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj43$CREATE OR REPLACE FUNCTION comunhao.dispatch_internal_notification_push()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions', 'vault', 'extensions'
AS $function$
declare
  project_url text;
  publishable_key text;
begin
  select decrypted_secret
  into project_url
  from vault.decrypted_secrets
  where name = 'comunhao_project_url'
  limit 1;

  select decrypted_secret
  into publishable_key
  from vault.decrypted_secrets
  where name = 'comunhao_publishable_key'
  limit 1;

  if project_url is null or publishable_key is null then
    insert into comunhao.notification_delivery_attempts (
      notification_id,
      channel,
      provider,
      delivery_status,
      last_error
    )
    values (
      new.id,
      'push',
      'firebase',
      'provider_not_configured',
      'Missing comunhao_project_url or comunhao_publishable_key in Vault.'
    );
    return new;
  end if;

  perform net.http_post(
    url := project_url || '/functions/v1/send-push-notification',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'apikey', publishable_key,
      'Authorization', 'Bearer ' || publishable_key
    ),
    body := jsonb_build_object(
      'notification_id', new.id,
      'recipient_profile_id', new.recipient_profile_id,
      'notification_type', new.notification_type
    ),
    timeout_milliseconds := 5000
  );

  return new;
exception
  when others then
    insert into comunhao.notification_delivery_attempts (
      notification_id,
      channel,
      provider,
      delivery_status,
      last_error
    )
    values (
      new.id,
      'push',
      'firebase',
      'failed',
      left(sqlerrm, 1000)
    );
    return new;
end;
