    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'dispatch_internal_notification_push()', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj44$CREATE OR REPLACE FUNCTION comunhao.ensure_church_organization(p_church_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  church_row comunhao.churches%rowtype;
  owner_id uuid;
  org_id uuid;
begin
  select * into church_row
  from comunhao.churches
  where id = p_church_id
  limit 1;

  if church_row.id is null then
    raise exception 'Church not found.';
  end if;

  if church_row.organization_id is not null then
    return church_row.organization_id;
  end if;

  select owner_profile_id into owner_id
  from comunhao.church_settings
  where church_id = p_church_id
  limit 1;

  insert into comunhao.church_organizations (
    name,
    code,
    headquarters_church_id,
    owner_profile_id,
    phone,
    email,
    province,
    city,
    primary_color,
    logo_url,
    is_demo
  )
  values (
    church_row.name,
    upper(regexp_replace(coalesce(church_row.slug, church_row.name), '[^a-zA-Z0-9]+', '-', 'g')),
    p_church_id,
    owner_id,
    church_row.phone,
    church_row.email,
    church_row.province,
    church_row.city,
    church_row.primary_color,
    church_row.logo_url,
    church_row.is_demo
  )
  on conflict (code) do update
  set headquarters_church_id = coalesce(comunhao.church_organizations.headquarters_church_id, excluded.headquarters_church_id)
  returning id into org_id;

  update comunhao.churches
  set
    organization_id = org_id,
    parent_church_id = null,
    unit_type = 'headquarters',
    unit_status = case when active then 'active' else 'suspended' end,
    unit_code = coalesce(unit_code, upper(regexp_replace(coalesce(slug, name), '[^a-zA-Z0-9]+', '-', 'g'))),
    is_demo = false
  where id = p_church_id;

  if owner_id is not null then
    insert into comunhao.church_unit_leaderships (
      church_id,
      organization_id,
      profile_id,
      role,
      permissions
    )
    values (
      p_church_id,
      org_id,
      owner_id,
      'pastor_presidente',
      array[
        'organization.view',
        'organization.manage',
        'branch.create',
        'branch.approve',
        'branch.manage',
        'branch.metrics.view',
        'branch.finance.view',
        'branch.members.view',
        'branch.transfer_member',
        'reports.consolidated.view',
        'reports.branch.view',
        'goals.manage'
      ]::text[]
    )
    on conflict (church_id, profile_id, role) do update
    set
      organization_id = excluded.organization_id,
      status = 'active',
      permissions = excluded.permissions;
  end if;

  return org_id;
end;
