  BEGIN
    EXECUTE $obj46$CREATE OR REPLACE FUNCTION comunhao.ensure_member_wallet(p_profile_id uuid, p_phone text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  wallet_id uuid;
begin
  insert into comunhao.member_wallet_accounts (profile_id, phone)
  values (p_profile_id, p_phone)
  on conflict (profile_id) do update
  set
    phone = coalesce(excluded.phone, comunhao.member_wallet_accounts.phone),
    updated_at = now()
  returning id into wallet_id;

  return wallet_id;
end;
$function$
