  BEGIN
    EXECUTE $obj52$CREATE OR REPLACE FUNCTION comunhao.generate_event_check_in_code(p_event_id uuid, p_profile_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  event_prefix text;
  candidate text;
begin
  select coalesce(
    nullif(regexp_replace(upper(coalesce(ch.join_code, ch.slug)), '[^A-Z0-9]', '', 'g'), ''),
    'EVT'
  )
  into event_prefix
  from comunhao.events evt
  join comunhao.churches ch
    on ch.id = evt.church_id
  where evt.id = p_event_id
  limit 1;

  event_prefix := substr(coalesce(event_prefix, 'EVT'), 1, 4);

  loop
    candidate := event_prefix
      || '-'
      || substr(replace(p_profile_id::text, '-', ''), 1, 4)
      || '-'
      || lpad(((random() * 9999)::int)::text, 4, '0');
    exit when not exists (
      select 1
      from comunhao.event_registrations
      where upper(check_in_code) = upper(candidate)
    );
  end loop;

  return candidate;
end;
$function$
$obj52$;
