    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'generate_event_check_in_code(p_event_id uuid, p_profile_id uuid)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj53$CREATE OR REPLACE FUNCTION comunhao.generate_event_occurrences(p_event_id uuid, p_until timestamp with time zone DEFAULT (now() + '90 days'::interval))
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  event_row comunhao.events%rowtype;
  cursor_start timestamptz;
  duration interval;
  created_count integer := 0;
  max_until timestamptz := least(coalesce(p_until, now() + interval '90 days'), now() + interval '370 days');
  frequency text;
begin
  select *
  into event_row
  from comunhao.events
  where id = p_event_id;

  if not found then
    raise exception 'Event not found.';
  end if;

  duration := coalesce(event_row.ends_at, event_row.starts_at + interval '2 hours') - event_row.starts_at;
  cursor_start := event_row.starts_at;
  frequency := lower(coalesce(event_row.recurrence_rule, 'once'));

  loop
    exit when cursor_start > max_until;

    insert into comunhao.event_occurrences (
      event_id,
      church_id,
      occurrence_start_at,
      occurrence_end_at,
      status,
      checkin_opens_at,
      checkin_closes_at,
      is_demo
    )
    values (
      event_row.id,
      event_row.church_id,
      cursor_start,
      cursor_start + duration,
      case when event_row.status in ('published', 'scheduled') then 'scheduled' else event_row.status end,
      cursor_start - interval '2 hours',
      cursor_start + duration + interval '1 hour',
      event_row.is_demo
    )
    on conflict (event_id, occurrence_start_at) do nothing;

    if found then
      created_count := created_count + 1;
    end if;

    if frequency in ('', 'once', 'none') then
      exit;
    elsif frequency like 'daily%' then
      cursor_start := cursor_start + interval '1 day';
    elsif frequency like 'biweekly%' or frequency like 'fortnightly%' then
      cursor_start := cursor_start + interval '14 days';
    elsif frequency like 'monthly%' then
      cursor_start := cursor_start + interval '1 month';
    else
      cursor_start := cursor_start + interval '7 days';
    end if;
  end loop;

  return created_count;
end;
$function$
$obj53$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'generate_event_occurrences(p_event_id uuid, p_until timestamp with time zone)', SQLERRM);
  END;
