    EXECUTE $obj55$CREATE OR REPLACE FUNCTION comunhao.generate_unique_church_slug(church_name text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  base_slug text := nullif(comunhao.slugify_text(church_name), '');
  candidate text;
  suffix integer := 1;
begin
  base_slug := coalesce(base_slug, 'igreja');
  candidate := base_slug;

  while exists (
    select 1
    from comunhao.churches
    where slug = candidate
  ) loop
    suffix := suffix + 1;
    candidate := base_slug || '-' || suffix::text;
  end loop;

  return candidate;
end;
