  BEGIN
    EXECUTE $obj56$CREATE OR REPLACE FUNCTION comunhao.generate_unique_join_code(church_name text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  prefix text;
  candidate text;
begin
  select string_agg(left(filtered.word, 1), '' order by filtered.ord)
  into prefix
  from (
    select word, ord
    from unnest(
      regexp_split_to_array(
        upper(regexp_replace(coalesce(church_name, ''), '[^A-Za-z0-9 ]', '', 'g')),
        '\s+'
      )
    ) with ordinality as words(word, ord)
    where word <> ''
      and word not in ('IGREJA', 'MINISTERIO', 'COMUNIDADE', 'CHURCH', 'DE', 'DA', 'DO', 'DOS', 'DAS')
    order by ord
    limit 3
  ) as filtered;

  prefix := upper(left(coalesce(nullif(prefix, ''), 'CMP'), 3));

  loop
    candidate := prefix || lpad((floor(random() * 100000))::int::text, 5, '0');
    exit when not exists (
      select 1
      from comunhao.churches
      where upper(join_code) = upper(candidate)
    );
  end loop;

  return candidate;
end;
$function$
$obj56$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'generate_unique_join_code(church_name text)', SQLERRM);
  END;
