    EXECUTE $obj57$CREATE OR REPLACE FUNCTION comunhao.get_active_campaigns_with_progress(p_church_id uuid)
 RETURNS TABLE(id uuid, title text, description text, image_url text, pastoral_publication_id uuid, target_amount numeric, start_at timestamp with time zone, end_at timestamp with time zone, active boolean, created_at timestamp with time zone, is_demo boolean, raised_amount numeric, contributor_count integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
  select
    campaign.id,
    campaign.title,
    campaign.description,
    campaign.image_url,
    campaign.pastoral_publication_id,
    campaign.target_amount,
    campaign.start_at,
    campaign.end_at,
    campaign.active,
    campaign.created_at,
    coalesce(campaign.is_demo, false) as is_demo,
    coalesce(
      sum(donation.amount) filter (
        where donation.status in ('confirmed', 'recorded')
          and coalesce(donation.is_demo, false) = false
      ),
      0
    ) as raised_amount,
    count(distinct donation.profile_id) filter (
      where donation.status in ('confirmed', 'recorded')
        and coalesce(donation.is_demo, false) = false
    )::integer as contributor_count
  from comunhao.donation_campaigns campaign
  left join comunhao.donations donation
    on donation.campaign_id = campaign.id
  where campaign.church_id = p_church_id
    and campaign.active = true
    and coalesce(campaign.is_demo, false) = false
  group by campaign.id
  order by campaign.created_at desc
  limit 20;
