  BEGIN
    EXECUTE $obj58$CREATE OR REPLACE FUNCTION comunhao.get_church_birthdays(p_church_id uuid, p_limit integer DEFAULT 6)
 RETURNS TABLE(profile_id uuid, full_name text, role text, birth_date date, next_birthday date)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
  with allowed as (
    select comunhao.has_church_role(
      p_church_id,
      array['member', 'leader', 'pastor', 'church_admin']::text[]
    ) as ok
  )
  select
    p.id as profile_id,
    p.full_name,
    m.role,
    p.birth_date,
    case
      when make_date(
        extract(year from current_date)::int,
        extract(month from p.birth_date)::int,
        least(
          extract(day from p.birth_date)::int,
          extract(day from (date_trunc('month', make_date(
            extract(year from current_date)::int,
            extract(month from p.birth_date)::int,
            1
          ) + interval '1 month - 1 day'))::date)::int
        )
      ) >= current_date
        then make_date(
          extract(year from current_date)::int,
          extract(month from p.birth_date)::int,
          least(
            extract(day from p.birth_date)::int,
            extract(day from (date_trunc('month', make_date(
              extract(year from current_date)::int,
              extract(month from p.birth_date)::int,
              1
            ) + interval '1 month - 1 day'))::date)::int
          )
        )
      else make_date(
        extract(year from current_date)::int + 1,
        extract(month from p.birth_date)::int,
        least(
          extract(day from p.birth_date)::int,
          extract(day from (date_trunc('month', make_date(
            extract(year from current_date)::int + 1,
            extract(month from p.birth_date)::int,
            1
          ) + interval '1 month - 1 day'))::date)::int
        )
      )
    end as next_birthday
  from comunhao.memberships m
  join comunhao.profiles p
    on p.id = m.profile_id
  cross join allowed
  where allowed.ok = true
    and m.church_id = p_church_id
    and m.status = 'active'
    and p.birth_date is not null
  order by next_birthday, p.full_name
  limit greatest(coalesce(p_limit, 6), 1);
$function$
$obj58$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'get_church_birthdays(p_church_id uuid, p_limit integer)', SQLERRM);
  END;
