    EXECUTE $obj59$CREATE OR REPLACE FUNCTION comunhao.get_church_calendar_metrics()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
begin
  if not comunhao.is_super_admin(auth.uid()) then
    raise exception 'Only super admins can view platform calendar metrics.';
  end if;

  return jsonb_build_object(
    'total_events', (select count(*) from comunhao.events where is_demo = false),
    'total_services', (select count(*) from comunhao.events where event_type in ('service', 'culto') and is_demo = false),
    'churches_with_activities', (select count(distinct church_id) from comunhao.events where starts_at >= now() - interval '30 days' and is_demo = false),
    'cancelled_events', (select count(*) from comunhao.events where status = 'cancelled' and is_demo = false),
    'future_occurrences', (select count(*) from comunhao.event_occurrences where occurrence_start_at >= now() and is_demo = false),
    'checkins', (select count(*) from comunhao.event_attendance where is_demo = false),
    'paid_events', (select count(*) from comunhao.events where payment_required = true and is_demo = false)
  );
end;
