    EXECUTE $obj61$CREATE OR REPLACE FUNCTION comunhao.get_church_contributions(p_church_id uuid, p_limit integer DEFAULT 100, p_status text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, church_id uuid, profile_id uuid, member_name text, member_phone text, campaign_id uuid, campaign_title text, amount numeric, currency text, donation_type text, payment_method text, provider text, provider_reference text, proof_url text, status text, confirmed_by uuid, confirmed_at timestamp with time zone, rejection_reason text, receipt_number text, validation_code text, is_demo boolean, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
begin
  if not comunhao.user_has_finance_permission(p_church_id, 'finance.view', auth.uid()) then
    raise exception 'You cannot view contributions for this church.';
  end if;

  return query
  select
    donation.id,
    donation.church_id,
    donation.profile_id,
    profile.full_name as member_name,
    profile.phone as member_phone,
    donation.campaign_id,
    campaign.title as campaign_title,
    donation.amount,
    donation.currency,
    donation.donation_type,
    donation.payment_method,
    donation.provider,
    donation.provider_reference,
    donation.proof_url,
    donation.status,
    donation.confirmed_by,
    donation.confirmed_at,
    donation.rejection_reason,
    donation.receipt_number,
    donation.validation_code,
    donation.is_demo,
    donation.created_at
  from comunhao.donations donation
  left join comunhao.profiles profile on profile.id = donation.profile_id
  left join comunhao.donation_campaigns campaign on campaign.id = donation.campaign_id
  where donation.church_id = p_church_id
    and (p_status is null or donation.status = p_status)
  order by donation.created_at desc
  limit greatest(coalesce(p_limit, 100), 1);
end;
