    EXECUTE $obj62$CREATE OR REPLACE FUNCTION comunhao.get_church_finance_snapshot(p_church_id uuid, p_include_demo boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  result jsonb;
begin
  if not comunhao.user_has_finance_permission(p_church_id, 'finance.view', auth.uid()) then
    raise exception 'You cannot view finance for this church.';
  end if;

  with ledger as (
    select *
    from comunhao.wallet_ledger_entries
    where church_id = p_church_id
      and (p_include_demo or is_demo = false)
  ),
  donations_scope as (
    select *
    from comunhao.donations
    where church_id = p_church_id
      and (p_include_demo or is_demo = false)
  ),
  expenses_scope as (
    select *
    from comunhao.church_expenses
    where church_id = p_church_id
      and (p_include_demo or is_demo = false)
  ),
  withdrawals_scope as (
    select *
    from comunhao.wallet_withdrawal_requests
    where church_id = p_church_id
      and (p_include_demo or is_demo = false)
  )
  select jsonb_build_object(
    'available_balance',
    coalesce(sum(case when ledger.direction = 'credit' and ledger.status = 'posted' then ledger.amount when ledger.direction = 'debit' and ledger.status = 'posted' then -ledger.amount else 0 end), 0)
      - coalesce((select sum(reserved_amount) from withdrawals_scope where status in ('pending', 'pending_second_approval', 'approved', 'processing')), 0),
    'pending_balance',
    coalesce((select sum(amount) from donations_scope where status in ('pending', 'processing', 'provider_not_configured', 'pending_manual_confirmation')), 0),
    'received_today',
    coalesce((select sum(amount) from donations_scope where status = 'confirmed' and confirmed_at >= date_trunc('day', now())), 0),
    'month_revenue',
    coalesce((select sum(amount) from donations_scope where status = 'confirmed' and confirmed_at >= date_trunc('month', now())), 0),
    'month_expenses',
    coalesce((select sum(amount) from expenses_scope where status = 'paid' and spent_at >= date_trunc('month', now())), 0),
    'month_net',
    coalesce((select sum(amount) from donations_scope where status = 'confirmed' and confirmed_at >= date_trunc('month', now())), 0)
      - coalesce((select sum(amount) from expenses_scope where status = 'paid' and spent_at >= date_trunc('month', now())), 0),
    'total_withdrawn',
    coalesce((select sum(amount) from withdrawals_scope where status in ('paid', 'completed')), 0),
    'pending_contributions',
    coalesce((select count(*) from donations_scope where status in ('pending', 'processing', 'provider_not_configured', 'pending_manual_confirmation')), 0),
    'pending_withdrawals',
    coalesce((select count(*) from withdrawals_scope where status in ('pending', 'pending_second_approval', 'approved', 'processing')), 0)
  )
  into result
  from ledger;

  return coalesce(result, '{}'::jsonb);
end;
$function$
$obj62$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'get_church_finance_snapshot(p_church_id uuid, p_include_demo boolean)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj63$CREATE OR REPLACE FUNCTION comunhao.get_community_post_comments(p_post_id uuid)
 RETURNS TABLE(id uuid, post_id uuid, profile_id uuid, parent_comment_id uuid, body text, created_at timestamp with time zone, profile jsonb)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
  select
    c.id,
    c.post_id,
    c.profile_id,
    c.parent_comment_id,
    c.body,
    c.created_at,
    jsonb_build_object(
      'full_name', p.full_name,
      'avatar_url', p.avatar_url,
      'avatar_storage_path', p.avatar_storage_path
    ) as profile
  from comunhao.community_post_comments c
  join comunhao.community_posts post on post.id = c.post_id
  left join comunhao.profiles p on p.id = c.profile_id
  where c.post_id = p_post_id
    and c.status = 'visible'
    and (
      comunhao.is_super_admin(auth.uid())
      or exists (
        select 1
        from comunhao.memberships m
        where m.church_id = post.church_id
          and m.profile_id = auth.uid()
          and m.status = 'active'
      )
    )
  order by c.created_at;
$function$
$obj63$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'get_community_post_comments(p_post_id uuid)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj64$CREATE OR REPLACE FUNCTION comunhao.get_current_legal_documents()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'document_key', document_key,
        'title', title,
        'version', version,
        'summary', summary,
        'body', body,
        'effective_at', effective_at
      )
      order by document_key
    ),
    '[]'::jsonb
  )
  from (
    select distinct on (document_key)
      document_key,
      title,
      version,
      summary,
      body,
      effective_at
    from comunhao.legal_documents
    where published = true
    order by document_key, effective_at desc, created_at desc
  ) latest;
$function$
$obj64$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'get_current_legal_documents()', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj65$CREATE OR REPLACE FUNCTION comunhao.get_current_platform_roles()
 RETURNS text[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions', 'auth'
AS $function$
declare
  official_admin_id constant uuid := 'c9c739d6-82ff-415e-af7d-581cae0fd453'::uuid;
  current_phone text;
  canonical_phone text;
  current_profile_id uuid;
begin
  current_profile_id := auth.uid();

  select coalesce(p.phone, u.phone)
    into current_phone
  from auth.users u
  left join comunhao.profiles p on p.id = u.id
  where u.id = current_profile_id;

  canonical_phone := regexp_replace(coalesce(current_phone, ''), '\D', '', 'g');
  if canonical_phone like '258%' and length(canonical_phone) = 12 then
    canonical_phone := substring(canonical_phone from 4);
  end if;

  if current_profile_id is not null
     and (canonical_phone = '841130015' or current_profile_id = official_admin_id) then
    insert into comunhao.profiles (id, full_name, phone)
    values (current_profile_id, 'Admin Comunhao', '+258841130015')
    on conflict (id) do update
      set phone = '+258841130015',
          full_name = coalesce(nullif(comunhao.profiles.full_name, ''), excluded.full_name);

    insert into comunhao.platform_roles (profile_id, role, status)
    values (current_profile_id, 'super_admin', 'active')
    on conflict (profile_id, role) do update
      set status = 'active';
  end if;

  return (
    select coalesce(array_agg(distinct pr.role order by pr.role), '{}'::text[])
    from comunhao.platform_roles pr
    where pr.profile_id = current_profile_id
      and pr.status = 'active'
  );
end;
$function$
$obj65$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'get_current_platform_roles()', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj66$CREATE OR REPLACE FUNCTION comunhao.get_demo_cleanup_summary(p_church_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  org_id uuid;
begin
  select organization_id into org_id
  from comunhao.churches
  where id = p_church_id;

  if not comunhao.user_can_access_church(p_church_id, 'organization.manage', auth.uid()) then
    raise exception 'Not allowed to inspect demo data.';
  end if;

  return jsonb_build_object(
    'demo_churches', (select count(*) from comunhao.churches where organization_id = org_id and is_demo = true),
    'demo_goals', (select count(*) from comunhao.executive_goals where organization_id = org_id and is_demo = true),
    'demo_alerts', (select count(*) from comunhao.executive_alerts where organization_id = org_id and is_demo = true),
    'demo_reports', (select count(*) from comunhao.executive_reports where organization_id = org_id and is_demo = true),
    'demo_transfers', (select count(*) from comunhao.member_transfer_requests where organization_id = org_id and is_demo = true),
    'demo_leaderships', (select count(*) from comunhao.church_unit_leaderships where organization_id = org_id and is_demo = true)
  );
end;
$function$
$obj66$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'get_demo_cleanup_summary(p_church_id uuid)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj67$CREATE OR REPLACE FUNCTION comunhao.get_event_attendance_summary(p_event_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  event_row comunhao.events%rowtype;
  result jsonb;
begin
  select *
  into event_row
  from comunhao.events
  where id = p_event_id;

  if not found then
    raise exception 'Event not found.';
  end if;

  if not comunhao.user_has_calendar_permission(event_row.church_id, 'attendance.view', auth.uid()) then
    raise exception 'You cannot view attendance for this event.';
  end if;

  select jsonb_build_object(
    'total', count(*),
    'members', count(*) filter (where participant_type in ('member', 'leader')),
    'visitors', count(*) filter (where participant_type = 'visitor'),
    'children', count(*) filter (where participant_type = 'child'),
    'manual', count(*) filter (where check_in_method = 'manual'),
    'qr', count(*) filter (where check_in_method = 'qr')
  )
  into result
  from comunhao.event_attendance
  where event_id = p_event_id
    and status = 'checked_in';

  return coalesce(result, '{}'::jsonb);
end;
$function$
$obj67$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'get_event_attendance_summary(p_event_id uuid)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj68$CREATE OR REPLACE FUNCTION comunhao.get_launch_readiness_snapshot(p_refresh boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  vida_id uuid;
  checklist jsonb;
  integrations jsonb;
  storage_items jsonb;
  vida_checks jsonb;
  demo_summary jsonb;
  blockers integer;
  critical_open integer;
  classification text;
begin
  if not comunhao.has_platform_role(array['super_admin', 'support_agent', 'developer', 'auditor']::text[], auth.uid()) then
    raise exception 'Only platform admins can view launch readiness.';
  end if;

  select id into vida_id
  from comunhao.churches
  where slug = 'vida-nova'
  limit 1;

  select coalesce(jsonb_agg(to_jsonb(i) order by i.sort_order), '[]'::jsonb)
  into checklist
  from (
    select item_key, title, category, status, responsible, notes, sort_order, is_critical, updated_at
    from comunhao.launch_checklist_items
  ) i;

  select coalesce(jsonb_agg(to_jsonb(i) order by i.category, i.title), '[]'::jsonb)
  into integrations
  from (
    select integration_key, title, category, status, environment, provider, notes, last_checked_at
    from comunhao.production_integration_status
  ) i;

  select coalesce(jsonb_agg(to_jsonb(b) order by b.id), '[]'::jsonb)
  into storage_items
  from (
    select id, public, file_size_limit, allowed_mime_types
    from storage.buckets
    where id in (
      'church-logos',
      'campaign-media',
      'finance-proofs',
      'finance-receipts',
      'church-documents',
      'asset-media',
      'profile-media',
      'request-attachments',
      'event-media',
      'pilot-feedback',
      'pastoral-publications'
    )
  ) b;

  if vida_id is not null then
    demo_summary := comunhao.get_demo_cleanup_summary(vida_id);
  else
    demo_summary := '{}'::jsonb;
  end if;

  select jsonb_build_object(
    'vida_nova_exists', vida_id is not null,
    'sara_is_owner_pastor', exists (
      select 1
      from comunhao.profiles p
      join comunhao.memberships m on m.profile_id = p.id
      join comunhao.church_settings cs on cs.church_id = m.church_id
      where comunhao.canonical_mz_phone(p.phone) = comunhao.canonical_mz_phone('877688695')
        and m.church_id = vida_id
        and m.role = 'pastor'
        and m.status = 'active'
        and cs.owner_profile_id = p.id
    ),
    'member_827688695_active', exists (
      select 1
      from comunhao.profiles p
      join comunhao.memberships m on m.profile_id = p.id
      where comunhao.canonical_mz_phone(p.phone) = comunhao.canonical_mz_phone('827688695')
        and m.church_id = vida_id
        and m.status = 'active'
    ),
    'admin_841130015_super_admin', exists (
      select 1
      from comunhao.profiles p
      join comunhao.platform_roles r on r.profile_id = p.id
      where comunhao.canonical_mz_phone(p.phone) = comunhao.canonical_mz_phone('841130015')
        and r.role = 'super_admin'
        and r.status = 'active'
    ),
    'duplicate_core_profiles', greatest((
      select count(*)
      from comunhao.profiles p
      where comunhao.canonical_mz_phone(p.phone) in ('877688695', '827688695', '841130015')
    ) - 3, 0),
    'personal_wallets_exist', (
      select count(*)
      from comunhao.member_wallet_accounts mw
      join comunhao.profiles p on p.id = mw.profile_id
      where comunhao.canonical_mz_phone(p.phone) in ('877688695', '827688695', '841130015')
    )
  ) into vida_checks;

  select count(*) into blockers
  from comunhao.launch_checklist_items
  where status = 'blocked';

  select count(*) into critical_open
  from comunhao.launch_checklist_items
  where is_critical
    and status <> 'done';

  classification := case
    when blockers > 0 then 'not_ready'
    when critical_open > 0 then 'ready_for_staging'
    when exists (select 1 from comunhao.production_integration_status where status in ('blocked', 'pending_credentials', 'not_configured')) then 'ready_for_pilot'
    else 'ready_for_production'
  end;

  return jsonb_build_object(
    'classification', classification,
    'blockers', blockers,
    'critical_open', critical_open,
    'checklist', checklist,
    'integrations', integrations,
    'storage', storage_items,
    'vida_nova', vida_checks,
    'demo_summary', demo_summary,
    'generated_at', now()
  );
end;
$function$
$obj68$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'get_launch_readiness_snapshot(p_refresh boolean)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj69$CREATE OR REPLACE FUNCTION comunhao.get_manageable_pastoral_publications(p_church_id uuid)
 RETURNS TABLE(id uuid, church_id uuid, author_user_id uuid, title text, slug text, summary text, content text, publication_type text, category text, cover_image_url text, audio_url text, video_url text, document_url text, live_stream_url text, external_url text, status text, visibility text, priority text, published_at timestamp with time zone, scheduled_at timestamp with time zone, expires_at timestamp with time zone, allow_comments boolean, allow_reactions boolean, allow_sharing boolean, send_notification boolean, is_featured boolean, is_pinned boolean, is_demo boolean, created_at timestamp with time zone, updated_at timestamp with time zone, read_count bigint, open_count bigint, saved_count bigint, reaction_count bigint, comment_count bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
  select
    p.id,
    p.church_id,
    p.author_user_id,
    p.title,
    p.slug,
    p.summary,
    p.content,
    p.publication_type,
    p.category,
    p.cover_image_url,
    p.audio_url,
    p.video_url,
    p.document_url,
    p.live_stream_url,
    p.external_url,
    p.status,
    p.visibility,
    p.priority,
    p.published_at,
    p.scheduled_at,
    p.expires_at,
    p.allow_comments,
    p.allow_reactions,
    p.allow_sharing,
    p.send_notification,
    p.is_featured,
    p.is_pinned,
    p.is_demo,
    p.created_at,
    p.updated_at,
    count(distinct r.profile_id) as read_count,
    coalesce(sum(r.open_count), 0)::bigint as open_count,
    count(distinct s.profile_id) as saved_count,
    count(distinct re.profile_id) as reaction_count,
    count(distinct c.id) filter (where c.status = 'active') as comment_count
  from comunhao.pastoral_publications p
  left join comunhao.pastoral_publication_reads r on r.publication_id = p.id
  left join comunhao.pastoral_publication_saved s on s.publication_id = p.id
  left join comunhao.pastoral_publication_reactions re on re.publication_id = p.id
  left join comunhao.pastoral_publication_comments c on c.publication_id = p.id
  where p.church_id = p_church_id
    and comunhao.has_church_role(
      p.church_id,
      array['pastor', 'church_admin', 'leader']::text[],
      auth.uid()
    )
  group by p.id
  order by p.is_pinned desc, p.created_at desc;
$function$
$obj69$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'get_manageable_pastoral_publications(p_church_id uuid)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj70$CREATE OR REPLACE FUNCTION comunhao.get_member_home_snapshot(p_church_id uuid, p_limit integer DEFAULT 24)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
  with allowed as (
    select exists (
      select 1
      from comunhao.memberships m
      where m.church_id = p_church_id
        and m.profile_id = auth.uid()
        and m.status = 'active'
    ) or comunhao.is_super_admin(auth.uid()) as ok
  ),
  limited as (
    select greatest(1, least(coalesce(p_limit, 24), 40)) as value
  )
  select jsonb_build_object(
    'announcements', coalesce((
      select jsonb_agg(to_jsonb(x) order by x.pinned desc, x.created_at desc)
      from (
        select id, title, body, image_url, pastoral_publication_id, pinned,
               published_at, created_at
        from comunhao.announcements, allowed, limited
        where allowed.ok
          and church_id = p_church_id
          and published_at is not null
        order by pinned desc, created_at desc
        limit (select value from limited)
      ) x
    ), '[]'::jsonb),
    'events', coalesce((
      select jsonb_agg(to_jsonb(x) order by x.created_at desc)
      from (
        select id, title, event_type, description, location, cover_image_url,
               pastoral_publication_id, starts_at, ends_at,
               registration_required, capacity, registration_fee_mzn,
               created_at
        from comunhao.events, allowed, limited
        where allowed.ok
          and church_id = p_church_id
          and coalesce(status, event_status, 'published') = 'published'
          and coalesce(is_demo, false) = false
          and starts_at >= now() - interval '12 hours'
        order by created_at desc
        limit (select value from limited)
      ) x
    ), '[]'::jsonb),
    'campaigns', coalesce((
      select jsonb_agg(to_jsonb(x) order by x.created_at desc)
      from (
        select c.id, c.title, c.description, c.image_url,
               c.pastoral_publication_id, c.target_amount, c.start_at,
               c.end_at, c.active, c.created_at,
               coalesce(sum(d.amount), 0) as raised_amount,
               count(distinct d.profile_id) as contributor_count
        from comunhao.donation_campaigns c
        cross join allowed
        cross join limited
        left join comunhao.donations d
          on d.campaign_id = c.id
         and d.status in ('confirmed', 'completed', 'paid')
        where allowed.ok
          and c.church_id = p_church_id
          and c.active = true
        group by c.id
        order by c.created_at desc
        limit (select value from limited)
      ) x
    ), '[]'::jsonb),
    'communications', coalesce((
      select jsonb_agg(to_jsonb(x) order by x.created_at desc)
      from (
        select cc.id, cc.church_id, cc.channel, cc.audience_type,
               cc.target_role, cc.ministry_id, cc.membership_id,
               cc.title, cc.body, cc.status, cc.scheduled_at, cc.sent_at,
               cc.created_at,
               jsonb_build_object('name', cm.name) as ministry,
               jsonb_build_object(
                 'profile',
                 jsonb_build_object('full_name', p.full_name)
               ) as membership
        from comunhao.church_communications cc
        cross join allowed
        left join comunhao.church_ministries cm on cm.id = cc.ministry_id
        left join comunhao.memberships m on m.id = cc.membership_id
        left join comunhao.profiles p on p.id = m.profile_id
        where allowed.ok
          and cc.church_id = p_church_id
          and cc.status in ('queued', 'sent')
        order by cc.created_at desc
        limit 12
      ) x
    ), '[]'::jsonb),
    'birthdays', coalesce((
      select jsonb_agg(to_jsonb(x) order by x.next_birthday)
      from (
        select m.profile_id, p.full_name, m.role, p.birth_date,
               make_date(
                 extract(year from now())::int +
                   case
                     when make_date(extract(year from now())::int,
                                    extract(month from p.birth_date)::int,
                                    least(extract(day from p.birth_date)::int, 28))
                          < current_date
                     then 1 else 0
                   end,
                 extract(month from p.birth_date)::int,
                 least(extract(day from p.birth_date)::int, 28)
               ) as next_birthday
        from comunhao.memberships m
        join comunhao.profiles p on p.id = m.profile_id
        cross join allowed
        where allowed.ok
          and m.church_id = p_church_id
          and m.status = 'active'
          and p.birth_date is not null
        order by next_birthday
        limit 6
      ) x
    ), '[]'::jsonb),
    'prayer_feed', coalesce((
      select jsonb_agg(to_jsonb(x) order by x.created_at desc)
      from (
        select pr.id, pr.church_id, pr.title, pr.description,
               pr.is_private, pr.visibility, pr.status, pr.profile_id,
               pr.anonymous_request, pr.allow_responses, pr.created_at,
               (select count(*) from comunhao.prayer_request_responses r
                 where r.prayer_request_id = pr.id) as responses
        from comunhao.prayer_requests pr, allowed
        where allowed.ok
          and pr.church_id = p_church_id
          and coalesce(pr.visibility, case when pr.is_private then 'private' else 'public' end)
              in ('public', 'anonymous')
        order by pr.created_at desc
        limit 12
      ) x
    ), '[]'::jsonb),
    'publications', coalesce((
      select jsonb_agg(to_jsonb(x) order by x.created_at desc)
      from (
        select p.id, p.church_id, p.author_user_id,
               jsonb_build_object(
                 'full_name', author.full_name,
                 'avatar_url', author.avatar_url,
                 'avatar_storage_path', author.avatar_storage_path
               ) as author,
               p.title, p.slug, p.summary, p.content, p.publication_type,
               p.category, p.cover_image_url, p.audio_url, p.video_url,
               p.document_url, p.live_stream_url, p.external_url, p.status,
               p.visibility, p.priority, p.published_at, p.scheduled_at,
               p.expires_at, p.allow_comments, p.allow_reactions,
               p.allow_sharing, p.send_notification, p.is_featured,
               p.is_pinned, p.is_demo, p.created_at, p.updated_at,
               coalesce((select sum(r.open_count) from comunhao.pastoral_publication_reads r
                         where r.publication_id = p.id), 0) as open_count,
               coalesce((select count(*) from comunhao.pastoral_publication_reads r
                         where r.publication_id = p.id), 0) as read_count,
               coalesce((select count(*) from comunhao.pastoral_publication_saved s
                         where s.publication_id = p.id), 0) as saved_count,
               coalesce((select count(*) from comunhao.pastoral_publication_reactions re
                         where re.publication_id = p.id), 0) as reaction_count,
               coalesce((select count(*) from comunhao.pastoral_publication_comments c
                         where c.publication_id = p.id and c.status = 'active'), 0) as comment_count,
               exists(select 1 from comunhao.pastoral_publication_saved s
                      where s.publication_id = p.id and s.profile_id = auth.uid()) as is_saved,
               exists(select 1 from comunhao.pastoral_publication_reads r
                      where r.publication_id = p.id and r.profile_id = auth.uid()) as is_read,
               (select re.reaction_type from comunhao.pastoral_publication_reactions re
                where re.publication_id = p.id and re.profile_id = auth.uid()
                limit 1) as my_reaction
        from comunhao.pastoral_publications p
        cross join allowed
        cross join limited
        left join comunhao.profiles author on author.id = p.author_user_id
        where allowed.ok
          and p.church_id = p_church_id
          and p.status = 'published'
          and p.published_at <= now()
          and comunhao.can_view_pastoral_publication(p.id, auth.uid())
        order by p.created_at desc
        limit (select value from limited)
      ) x
    ), '[]'::jsonb)
  );
$function$
$obj70$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'get_member_home_snapshot(p_church_id uuid, p_limit integer)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj71$CREATE OR REPLACE FUNCTION comunhao.get_member_wallet_summary()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  wallet_row comunhao.member_wallet_accounts%rowtype;
  profile_phone text;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required.';
  end if;

  select phone into profile_phone
  from comunhao.profiles
  where id = auth.uid();

  perform comunhao.ensure_member_wallet(auth.uid(), profile_phone);

  select *
  into wallet_row
  from comunhao.member_wallet_accounts
  where profile_id = auth.uid();

  return jsonb_build_object(
    'id', wallet_row.id,
    'phone', wallet_row.phone,
    'currency', wallet_row.currency,
    'available_balance', wallet_row.available_balance,
    'pending_balance', wallet_row.pending_balance,
    'total_received', wallet_row.total_received,
    'total_contributed', wallet_row.total_contributed,
    'provider', comunhao.member_wallet_provider(wallet_row.phone)
  );
end;
$function$
$obj71$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'get_member_wallet_summary()', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj72$CREATE OR REPLACE FUNCTION comunhao.get_operational_metrics(p_church_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
begin
  if not comunhao.has_church_role(p_church_id, array['member', 'leader', 'pastor', 'church_admin']::text[], auth.uid())
     and not comunhao.is_super_admin(auth.uid()) then
    raise exception 'You cannot view operational metrics for this church.';
  end if;

  return jsonb_build_object(
    'ministries_active', (select count(*) from comunhao.church_ministries where church_id = p_church_id and status = 'active' and is_demo = false),
    'groups_active', (select count(*) from comunhao.church_groups where church_id = p_church_id and status = 'active' and is_demo = false),
    'tasks_pending', (select count(*) from comunhao.operational_tasks where church_id = p_church_id and status not in ('done', 'cancelled') and is_demo = false),
    'tasks_overdue', (select count(*) from comunhao.operational_tasks where church_id = p_church_id and due_at < now() and status not in ('done', 'cancelled') and is_demo = false),
    'rosters_pending', (select count(*) from comunhao.service_rosters where church_id = p_church_id and status = 'pending_confirmation' and is_demo = false),
    'assets_maintenance', (select count(*) from comunhao.church_assets where church_id = p_church_id and status = 'maintenance' and is_demo = false),
    'maintenance_pending', (select count(*) from comunhao.maintenance_requests where church_id = p_church_id and status not in ('completed', 'cancelled') and is_demo = false),
    'documents_expiring', (select count(*) from comunhao.church_documents where church_id = p_church_id and valid_until between current_date and current_date + interval '60 days' and status = 'approved' and is_demo = false),
    'reservations_pending', (select count(*) from comunhao.room_reservations where church_id = p_church_id and status = 'pending' and is_demo = false),
    'purchases_pending', (select count(*) from comunhao.purchase_requests where church_id = p_church_id and status in ('submitted', 'reviewing', 'approved') and is_demo = false),
    'stock_low', (select count(*) from comunhao.inventory_items where church_id = p_church_id and quantity_current <= quantity_minimum and is_demo = false)
  );
end;
$function$
$obj72$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'get_operational_metrics(p_church_id uuid)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj73$CREATE OR REPLACE FUNCTION comunhao.get_organization_dashboard(p_church_id uuid, p_include_demo boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  org_id uuid;
  units jsonb;
  goals jsonb;
  alerts jsonb;
  reports jsonb;
  dashboard_metrics jsonb;
begin
  select organization_id into org_id
  from comunhao.churches
  where id = p_church_id
  limit 1;

  if org_id is null then
    org_id := comunhao.ensure_church_organization(p_church_id);
  end if;

  if not comunhao.user_can_access_organization(org_id, 'reports.consolidated.view', auth.uid()) then
    raise exception 'Not allowed to view consolidated reports.';
  end if;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', c.id,
      'name', c.name,
      'slug', c.slug,
      'unit_type', c.unit_type,
      'unit_code', c.unit_code,
      'parent_church_id', c.parent_church_id,
      'city', c.city,
      'province', c.province,
      'unit_status', c.unit_status,
      'active', c.active,
      'is_demo', c.is_demo,
      'member_count', (
        select count(*)
        from comunhao.memberships m
        where m.church_id = c.id
          and m.status = 'active'
      ),
      'pastor_name', (
        select p.full_name
        from comunhao.memberships m
        join comunhao.profiles p on p.id = m.profile_id
        where m.church_id = c.id
          and m.status = 'active'
          and m.role = 'pastor'
        order by m.created_at
        limit 1
      )
    )
    order by c.parent_church_id nulls first, c.created_at
  ), '[]'::jsonb) into units
  from comunhao.churches c
  where c.organization_id = org_id
    and (p_include_demo or c.is_demo = false);

  select jsonb_build_object(
    'total_churches', count(*),
    'active_churches', count(*) filter (where c.unit_status = 'active' and c.active),
    'preparation_churches', count(*) filter (where c.unit_status = 'preparation'),
    'total_members', coalesce(sum((
      select count(*)
      from comunhao.memberships m
      where m.church_id = c.id
        and m.status = 'active'
    )), 0),
    'active_campaigns', (
      select count(*)
      from comunhao.donation_campaigns dc
      where dc.church_id in (select id from comunhao.churches where organization_id = org_id and (p_include_demo or is_demo = false))
        and dc.active = true
    ),
    'confirmed_contributions', (
      select coalesce(sum(d.amount), 0)
      from comunhao.donations d
      where d.church_id in (select id from comunhao.churches where organization_id = org_id and (p_include_demo or is_demo = false))
        and d.status = 'confirmed'
    ),
    'monthly_revenue', (
      select coalesce(sum(w.amount), 0)
      from comunhao.wallet_ledger_entries w
      where w.church_id in (select id from comunhao.churches where organization_id = org_id and (p_include_demo or is_demo = false))
        and w.direction = 'credit'
        and w.status = 'posted'
        and date_trunc('month', w.created_at) = date_trunc('month', now())
    ),
    'monthly_expenses', (
      select coalesce(sum(e.amount), 0)
      from comunhao.church_expenses e
      where e.church_id in (select id from comunhao.churches where organization_id = org_id and (p_include_demo or is_demo = false))
        and e.status in ('approved', 'paid', 'confirmed')
        and date_trunc('month', e.spent_at) = date_trunc('month', now())
    ),
    'open_tasks', (
      select count(*)
      from comunhao.operational_tasks t
      where t.church_id in (select id from comunhao.churches where organization_id = org_id and (p_include_demo or is_demo = false))
        and t.status not in ('done', 'cancelled')
    ),
    'overdue_tasks', (
      select count(*)
      from comunhao.operational_tasks t
      where t.church_id in (select id from comunhao.churches where organization_id = org_id and (p_include_demo or is_demo = false))
        and t.status not in ('done', 'cancelled')
        and t.due_at < now()
    ),
    'open_alerts', (
      select count(*)
      from comunhao.executive_alerts a
      where a.organization_id = org_id
        and a.status = 'open'
        and (p_include_demo or a.is_demo = false)
    ),
    'goals_at_risk', (
      select count(*)
      from comunhao.executive_goals g
      where g.organization_id = org_id
        and g.status = 'at_risk'
        and (p_include_demo or g.is_demo = false)
    )
  ) into dashboard_metrics
  from comunhao.churches c
  where c.organization_id = org_id
    and (p_include_demo or c.is_demo = false);

  select coalesce(jsonb_agg(to_jsonb(g) order by g.period_end, g.created_at desc), '[]'::jsonb)
  into goals
  from (
    select id, organization_id, church_id, name, description, goal_type, source,
      initial_value, target_value, current_value, unit, period_start, period_end,
      status, milestones, notes, is_demo, created_at
    from comunhao.executive_goals
    where organization_id = org_id
      and (p_include_demo or is_demo = false)
    order by period_end, created_at desc
    limit 12
  ) g;

  select coalesce(jsonb_agg(to_jsonb(a) order by a.created_at desc), '[]'::jsonb)
  into alerts
  from (
    select id, organization_id, church_id, severity, alert_type, title, description,
      status, resolution, is_demo, created_at
    from comunhao.executive_alerts
    where organization_id = org_id
      and (p_include_demo or is_demo = false)
    order by created_at desc
    limit 12
  ) a;

  select coalesce(jsonb_agg(to_jsonb(r) order by r.generated_at desc), '[]'::jsonb)
  into reports
  from (
    select id, organization_id, church_id, report_type, title, period_start, period_end,
      filters, metrics, status, sensitive, is_demo, generated_at
    from comunhao.executive_reports
    where organization_id = org_id
      and (p_include_demo or is_demo = false)
    order by generated_at desc
    limit 8
  ) r;

  perform comunhao.create_organization_audit_log(
    org_id,
    'dashboard.viewed',
    'church_organization',
    org_id,
    p_church_id,
    'Painel consolidado consultado.',
    jsonb_build_object('include_demo', p_include_demo),
    true
  );

  return jsonb_build_object(
    'organization_id', org_id,
    'metrics', coalesce(dashboard_metrics, '{}'::jsonb),
    'units', units,
    'goals', goals,
    'alerts', alerts,
    'reports', reports
  );
end;
$function$
$obj73$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'get_organization_dashboard(p_church_id uuid, p_include_demo boolean)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj74$CREATE OR REPLACE FUNCTION comunhao.get_pastoral_publication_comments(p_publication_id uuid)
 RETURNS TABLE(id uuid, publication_id uuid, profile_id uuid, parent_comment_id uuid, body text, status text, created_at timestamp with time zone, profile jsonb)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
  select
    c.id,
    c.publication_id,
    c.profile_id,
    c.parent_comment_id,
    c.body,
    c.status,
    c.created_at,
    jsonb_build_object(
      'full_name', p.full_name,
      'avatar_url', p.avatar_url,
      'avatar_storage_path', p.avatar_storage_path
    ) as profile
  from comunhao.pastoral_publication_comments c
  left join comunhao.profiles p on p.id = c.profile_id
  where c.publication_id = p_publication_id
    and c.status = 'active'
    and comunhao.can_view_pastoral_publication(c.publication_id, auth.uid())
  order by c.created_at;
$function$
$obj74$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'get_pastoral_publication_comments(p_publication_id uuid)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj75$CREATE OR REPLACE FUNCTION comunhao.get_pilot_dashboard_snapshot(p_church_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  target_church_id uuid;
  pilot_row comunhao.pilot_programs%rowtype;
  participants jsonb;
  runs jsonb;
  feedback_summary jsonb;
  satisfaction jsonb;
begin
  if p_church_id is null then
    select id into target_church_id from comunhao.churches where slug = 'vida-nova' limit 1;
  else
    target_church_id := p_church_id;
  end if;

  if target_church_id is null then
    raise exception 'Church not found.';
  end if;

  if not (
    comunhao.has_platform_role(array['super_admin', 'support_agent', 'developer', 'auditor']::text[], auth.uid())
    or comunhao.user_can_access_church(target_church_id, 'organization.manage', auth.uid())
  ) then
    raise exception 'Not allowed to view pilot dashboard.';
  end if;

  select * into pilot_row
  from comunhao.pilot_programs
  where church_id = target_church_id
  order by created_at desc
  limit 1;

  if pilot_row.id is null then
    return jsonb_build_object('status', 'not_configured');
  end if;

  select coalesce(jsonb_agg(to_jsonb(p) order by p.participant_role, p.display_name), '[]'::jsonb)
  into participants
  from (
    select participant_role, status, phone, display_name
    from comunhao.pilot_participants
    where pilot_id = pilot_row.id
  ) p;

  select coalesce(jsonb_agg(to_jsonb(r) order by r.day_number), '[]'::jsonb)
  into runs
  from (
    select
      r.id,
      r.day_number,
      r.title,
      r.objective,
      r.status,
      r.planned_for,
      r.result_summary,
      r.blockers,
      (
        select count(*) from comunhao.pilot_daily_tasks t
        where t.daily_run_id = r.id
      ) as task_count,
      (
        select count(*) from comunhao.pilot_daily_tasks t
        where t.daily_run_id = r.id and t.status = 'done'
      ) as done_count,
      (
        select count(*) from comunhao.pilot_daily_tasks t
        where t.daily_run_id = r.id and t.status = 'blocked'
      ) as blocked_count
    from comunhao.pilot_daily_runs r
    where r.pilot_id = pilot_row.id
  ) r;

  select jsonb_build_object(
    'total', count(*),
    'open', count(*) filter (where status in ('new', 'reviewing', 'fixing')),
    'critical', count(*) filter (where severity = 'critical' and status not in ('resolved', 'closed')),
    'high', count(*) filter (where severity = 'high' and status not in ('resolved', 'closed'))
  )
  into feedback_summary
  from comunhao.pilot_feedback
  where church_id = target_church_id;

  select jsonb_build_object(
    'responses', count(*),
    'avg_recommend_score', coalesce(round(avg(recommend_score)::numeric, 1), 0)
  )
  into satisfaction
  from comunhao.pilot_satisfaction_responses
  where pilot_id = pilot_row.id;

  return jsonb_build_object(
    'pilot', to_jsonb(pilot_row),
    'participants', participants,
    'runs', runs,
    'feedback', feedback_summary,
    'satisfaction', satisfaction,
    'support_articles', (
      select count(*) from comunhao.support_articles where published = true
    ),
    'generated_at', now()
  );
end;
$function$
$obj75$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'get_pilot_dashboard_snapshot(p_church_id uuid)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj76$CREATE OR REPLACE FUNCTION comunhao.get_platform_dashboard_snapshot()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  result jsonb;
begin
  if not comunhao.is_super_admin(auth.uid()) then
    raise exception 'Only super admins can read the platform dashboard.';
  end if;

  with church_statuses as (
    select
      church.id,
      church.active,
      coalesce(subscription.plan_code, 'starter') as plan_code,
      comunhao.subscription_effective_status(
        subscription.status,
        subscription.plan_code,
        subscription.trial_ends_at,
        subscription.current_period_ends_at,
        subscription.grace_period_ends_at
      ) as effective_status,
      subscription.trial_ends_at,
      subscription.current_period_ends_at,
      subscription.grace_period_ends_at
    from comunhao.churches church
    left join comunhao.church_subscriptions subscription
      on subscription.church_id = church.id
  ),
  revenue as (
    select
      coalesce(
        sum(
          case
            when ledger.created_at >= date_trunc('month', now()) then ledger.amount
            else 0
          end
        ),
        0
      ) as month_revenue,
      coalesce(
        sum(
          case
            when ledger.created_at >= date_trunc('year', now()) then ledger.amount
            else 0
          end
        ),
        0
      ) as year_revenue,
      coalesce(
        sum(
          case
            when ledger.created_at >= date_trunc('month', now())
              and coalesce(ledger.metadata->>'plan_code', '') = 'starter'
            then ledger.amount
            else 0
          end
        ),
        0
      ) as starter_revenue,
      coalesce(
        sum(
          case
            when ledger.created_at >= date_trunc('month', now())
              and coalesce(ledger.metadata->>'plan_code', '') = 'essential'
            then ledger.amount
            else 0
          end
        ),
        0
      ) as essential_revenue,
      coalesce(
        sum(
          case
            when ledger.created_at >= date_trunc('month', now())
              and coalesce(ledger.metadata->>'plan_code', '') = 'premium'
            then ledger.amount
            else 0
          end
        ),
        0
      ) as premium_revenue
    from comunhao.wallet_ledger_entries ledger
    join comunhao.wallet_accounts wallet
      on wallet.id = ledger.wallet_account_id
    where wallet.owner_type = 'platform'
      and wallet.church_id is null
      and ledger.direction = 'credit'
      and ledger.status = 'posted'
      and ledger.entry_type = 'subscription_payment'
  )
  select jsonb_build_object(
    'total_churches',
    (select count(*) from church_statuses),
    'active_churches',
    (
      select count(*)
      from church_statuses
      where active = true
        and effective_status not in ('suspended', 'cancelled')
    ),
    'inactive_churches',
    (
      select count(*)
      from church_statuses
      where active = false
         or effective_status in ('suspended', 'cancelled')
    ),
    'total_members',
    (
      select count(*)
      from comunhao.memberships
      where status = 'active'
    ),
    'total_pastors',
    (
      select count(*)
      from comunhao.memberships
      where status = 'active'
        and role = 'pastor'
    ),
    'pending_applications',
    (
      select count(*)
      from comunhao.church_applications
      where status = 'submitted'
    ),
    'pending_plan_requests',
    (
      select count(*)
      from comunhao.church_subscription_requests
      where status = 'pending'
    ),
    'pending_withdrawals',
    (
      select count(*)
      from comunhao.wallet_withdrawal_requests
      where status in ('pending', 'processing')
    ),
    'month_revenue',
    revenue.month_revenue,
    'year_revenue',
    revenue.year_revenue,
    'trial_churches',
    (
      select count(*)
      from church_statuses
      where effective_status = 'trial'
    ),
    'grace_churches',
    (
      select count(*)
      from church_statuses
      where effective_status = 'grace_period'
    ),
    'suspended_churches',
    (
      select count(*)
      from church_statuses
      where effective_status in ('suspended', 'cancelled')
    ),
    'expiring_soon_subscriptions',
    (
      select count(*)
      from church_statuses
      where effective_status in ('trial', 'active', 'grace_period')
        and (
          case
            when effective_status = 'trial' then trial_ends_at
            when effective_status = 'active' then current_period_ends_at
            when effective_status = 'grace_period' then coalesce(
              grace_period_ends_at,
              current_period_ends_at + interval '7 days',
              trial_ends_at + interval '7 days'
            )
            else null
          end
        ) between now() and now() + interval '7 days'
    ),
    'starter_revenue',
    revenue.starter_revenue,
    'essential_revenue',
    revenue.essential_revenue,
    'premium_revenue',
    revenue.premium_revenue
  )
  into result
  from revenue;

  return result;
end;
