  BEGIN
    EXECUTE $obj77$CREATE OR REPLACE FUNCTION comunhao.get_platform_operational_metrics()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
begin
  if not comunhao.has_platform_role(
    array['super_admin', 'support_agent', 'developer', 'auditor']::text[],
    auth.uid()
  ) then
    raise exception 'Only platform staff can view operational metrics.';
  end if;

  return jsonb_build_object(
    'ministries', (select count(*) from comunhao.church_ministries where is_demo = false),
    'groups', (select count(*) from comunhao.church_groups where is_demo = false),
    'tasks_open', (select count(*) from comunhao.operational_tasks where status not in ('done', 'cancelled') and is_demo = false),
    'tasks_overdue', (select count(*) from comunhao.operational_tasks where due_at < now() and status not in ('done', 'cancelled') and is_demo = false),
    'rosters_pending', (select count(*) from comunhao.service_rosters where status = 'pending_confirmation' and is_demo = false),
    'assets', (select count(*) from comunhao.church_assets where is_demo = false),
    'assets_maintenance', (select count(*) from comunhao.church_assets where status = 'maintenance' and is_demo = false),
    'purchase_requests_pending', (select count(*) from comunhao.purchase_requests where status in ('submitted', 'reviewing', 'approved') and is_demo = false),
    'volunteer_opportunities_open', (select count(*) from comunhao.volunteer_opportunities where status = 'open' and is_demo = false),
    'join_requests_pending', (select count(*) from comunhao.ministry_join_requests where status in ('pending', 'reviewing', 'interview_required') and is_demo = false)
  );
end;
