  BEGIN
    EXECUTE $obj78$CREATE OR REPLACE FUNCTION comunhao.get_visible_birthdays(p_church_id uuid, p_days integer DEFAULT 31)
 RETURNS TABLE(profile_id uuid, full_name text, phone text, birth_date date, days_until integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
begin
  if not comunhao.has_church_role(
    p_church_id,
    array['member', 'leader', 'pastor', 'church_admin']::text[],
    auth.uid()
  ) then
    raise exception 'You cannot view birthdays for this church.';
  end if;

  return query
  with birthday_base as (
    select
      profile.id,
      profile.full_name,
      profile.phone,
      profile.birth_date,
      make_date(
        extract(year from current_date)::int,
        extract(month from profile.birth_date)::int,
        least(
          extract(day from profile.birth_date)::int,
          extract(
            day from (
              date_trunc(
                'month',
                make_date(
                  extract(year from current_date)::int,
                  extract(month from profile.birth_date)::int,
                  1
                )
              ) + interval '1 month - 1 day'
            )
          )::int
        )
      ) as birthday_this_year
    from comunhao.memberships membership
    join comunhao.profiles profile on profile.id = membership.profile_id
    where membership.church_id = p_church_id
      and membership.status = 'active'
      and profile.birth_date is not null
  ),
  birthday_next as (
    select
      birthday_base.*,
      case
        when birthday_base.birthday_this_year < current_date
          then birthday_base.birthday_this_year + interval '1 year'
        else birthday_base.birthday_this_year
      end as next_birthday
    from birthday_base
  )
  select
    birthday_next.id,
    birthday_next.full_name,
    case
      when comunhao.user_has_calendar_permission(p_church_id, 'birthday.view', auth.uid())
        then birthday_next.phone
      else null
    end as phone,
    birthday_next.birth_date,
    (birthday_next.next_birthday::date - current_date)::int as days_until
  from birthday_next
  order by days_until
  limit greatest(coalesce(p_days, 31), 1);
end;
$function$
$obj78$;
