    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'get_visible_birthdays(p_church_id uuid, p_days integer)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj79$CREATE OR REPLACE FUNCTION comunhao.get_wallet_dashboard(p_owner_type text, p_church_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(provider text, balance numeric, total_credits numeric, total_debits numeric, incoming_today numeric, incoming_month numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
begin
  if not comunhao.user_can_access_wallet_scope(p_owner_type, p_church_id, false, auth.uid()) then
    raise exception 'You do not have access to this wallet.';
  end if;

  return query
  select
    wa.provider,
    coalesce(
      sum(
        case
          when le.direction = 'credit' and le.status = 'posted' then le.amount
          when le.direction = 'debit' and le.status = 'posted' then -le.amount
          else 0
        end
      ),
      0
    ) as balance,
    coalesce(
      sum(
        case
          when le.direction = 'credit' and le.status = 'posted' then le.amount
          else 0
        end
      ),
      0
    ) as total_credits,
    coalesce(
      sum(
        case
          when le.direction = 'debit' and le.status = 'posted' then le.amount
          else 0
        end
      ),
      0
    ) as total_debits,
    coalesce(
      sum(
        case
          when le.direction = 'credit'
            and le.status = 'posted'
            and le.created_at >= date_trunc('day', now())
          then le.amount
          else 0
        end
      ),
      0
    ) as incoming_today,
    coalesce(
      sum(
        case
          when le.direction = 'credit'
            and le.status = 'posted'
            and le.created_at >= date_trunc('month', now())
          then le.amount
          else 0
        end
      ),
      0
    ) as incoming_month
  from comunhao.wallet_accounts wa
  left join comunhao.wallet_ledger_entries le
    on le.wallet_account_id = wa.id
  where wa.owner_type = p_owner_type
    and (
      (p_owner_type = 'platform' and wa.church_id is null)
      or (p_owner_type = 'church' and wa.church_id = p_church_id)
    )
  group by wa.provider, wa.sort_order
  order by wa.sort_order, wa.provider;
end;
$function$
$obj79$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'get_wallet_dashboard(p_owner_type text, p_church_id uuid)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj80$CREATE OR REPLACE FUNCTION comunhao.get_wallet_ledger(p_owner_type text, p_church_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50)
 RETURNS TABLE(id uuid, wallet_account_id uuid, provider text, direction text, entry_type text, amount numeric, currency text, status text, description text, reference_table text, reference_id uuid, created_at timestamp with time zone, posted_at timestamp with time zone, sender_name text, sender_phone text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
begin
  if not comunhao.user_can_access_wallet_scope(p_owner_type, p_church_id, false, auth.uid()) then
    raise exception 'You do not have access to this wallet.';
  end if;

  return query
  select
    le.id,
    le.wallet_account_id,
    wa.provider,
    le.direction,
    le.entry_type,
    le.amount,
    le.currency,
    le.status,
    le.description,
    le.reference_table,
    le.reference_id,
    le.created_at,
    le.posted_at,
    case
      when le.direction = 'credit' then nullif(trim(coalesce(
        donor.full_name,
        donation.anonymous_name,
        le.metadata ->> 'sender_name',
        le.metadata ->> 'member_name',
        actor.full_name
      )), '')
      else nullif(trim(coalesce(actor.full_name, le.metadata ->> 'actor_name')), '')
    end as sender_name,
    case
      when le.direction = 'credit' then nullif(trim(coalesce(
        donation.payer_phone,
        donor.phone,
        le.metadata ->> 'sender_phone',
        le.metadata ->> 'member_phone',
        actor.phone
      )), '')
      else nullif(trim(coalesce(actor.phone, le.metadata ->> 'actor_phone')), '')
    end as sender_phone
  from comunhao.wallet_ledger_entries le
  join comunhao.wallet_accounts wa
    on wa.id = le.wallet_account_id
  left join comunhao.donations donation
    on le.reference_table = 'donations'
   and donation.id = le.reference_id
  left join comunhao.profiles donor
    on donor.id = donation.profile_id
  left join comunhao.profiles actor
    on actor.id = le.created_by
  where wa.owner_type = p_owner_type
    and (
      (p_owner_type = 'platform' and wa.church_id is null)
      or (p_owner_type = 'church' and wa.church_id = p_church_id)
    )
  order by le.created_at desc
  limit greatest(coalesce(p_limit, 50), 1);
end;
$function$
$obj80$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'get_wallet_ledger(p_owner_type text, p_church_id uuid, p_limit integer)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj81$CREATE OR REPLACE FUNCTION comunhao.get_wallet_withdrawal_requests(p_owner_type text DEFAULT NULL::text, p_church_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50)
 RETURNS TABLE(id uuid, owner_type text, church_id uuid, church_name text, provider text, amount numeric, currency text, destination_number text, status text, notes text, created_at timestamp with time zone, processed_at timestamp with time zone, completed_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
begin
  if p_owner_type = 'platform' then
    if not comunhao.is_super_admin(auth.uid()) then
      raise exception 'You do not have access to the platform withdrawal queue.';
    end if;
  elsif p_owner_type = 'church' then
    if not comunhao.user_can_access_wallet_scope('church', p_church_id, false, auth.uid()) then
      raise exception 'You do not have access to this church withdrawal queue.';
    end if;
  elsif p_owner_type is null then
    if not comunhao.is_super_admin(auth.uid()) then
      raise exception 'Only super admins can view all withdrawal requests.';
    end if;
  else
    raise exception 'Invalid owner_type filter: %', p_owner_type;
  end if;

  return query
  select
    wr.id,
    wr.owner_type,
    wr.church_id,
    c.name as church_name,
    wr.provider,
    wr.amount,
    wr.currency,
    wr.destination_number,
    wr.status,
    wr.notes,
    wr.created_at,
    wr.processed_at,
    wr.completed_at
  from comunhao.wallet_withdrawal_requests wr
  left join comunhao.churches c
    on c.id = wr.church_id
  where (p_owner_type is null or wr.owner_type = p_owner_type)
    and (p_church_id is null or wr.church_id = p_church_id)
  order by wr.created_at desc
  limit greatest(coalesce(p_limit, 50), 1);
end;
