    EXECUTE $obj88$CREATE OR REPLACE FUNCTION comunhao.handle_event_registration_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
begin
  if new.check_in_code is null or btrim(new.check_in_code) = '' then
    new.check_in_code := comunhao.generate_event_check_in_code(
      new.event_id,
      new.profile_id
    );
  end if;

  if new.attendee_count is null or new.attendee_count < 1 then
    new.attendee_count := 1;
  end if;

  if new.checked_in_at is not null then
    new.status := 'checked_in';
  elsif new.status not in (
    'registered',
    'waiting_list',
    'confirmed',
    'cancelled',
    'checked_in',
    'no_show'
  ) then
    new.status := 'confirmed';
  end if;

  new.updated_at := now();
  return new;
end;
