  BEGIN
    EXECUTE $obj90$CREATE OR REPLACE FUNCTION comunhao.handle_new_auth_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  metadata_church_id uuid;
  metadata_birth_date date;
begin
  begin
    if coalesce(new.raw_user_meta_data ->> 'church_id', '') <> '' then
      metadata_church_id := (new.raw_user_meta_data ->> 'church_id')::uuid;
    elsif coalesce(new.raw_user_meta_data ->> 'church_slug', '') <> '' then
      select id
      into metadata_church_id
      from comunhao.churches
      where slug = new.raw_user_meta_data ->> 'church_slug'
      limit 1;
    end if;
  exception
    when others then
      metadata_church_id := null;
  end;

  begin
    if coalesce(new.raw_user_meta_data ->> 'birth_date', '') <> '' then
      metadata_birth_date := (new.raw_user_meta_data ->> 'birth_date')::date;
    end if;
  exception
    when others then
      metadata_birth_date := null;
  end;

  update comunhao.profiles
  set
    full_name = coalesce(new.raw_user_meta_data ->> 'full_name', 'Membro'),
    phone = new.phone,
    birth_date = coalesce(metadata_birth_date, comunhao.profiles.birth_date)
  where id = new.id;

  if not found then
    insert into comunhao.profiles (
      id,
      full_name,
      phone,
      birth_date
    )
    values (
      new.id,
      coalesce(new.raw_user_meta_data ->> 'full_name', 'Membro'),
      new.phone,
      metadata_birth_date
    );
  end if;

  if metadata_church_id is not null then
    update comunhao.memberships
    set
      status = 'active',
      role = comunhao.memberships.role
    where church_id = metadata_church_id
      and profile_id = new.id;

    if not found then
      insert into comunhao.memberships (
        church_id,
        profile_id,
        role,
        status
      )
      values (
        metadata_church_id,
        new.id,
        'member',
        'active'
      );
    end if;
  end if;

  return new;
end;
$function$
$obj90$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'handle_new_auth_user()', SQLERRM);
  END;
