  BEGIN
    EXECUTE $obj98$CREATE OR REPLACE FUNCTION comunhao.list_public_churches_with_member_counts(p_query text DEFAULT NULL::text, p_limit integer DEFAULT 50)
 RETURNS TABLE(id uuid, name text, slug text, join_code text, app_name text, logo_url text, primary_color text, secondary_color text, phone text, email text, city text, country text, tagline text, hero_title text, hero_subtitle text, default_currency text, subscription_status text, trial_ends_at timestamp with time zone, subscription_ends_at timestamp with time zone, active_member_count bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
  with search_input as (
    select
      nullif(trim(coalesce(p_query, '')), '') as text_query,
      nullif(regexp_replace(coalesce(p_query, ''), '\D', '', 'g'), '') as digit_query
  )
  select
    c.id,
    c.name,
    c.slug,
    c.join_code,
    c.app_name,
    c.logo_url,
    c.primary_color,
    c.secondary_color,
    c.phone,
    c.email,
    c.city,
    c.country,
    c.tagline,
    c.hero_title,
    c.hero_subtitle,
    c.default_currency,
    c.subscription_status,
    c.trial_ends_at,
    c.subscription_ends_at,
    count(m.id) filter (
      where m.status = 'active'
        and coalesce(m.role, 'member') = 'member'
    ) as active_member_count
  from comunhao.churches c
  cross join search_input s
  left join comunhao.memberships m on m.church_id = c.id
  where c.active = true
    and (
      s.text_query is null
      or c.name ilike '%' || s.text_query || '%'
      or c.slug ilike '%' || s.text_query || '%'
      or c.join_code ilike '%' || s.text_query || '%'
      or c.phone ilike '%' || s.text_query || '%'
      or (
        s.digit_query is not null
        and regexp_replace(coalesce(c.phone, ''), '\D', '', 'g')
          ilike '%' || s.digit_query || '%'
      )
    )
  group by c.id
  order by c.name
  limit greatest(1, least(coalesce(p_limit, 50), 100));
$function$
$obj98$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'list_public_churches_with_member_counts(p_query text, p_limit integer)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj99$CREATE OR REPLACE FUNCTION comunhao.maintain_event_occurrences_all()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  event_row record;
  total_created integer := 0;
begin
  for event_row in
    select id
    from comunhao.events
    where is_demo = false
      and status in ('published', 'scheduled', 'ongoing')
      and starts_at <= now() + interval '120 days'
  loop
    total_created := total_created
      + comunhao.generate_event_occurrences(
          event_row.id,
          now() + interval '120 days'
        );
  end loop;

  return total_created;
end;
$function$
$obj99$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'maintain_event_occurrences_all()', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj100$CREATE OR REPLACE FUNCTION comunhao.manual_check_in_event(p_event_id uuid, p_profile_id uuid DEFAULT NULL::uuid, p_visitor_name text DEFAULT NULL::text, p_visitor_phone text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS event_attendance
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  event_row comunhao.events%rowtype;
  occurrence_row comunhao.event_occurrences%rowtype;
  visitor_row comunhao.church_visitors%rowtype;
  attendee comunhao.event_attendance;
begin
  select *
  into event_row
  from comunhao.events
  where id = p_event_id;

  if not found then
    raise exception 'Event not found.';
  end if;

  if not comunhao.user_has_calendar_permission(event_row.church_id, 'attendance.manage', auth.uid()) then
    raise exception 'You cannot manage attendance for this event.';
  end if;

  perform comunhao.generate_event_occurrences(p_event_id, event_row.starts_at + interval '1 day');

  select *
  into occurrence_row
  from comunhao.event_occurrences
  where event_id = p_event_id
  order by abs(extract(epoch from (occurrence_start_at - now())))
  limit 1;

  if p_profile_id is null then
    if nullif(trim(coalesce(p_visitor_name, '')), '') is null then
      raise exception 'Visitor name is required for visitor check-in.';
    end if;

    insert into comunhao.church_visitors (
      church_id,
      full_name,
      phone,
      status,
      first_visit_at,
      notes
    )
    values (
      event_row.church_id,
      trim(p_visitor_name),
      nullif(trim(coalesce(p_visitor_phone, '')), ''),
      'new',
      now(),
      p_notes
    )
    on conflict do nothing;

    select *
    into visitor_row
    from comunhao.church_visitors
    where church_id = event_row.church_id
      and full_name = trim(p_visitor_name)
      and (
        p_visitor_phone is null
        or phone = nullif(trim(coalesce(p_visitor_phone, '')), '')
      )
    order by created_at desc
    limit 1;
  end if;

  insert into comunhao.event_attendance (
    event_id,
    occurrence_id,
    church_id,
    profile_id,
    visitor_id,
    participant_type,
    check_in_method,
    checked_in_by,
    notes
  )
  values (
    event_row.id,
    occurrence_row.id,
    event_row.church_id,
    p_profile_id,
    visitor_row.id,
    case when p_profile_id is null then 'visitor' else 'member' end,
    'manual',
    auth.uid(),
    p_notes
  )
  on conflict do nothing;

  select *
  into attendee
  from comunhao.event_attendance
  where event_id = event_row.id
    and coalesce(occurrence_id, '00000000-0000-0000-0000-000000000000'::uuid) = coalesce(occurrence_row.id, '00000000-0000-0000-0000-000000000000'::uuid)
    and (
      (p_profile_id is not null and profile_id = p_profile_id)
      or (p_profile_id is null and visitor_id = visitor_row.id)
    )
  limit 1;

  return attendee;
end;
$function$
$obj100$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'manual_check_in_event(p_event_id uuid, p_profile_id uuid, p_visitor_name text, p_visitor_phone text, p_notes text)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj101$CREATE OR REPLACE FUNCTION comunhao.manual_child_check_in_event(p_event_id uuid, p_occurrence_id uuid DEFAULT NULL::uuid, p_child_name text DEFAULT NULL::text, p_guardian_name text DEFAULT NULL::text, p_guardian_phone text DEFAULT NULL::text, p_room_name text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS child_checkins
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  event_row comunhao.events%rowtype;
  occurrence_row comunhao.event_occurrences%rowtype;
  child_row comunhao.child_checkins%rowtype;
  code text;
begin
  select *
  into event_row
  from comunhao.events
  where id = p_event_id;

  if not found then
    raise exception 'Event not found.';
  end if;

  if not comunhao.user_has_calendar_permission(event_row.church_id, 'checkin.manage', auth.uid()) then
    raise exception 'You cannot manage child check-in for this event.';
  end if;

  if nullif(trim(coalesce(p_child_name, '')), '') is null then
    raise exception 'Child name is required.';
  end if;

  perform comunhao.generate_event_occurrences(p_event_id, event_row.starts_at + interval '1 day');

  if p_occurrence_id is not null then
    select *
    into occurrence_row
    from comunhao.event_occurrences
    where id = p_occurrence_id
      and event_id = p_event_id;
  end if;

  if occurrence_row.id is null then
    select *
    into occurrence_row
    from comunhao.event_occurrences
    where event_id = p_event_id
    order by abs(extract(epoch from (occurrence_start_at - now())))
    limit 1;
  end if;

  code := upper(substr(md5(random()::text || clock_timestamp()::text), 1, 6));

  insert into comunhao.child_checkins (
    event_id,
    occurrence_id,
    church_id,
    child_name,
    guardian_name,
    guardian_phone,
    room_name,
    security_code,
    checked_in_by,
    notes_private
  )
  values (
    event_row.id,
    occurrence_row.id,
    event_row.church_id,
    trim(p_child_name),
    nullif(trim(coalesce(p_guardian_name, '')), ''),
    nullif(trim(coalesce(p_guardian_phone, '')), ''),
    nullif(trim(coalesce(p_room_name, '')), ''),
    code,
    auth.uid(),
    p_notes
  )
  returning *
  into child_row;

  insert into comunhao.event_attendance (
    event_id,
    occurrence_id,
    church_id,
    participant_type,
    check_in_method,
    checked_in_by,
    notes
  )
  values (
    event_row.id,
    occurrence_row.id,
    event_row.church_id,
    'child',
    'manual',
    auth.uid(),
    concat_ws(' | ', trim(p_child_name), nullif(trim(coalesce(p_guardian_name, '')), ''), p_notes)
  );

  return child_row;
end;
$function$
$obj101$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'manual_child_check_in_event(p_event_id uuid, p_occurrence_id uuid, p_child_name text, p_guardian_name text, p_guardian_phone text, p_room_name text, p_notes text)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj102$CREATE OR REPLACE FUNCTION comunhao.map_church_subscription_status(p_status text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
  select case
    when p_status = 'trial' then 'trial'
    when p_status = 'active' then 'active'
    when p_status = 'grace_period' then 'overdue'
    when p_status in ('suspended', 'cancelled') then 'suspended'
    else 'active'
  end;
