    EXECUTE $obj105$CREATE OR REPLACE FUNCTION comunhao.mark_internal_notification_read(p_notification_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
begin
  update comunhao.internal_notifications
  set read_at = coalesce(read_at, now())
  where id = p_notification_id
    and recipient_profile_id = auth.uid();

  update comunhao.notification_delivery_attempts
  set
    delivery_status = case
      when channel = 'in_app' then 'read'
      else delivery_status
    end,
    read_at = coalesce(read_at, now()),
    updated_at = now()
  where notification_id = p_notification_id
    and exists (
      select 1
      from comunhao.internal_notifications notification
      where notification.id = p_notification_id
        and notification.recipient_profile_id = auth.uid()
    );
end;
