    EXECUTE $obj107$CREATE OR REPLACE FUNCTION comunhao.moderate_community_post(p_post_id uuid, p_status text, p_note text DEFAULT NULL::text)
 RETURNS community_posts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  post_row comunhao.community_posts%rowtype;
begin
  select *
  into post_row
  from comunhao.community_posts
  where id = p_post_id;

  if not found then
    raise exception 'Community post not found.';
  end if;

  if not comunhao.can_manage_community_feed(post_row.church_id, auth.uid()) then
    raise exception 'Permission denied.';
  end if;

  update comunhao.community_posts
  set
    status = p_status,
    moderation_note = nullif(trim(coalesce(p_note, '')), ''),
    moderated_by = auth.uid(),
    moderated_at = now()
  where id = p_post_id
  returning * into post_row;

  return post_row;
end;
