    EXECUTE $obj114$CREATE OR REPLACE FUNCTION comunhao.notify_donation_status_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
begin
  if old.status is distinct from new.status
    and new.profile_id is not null
    and new.status in ('confirmed', 'rejected', 'failed') then
    perform comunhao.create_internal_notification(
      new.profile_id,
      case
        when new.status = 'confirmed' then 'Contribuicao confirmada'
        when new.status = 'rejected' then 'Contribuicao rejeitada'
        else 'Contribuicao falhou'
      end,
      case
        when new.status = 'confirmed' then 'A igreja confirmou a tua contribuicao.'
        when new.status = 'rejected' then 'A igreja rejeitou a tua contribuicao. Verifica o motivo.'
        else 'Nao foi possivel confirmar a tua contribuicao.'
      end,
      case
        when new.status = 'confirmed' then 'contribution_confirmed'
        when new.status = 'rejected' then 'contribution_rejected'
        else 'contribution_failed'
      end,
      new.church_id,
      new.confirmed_by,
      'normal',
      'donations',
      new.id,
      'member_donations',
      jsonb_build_object(
        'amount', new.amount,
        'currency', new.currency,
        'provider', new.provider,
        'receipt_number', new.receipt_number
      )
    );
  end if;

  return new;
end;
$function$
$obj114$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'notify_donation_status_changed()', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj115$CREATE OR REPLACE FUNCTION comunhao.notify_event_relevant_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
begin
  if TG_OP = 'UPDATE' and (
    old.starts_at is distinct from new.starts_at
    or old.ends_at is distinct from new.ends_at
    or old.location_name is distinct from new.location_name
    or old.location is distinct from new.location
    or old.status is distinct from new.status
    or old.capacity is distinct from new.capacity
    or old.online_url is distinct from new.online_url
  ) then
    insert into comunhao.event_change_history (
      event_id,
      church_id,
      changed_by,
      change_type,
      reason,
      old_values,
      new_values
    )
    values (
      new.id,
      new.church_id,
      auth.uid(),
      case when new.status = 'cancelled' then 'cancelled' else 'updated' end,
      new.cancellation_reason,
      to_jsonb(old),
      to_jsonb(new)
    );
  end if;

  return new;
end;
$function$
$obj115$;
