    'prayer_request_created',
    new.profile_id,
    'normal',
    'prayer_requests',
    new.id,
    'prayer_requests',
    jsonb_build_object(
      'visibility', new.visibility,
      'anonymous', coalesce(new.anonymous_request, false),
      'allow_responses', coalesce(new.allow_responses, true),
      'status', new.status
    )
  );

  return new;
end;
