  BEGIN
    EXECUTE $obj120$CREATE OR REPLACE FUNCTION comunhao.notify_public_content_created()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  member_row record;
  title_text text;
  message_text text;
  type_text text;
begin
  if tg_table_name = 'events' then
    if new.event_status <> 'published' then
      return new;
    end if;
    title_text := 'Novo evento publicado';
    message_text := new.title;
    type_text := 'event_published';
  elsif tg_table_name = 'donation_campaigns' then
    if new.active is not true or new.campaign_status not in ('active', 'published') then
      return new;
    end if;
    title_text := 'Nova campanha';
    message_text := new.title;
    type_text := 'campaign_published';
  else
    if new.publication_status <> 'published' or new.notify_members is not true then
      return new;
    end if;
    title_text := 'Nova publicacao';
    message_text := new.title;
    type_text := 'publication_published';
  end if;

  for member_row in
    select profile_id
    from comunhao.memberships
    where church_id = new.church_id
      and status = 'active'
  loop
    perform comunhao.create_internal_notification(
      member_row.profile_id,
      title_text,
      message_text,
      type_text,
      new.church_id,
      new.created_by,
      'normal',
      tg_table_name,
      new.id,
      tg_table_name,
      jsonb_build_object('source_table', tg_table_name)
    );
  end loop;

  return new;
end;
$function$
$obj120$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'notify_public_content_created()', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj121$CREATE OR REPLACE FUNCTION comunhao.notify_publication_published()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  membership_row record;
begin
  if new.status <> 'published'
     or coalesce(new.send_notification, false) is false
     or (tg_op = 'UPDATE' and old.status = 'published') then
    return new;
  end if;

  for membership_row in
    select m.profile_id
    from comunhao.memberships m
    where m.church_id = new.church_id
      and m.status = 'active'
      and comunhao.can_view_pastoral_publication(new.id, m.profile_id)
  loop
    perform comunhao.create_internal_notification(
      membership_row.profile_id,
      new.title,
      coalesce(new.summary, 'Nova publicacao da igreja.'),
      case
        when new.publication_type = 'urgent_notice' then 'urgent_notice'
        else 'pastoral_publication'
      end,
      new.church_id,
      new.author_user_id,
      case
        when new.publication_type = 'urgent_notice' then 'urgent'
        else 'normal'
      end,
      'pastoral_publications',
      new.id,
      '/publications/' || new.id::text,
      jsonb_build_object(
        'publication_type', new.publication_type,
        'visibility', new.visibility
      )
    );
  end loop;

  return new;
end;
$function$
$obj121$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'notify_publication_published()', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj122$CREATE OR REPLACE FUNCTION comunhao.notify_super_admins_church_application()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  recipient record;
begin
  if new.status = 'submitted'
    and (
      tg_op = 'INSERT'
      or old.status is distinct from new.status
    ) then
    for recipient in
      select distinct profile_id
      from comunhao.platform_roles
      where role = 'super_admin'
        and status = 'active'
        and profile_id is not null
      union
      select id
      from comunhao.profiles
      where id = 'c9c739d6-82ff-415e-af7d-581cae0fd453'::uuid
         or regexp_replace(coalesce(phone, ''), '\D', '', 'g')
            in ('841130015', '258841130015')
    loop
      perform comunhao.create_internal_notification(
        recipient.profile_id,
        'Novo pedido de igreja',
        'A igreja ' || coalesce(new.church_name, 'sem nome') || ' foi enviada para aprovacao.',
        'church_application_submitted',
        null,
        new.pastor_profile_id,
        'high',
        'church_applications',
        new.id,
        '/church-applications',
        jsonb_build_object(
          'application_id', new.id,
          'church_name', new.church_name,
          'city', new.city,
          'province', new.province,
          'pastor_profile_id', new.pastor_profile_id
        )
      );
    end loop;
  end if;

  return new;
end;
