  END;
  BEGIN
    EXECUTE $obj123$CREATE OR REPLACE FUNCTION comunhao.open_event_checkin(p_occurrence_id uuid, p_duration_minutes integer DEFAULT 180)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  occurrence_row comunhao.event_occurrences%rowtype;
  raw_token text;
begin
  select *
  into occurrence_row
  from comunhao.event_occurrences
  where id = p_occurrence_id
  for update;

  if not found then
    raise exception 'Occurrence not found.';
  end if;

  if not comunhao.user_has_calendar_permission(occurrence_row.church_id, 'checkin.manage', auth.uid()) then
    raise exception 'You cannot open check-in for this event.';
  end if;

  raw_token := encode(gen_random_bytes(24), 'hex');

  update comunhao.event_occurrences
  set
    qr_token_hash = encode(digest(raw_token, 'sha256'), 'hex'),
    qr_expires_at = now() + make_interval(mins => greatest(coalesce(p_duration_minutes, 180), 5)),
    qr_closed_at = null,
    checkin_opens_at = now(),
    checkin_closes_at = now() + make_interval(mins => greatest(coalesce(p_duration_minutes, 180), 5)),
    status = 'ongoing',
    updated_at = now()
  where id = p_occurrence_id;

  return occurrence_row.id::text || ':' || raw_token;
end;
$function$
$obj123$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'open_event_checkin(p_occurrence_id uuid, p_duration_minutes integer)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj124$CREATE OR REPLACE FUNCTION comunhao.post_paid_church_expense_to_ledger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  wallet_id uuid;
  balance_before_value numeric;
  balance_after_value numeric;
  existing_entry_id uuid;
begin
  if new.status <> 'paid' then
    return new;
  end if;

  select id
  into existing_entry_id
  from comunhao.wallet_ledger_entries
  where reference_table = 'church_expenses'
    and reference_id = new.id
    and status = 'posted'
  limit 1;

  if existing_entry_id is not null then
    return new;
  end if;

  perform comunhao.ensure_wallet_accounts('church', new.church_id, (
    select name from comunhao.churches where id = new.church_id
  ));

  select id
  into wallet_id
  from comunhao.wallet_accounts
  where owner_type = 'church'
    and church_id = new.church_id
    and provider = case
      when new.payment_method in ('emola', 'mpesa') then new.payment_method
      else 'mpesa'
    end
  limit 1;

  balance_before_value := comunhao.finance_wallet_balance(wallet_id);
  balance_after_value := balance_before_value - new.amount;

  insert into comunhao.wallet_ledger_entries (
    wallet_account_id,
    church_id,
    created_by,
    direction,
    entry_type,
    amount,
    currency,
    status,
    description,
    reference_table,
    reference_id,
    metadata,
    posted_at,
    balance_before,
    balance_after,
    idempotency_key,
    is_demo
  )
  values (
    wallet_id,
    new.church_id,
    coalesce(new.paid_by, new.approved_by, new.created_by, auth.uid()),
    'debit',
    'expense',
    new.amount,
    new.currency,
    'posted',
    new.title,
    'church_expenses',
    new.id,
    jsonb_build_object(
      'category', new.category,
      'payment_method', new.payment_method,
      'payment_reference', new.payment_reference
    ),
    coalesce(new.paid_at, now()),
    balance_before_value,
    balance_after_value,
    'expense:' || new.id::text || ':paid',
    new.is_demo
  );

  perform comunhao.finance_log_event(
    new.church_id,
    'expense.paid',
    'church_expenses',
    new.id,
    new.amount,
    'expense:' || new.id::text || ':paid',
    jsonb_build_object('category', new.category)
  );

  return new;
end;
$function$
$obj124$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'post_paid_church_expense_to_ledger()', SQLERRM);
  END;
