    EXECUTE $obj125$CREATE OR REPLACE FUNCTION comunhao.prepare_event_internal_reminders(p_church_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  inserted_count integer := 0;
begin
  if not comunhao.user_has_calendar_permission(p_church_id, 'calendar.edit', auth.uid()) then
    raise exception 'You cannot prepare reminders for this church.';
  end if;

  insert into comunhao.event_reminders (
    event_id,
    occurrence_id,
    church_id,
    channel,
    audience,
    scheduled_for,
    status,
    provider_status,
    created_by
  )
  select
    eo.event_id,
    eo.id,
    eo.church_id,
    'internal',
    'members',
    eo.occurrence_start_at - interval '1 day',
    'queued',
    'internal_only',
    auth.uid()
  from comunhao.event_occurrences eo
  join comunhao.events e
    on e.id = eo.event_id
  where eo.church_id = p_church_id
    and eo.occurrence_start_at between now() and now() + interval '30 days'
    and e.status in ('published', 'scheduled', 'ongoing')
  on conflict do nothing;

  get diagnostics inserted_count = row_count;
  return inserted_count;
end;
