    EXECUTE $obj128$CREATE OR REPLACE FUNCTION comunhao.provision_church_trial_subscription(p_church_id uuid, p_trial_days integer DEFAULT 30)
 RETURNS church_subscriptions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  trial_start timestamptz := now();
  trial_end timestamptz := now() + make_interval(days => greatest(coalesce(p_trial_days, 30), 1));
  result comunhao.church_subscriptions;
begin
  insert into comunhao.church_subscriptions (
    church_id,
    plan_code,
    status,
    trial_started_at,
    trial_ends_at,
    current_period_started_at,
    current_period_ends_at,
    grace_period_ends_at,
    activated_at,
    suspended_at,
    cancelled_at,
    updated_at,
    updated_by,
    admin_notes
  )
  values (
    p_church_id,
    'premium',
    'trial',
    trial_start,
    trial_end,
    trial_start,
    trial_end,
    null,
    null,
    null,
    null,
    now(),
    auth.uid(),
    'Trial Plus automatico de 30 dias.'
  )
  on conflict (church_id) do update
    set
      plan_code = 'premium',
      status = 'trial',
      trial_started_at = excluded.trial_started_at,
      trial_ends_at = excluded.trial_ends_at,
      current_period_started_at = excluded.current_period_started_at,
      current_period_ends_at = excluded.current_period_ends_at,
      grace_period_ends_at = null,
      activated_at = null,
      suspended_at = null,
      cancelled_at = null,
      updated_at = now(),
      updated_by = auth.uid(),
      admin_notes = excluded.admin_notes
  returning * into result;

  return result;
end;
