    EXECUTE $obj130$CREATE OR REPLACE FUNCTION comunhao.react_to_community_comment(p_comment_id uuid, p_reaction_type text DEFAULT 'amen'::text)
 RETURNS community_comment_reactions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  reaction_row comunhao.community_comment_reactions%rowtype;
  normalized_reaction text := coalesce(nullif(trim(p_reaction_type), ''), 'amen');
begin
  if auth.uid() is null then
    raise exception 'Authentication required.';
  end if;

  if normalized_reaction not in ('amen', 'praying', 'glory', 'built', 'faithful') then
    raise exception 'Unsupported reaction type.';
  end if;

  if not exists (
    select 1
    from comunhao.community_post_comments c
    join comunhao.community_posts p on p.id = c.post_id
    join comunhao.memberships m on m.church_id = p.church_id
    where c.id = p_comment_id
      and c.status = 'visible'
      and m.profile_id = auth.uid()
      and m.status = 'active'
  ) then
    raise exception 'Comment not available for this member.';
  end if;

  insert into comunhao.community_comment_reactions (
    comment_id,
    profile_id,
    reaction_type
  )
  values (
    p_comment_id,
    auth.uid(),
    normalized_reaction
  )
  on conflict (comment_id, profile_id) do update
  set reaction_type = excluded.reaction_type,
      updated_at = now()
  returning * into reaction_row;

  return reaction_row;
end;
