    EXECUTE $obj133$CREATE OR REPLACE FUNCTION comunhao.reconcile_vida_nova_core_access()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  vida_id uuid;
  pastor_id uuid;
  member_id uuid;
  super_admin_id uuid;
begin
  select id
  into vida_id
  from comunhao.churches
  where lower(trim(name)) = 'vida nova'
  order by created_at
  limit 1;

  pastor_id := comunhao.profile_id_by_phone('877688695');
  member_id := comunhao.profile_id_by_phone('827688695');
  super_admin_id := comunhao.profile_id_by_phone('841130015');

  if vida_id is not null and pastor_id is not null then
    insert into comunhao.memberships (
      church_id,
      profile_id,
      role,
      status
    )
    values (
      vida_id,
      pastor_id,
      'pastor',
      'active'
    )
    on conflict (church_id, profile_id) do update
      set role = 'pastor',
          status = 'active';
  end if;

  if vida_id is not null and member_id is not null then
    insert into comunhao.memberships (
      church_id,
      profile_id,
      role,
      status
    )
    values (
      vida_id,
      member_id,
      'member',
      'active'
    )
    on conflict (church_id, profile_id) do update
      set role = case
            when comunhao.memberships.role in ('pastor', 'church_admin', 'leader') then comunhao.memberships.role
            else 'member'
          end,
          status = 'active';
  end if;

  if super_admin_id is not null then
    insert into comunhao.platform_roles (
      profile_id,
      role,
      status
    )
    values (
      super_admin_id,
      'super_admin',
      'active'
    )
    on conflict (profile_id, role) do update
      set status = 'active';
  end if;

  return jsonb_build_object(
    'vida_nova_found', vida_id is not null,
    'pastor_found', pastor_id is not null,
    'member_found', member_id is not null,
    'super_admin_found', super_admin_id is not null
  );
end;
$function$
$obj133$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'reconcile_vida_nova_core_access()', SQLERRM);
  END;
