  BEGIN
    EXECUTE $obj135$CREATE OR REPLACE FUNCTION comunhao.record_member_donation(p_church_id uuid, p_donation_type text, p_amount numeric, p_provider text, p_campaign_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  wallet_row comunhao.member_wallet_accounts%rowtype;
  result comunhao.donations;
  provider text;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required.';
  end if;

  if coalesce(p_amount, 0) <= 0 then
    raise exception 'Amount must be greater than zero.';
  end if;

  perform comunhao.ensure_member_wallet(
    auth.uid(),
    (select phone from comunhao.profiles where id = auth.uid())
  );

  select *
  into wallet_row
  from comunhao.member_wallet_accounts
  where profile_id = auth.uid()
  for update;

  provider := coalesce(nullif(trim(coalesce(p_provider, '')), ''), comunhao.member_wallet_provider(wallet_row.phone));

  if wallet_row.available_balance < p_amount then
    raise exception 'Saldo insuficiente na conta Comunhao.';
  end if;

  result := comunhao.create_church_contribution(
    p_church_id,
    p_donation_type,
    p_amount,
    'manual_transfer',
    provider,
    p_campaign_id,
    auth.uid(),
    wallet_row.phone,
    null,
    null,
    'Criado no app do membro a partir da carteira Comunhao. Enviar para confirmacao do pastor/financeiro.',
    false,
    'member-wallet:' || auth.uid()::text || ':' || p_church_id::text || ':' || p_donation_type || ':' || extract(epoch from clock_timestamp())::text
  );

  insert into comunhao.member_wallet_ledger_entries (
    wallet_account_id,
    profile_id,
    church_id,
    direction,
    entry_type,
    amount,
    currency,
    status,
    description,
    reference_table,
    reference_id,
    posted_at
  )
  values (
    wallet_row.id,
    auth.uid(),
    p_church_id,
    'debit',
    p_donation_type,
    p_amount,
    'MZN',
    'pending',
    'Contribuicao enviada para confirmacao da igreja.',
    'donations',
    result.id,
    now()
  );

  update comunhao.member_wallet_accounts
  set
    available_balance = available_balance - p_amount,
    pending_balance = pending_balance + p_amount,
    total_contributed = total_contributed + p_amount,
    updated_at = now()
  where id = wallet_row.id;

  return result.id;
end;
$function$
$obj135$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'record_member_donation(p_church_id uuid, p_donation_type text, p_amount numeric, p_provider text, p_campaign_id uuid)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj136$CREATE OR REPLACE FUNCTION comunhao.record_pastoral_publication_read(p_publication_id uuid, p_read_percent integer DEFAULT 100)
 RETURNS pastoral_publication_reads
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  read_row comunhao.pastoral_publication_reads%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Authentication required.';
  end if;

  if not comunhao.can_view_pastoral_publication(p_publication_id, auth.uid()) then
    raise exception 'Publication not available.';
  end if;

  insert into comunhao.pastoral_publication_reads (
    publication_id,
    profile_id,
    read_percent
  )
  values (
    p_publication_id,
    auth.uid(),
    greatest(0, least(coalesce(p_read_percent, 100), 100))
  )
  on conflict (publication_id, profile_id) do update
  set
    last_viewed_at = now(),
    open_count = comunhao.pastoral_publication_reads.open_count + 1,
    read_percent = greatest(
      comunhao.pastoral_publication_reads.read_percent,
      greatest(0, least(coalesce(p_read_percent, 100), 100))
    )
  returning * into read_row;

  return read_row;
end;
