    EXECUTE $obj137$CREATE OR REPLACE FUNCTION comunhao.record_pastoral_request_open(p_request_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  request_row comunhao.pastoral_requests%rowtype;
begin
  select * into request_row
  from comunhao.pastoral_requests
  where id = p_request_id;

  if request_row.id is null then
    raise exception 'Pastoral request not found.';
  end if;

  if not (
    request_row.profile_id = auth.uid()
    or comunhao.has_church_role(
      request_row.church_id,
      array['pastor', 'church_admin', 'leader']::text[],
      auth.uid()
    )
  ) then
    raise exception 'Not authorized.';
  end if;

  insert into comunhao.pastoral_request_access_logs (
    pastoral_request_id,
    profile_id,
    action
  )
  values (p_request_id, auth.uid(), 'opened');

  update comunhao.pastoral_requests
  set first_opened_at = coalesce(first_opened_at, now())
  where id = p_request_id;
end;
