    EXECUTE $obj138$CREATE OR REPLACE FUNCTION comunhao.record_platform_wallet_revenue(p_provider text, p_amount numeric, p_entry_type text DEFAULT 'subscription_payment'::text, p_description text DEFAULT NULL::text)
 RETURNS wallet_ledger_entries
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  wallet_id uuid;
  result comunhao.wallet_ledger_entries;
begin
  if not comunhao.is_super_admin(auth.uid()) then
    raise exception 'Only super admins can record platform revenue.';
  end if;

  if p_provider not in ('mpesa', 'emola') then
    raise exception 'Invalid provider: %', p_provider;
  end if;

  if p_entry_type not in ('subscription_payment', 'other_revenue', 'adjustment') then
    raise exception 'Invalid platform revenue entry type: %', p_entry_type;
  end if;

  if coalesce(p_amount, 0) <= 0 then
    raise exception 'Amount must be greater than zero.';
  end if;

  perform comunhao.ensure_wallet_accounts('platform', null, 'Comunhao');

  select id
  into wallet_id
  from comunhao.wallet_accounts
  where owner_type = 'platform'
    and church_id is null
    and provider = p_provider
  limit 1;

  insert into comunhao.wallet_ledger_entries (
    wallet_account_id,
    direction,
    entry_type,
    amount,
    currency,
    status,
    description,
    created_by,
    posted_at
  )
  values (
    wallet_id,
    'credit',
    p_entry_type,
    p_amount,
    'MZN',
    'posted',
    coalesce(p_description, 'Receita registada manualmente pela Comunhao.'),
    auth.uid(),
    now()
  )
  returning *
  into result;

  return result;
end;
