    EXECUTE $obj140$CREATE OR REPLACE FUNCTION comunhao.refresh_church_subscription_state(p_church_id uuid)
 RETURNS churches
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  church_row comunhao.churches%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Sessao expirada.';
  end if;

  if not exists (
    select 1
    from comunhao.memberships
    where church_id = p_church_id
      and profile_id = auth.uid()
      and status = 'active'
  )
  and not comunhao.has_platform_role(
    array['super_admin', 'support_agent', 'developer', 'auditor']::text[],
    auth.uid()
  ) then
    raise exception 'Sem permissao para atualizar esta igreja.';
  end if;

  perform comunhao.run_subscription_expiry_maintenance(p_church_id);
  select * into church_row from comunhao.sync_church_subscription_state(p_church_id);
  return church_row;
end;
