    EXECUTE $obj141$CREATE OR REPLACE FUNCTION comunhao.register_executive_report_export(p_report_id uuid, p_format text, p_filters jsonb DEFAULT '{}'::jsonb, p_contains_sensitive_data boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  report_row comunhao.executive_reports%rowtype;
  export_id uuid;
begin
  select * into report_row
  from comunhao.executive_reports
  where id = p_report_id
  limit 1;

  if report_row.id is null then
    raise exception 'Report not found.';
  end if;

  if not comunhao.user_can_access_organization(report_row.organization_id, 'reports.consolidated.view', auth.uid()) then
    raise exception 'Not allowed to export this report.';
  end if;

  insert into comunhao.executive_report_exports (
    report_id,
    organization_id,
    church_id,
    requested_by_profile_id,
    format,
    filters,
    contains_sensitive_data
  )
  values (
    report_row.id,
    report_row.organization_id,
    report_row.church_id,
    auth.uid(),
    lower(coalesce(nullif(trim(p_format), ''), 'pdf')),
    coalesce(p_filters, '{}'::jsonb),
    coalesce(p_contains_sensitive_data, false)
  )
  returning id into export_id;

  perform comunhao.create_organization_audit_log(
    report_row.organization_id,
    'report.exported',
    'executive_report',
    report_row.id,
    report_row.church_id,
    'Exportacao de relatorio registada.',
    jsonb_build_object('format', p_format, 'export_id', export_id),
    coalesce(p_contains_sensitive_data, false)
  );

  return export_id;
end;
