      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'register_for_event(p_event_id uuid)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj143$CREATE OR REPLACE FUNCTION comunhao.register_phone_auth_user(p_full_name text, p_phone text, p_password text, p_birth_date date DEFAULT NULL::date, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions', 'auth', 'extensions'
AS $function$
declare
  user_id uuid := gen_random_uuid();
  normalized_phone text := comunhao.normalize_phone_auth_number(p_phone);
  normalized_name text := nullif(trim(coalesce(p_full_name, '')), '');
  user_metadata jsonb;
begin
  if normalized_name is null then
    raise exception 'O nome completo e obrigatorio.';
  end if;

  if normalized_phone = '' then
    raise exception 'Numero de telefone invalido.';
  end if;

  if char_length(coalesce(p_password, '')) < 6 then
    raise exception 'A palavra-passe deve ter pelo menos 6 caracteres.';
  end if;

  if exists (
    select 1
    from auth.users
    where phone = normalized_phone
      and deleted_at is null
  ) then
    raise exception 'Ja existe uma conta com este numero de telefone.';
  end if;

  user_metadata := coalesce(p_metadata, '{}'::jsonb)
    || jsonb_build_object(
      'sub', user_id::text,
      'full_name', normalized_name,
      'phone', normalized_phone,
      'phone_verified', false,
      'email_verified', false
    );

  if p_birth_date is not null then
    user_metadata := user_metadata || jsonb_build_object(
      'birth_date', p_birth_date::text
    );
  end if;

  insert into auth.users (
    instance_id,
    id,
    aud,
    role,
    encrypted_password,
    email_confirmed_at,
    invited_at,
    confirmation_token,
    confirmation_sent_at,
    recovery_token,
    recovery_sent_at,
    email_change_token_new,
    email_change,
    email_change_sent_at,
    last_sign_in_at,
    raw_app_meta_data,
    raw_user_meta_data,
    is_super_admin,
    created_at,
    updated_at,
    phone,
    phone_confirmed_at,
    phone_change,
    phone_change_token,
    phone_change_sent_at,
    email_change_token_current,
    email_change_confirm_status,
    banned_until,
    reauthentication_token,
    reauthentication_sent_at,
    is_sso_user,
    deleted_at,
    is_anonymous
  )
  values (
    '00000000-0000-0000-0000-000000000000',
    user_id,
    'authenticated',
    'authenticated',
    extensions.crypt(p_password, extensions.gen_salt('bf')),
    null,
    null,
    '',
    null,
    '',
    null,
    '',
    '',
    null,
    null,
    jsonb_build_object(
      'provider', 'phone',
      'providers', jsonb_build_array('phone')
    ),
    user_metadata,
    false,
    now(),
    now(),
    normalized_phone,
    null,
    '',
    '',
    null,
    '',
    0,
    null,
    '',
    null,
    false,
    null,
    false
  );

  insert into auth.identities (
    provider_id,
    user_id,
    identity_data,
    provider,
    last_sign_in_at,
    created_at,
    updated_at,
    id
  )
  values (
    normalized_phone,
    user_id,
    user_metadata,
    'phone',
    null,
    now(),
    now(),
    gen_random_uuid()
  );

  perform comunhao.request_phone_auth_otp(
    normalized_phone,
    'signup'
  );

  return jsonb_build_object(
    'user_id', user_id,
    'phone', normalized_phone,
    'requires_otp', true
  );
exception
  when unique_violation then
    raise exception 'Ja existe uma conta com este numero de telefone.';
end;
$function$
$obj143$;
