      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'register_phone_auth_user(p_full_name text, p_phone text, p_password text, p_birth_date date, p_metadata jsonb)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj144$CREATE OR REPLACE FUNCTION comunhao.reject_church_contribution(p_donation_id uuid, p_reason text)
 RETURNS donations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  donation_row comunhao.donations%rowtype;
begin
  if nullif(trim(coalesce(p_reason, '')), '') is null then
    raise exception 'A rejection reason is required.';
  end if;

  select *
  into donation_row
  from comunhao.donations
  where id = p_donation_id
  for update;

  if not found then
    raise exception 'Contribution not found.';
  end if;

  if not comunhao.user_has_finance_permission(donation_row.church_id, 'finance.confirm_contribution', auth.uid()) then
    raise exception 'You cannot reject contributions for this church.';
  end if;

  if donation_row.status = 'confirmed' then
    raise exception 'Confirmed contributions cannot be rejected. Use refund or reversal.';
  end if;

  update comunhao.donations
  set
    status = 'rejected',
    rejected_by = auth.uid(),
    rejected_at = now(),
    rejection_reason = trim(p_reason),
    updated_at = now()
  where id = donation_row.id
  returning * into donation_row;

  perform comunhao.finance_log_event(
    donation_row.church_id,
    'contribution.rejected',
    'donations',
    donation_row.id,
    donation_row.amount,
    null,
    jsonb_build_object('reason', p_reason)
  );

  if donation_row.profile_id is not null then
    perform comunhao.create_internal_notification(
      donation_row.profile_id,
      'Contribuicao rejeitada',
      'A sua contribuicao precisa de correcao: ' || trim(p_reason),
      'contribution_rejected',
      donation_row.church_id,
      auth.uid(),
      'normal',
      'donations',
      donation_row.id,
      '/donations',
      jsonb_build_object('reason', p_reason)
    );
  end if;

  return donation_row;
end;
$function$
$obj144$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'reject_church_contribution(p_donation_id uuid, p_reason text)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj145$CREATE OR REPLACE FUNCTION comunhao.reject_member_donation(p_donation_id uuid, p_notes text DEFAULT NULL::text)
 RETURNS donations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  donation_row comunhao.donations%rowtype;
begin
  select *
  into donation_row
  from comunhao.donations
  where id = p_donation_id
  for update;

  if donation_row.id is null then
    raise exception 'Donation not found.';
  end if;

  if not comunhao.has_church_role(
    donation_row.church_id,
    array['pastor', 'church_admin']::text[],
    auth.uid()
  ) then
    raise exception 'Only church finance admins can reject donations.';
  end if;

  update comunhao.donations
  set
    status = 'rejected',
    notes = coalesce(nullif(trim(coalesce(p_notes, '')), ''), notes),
    confirmed_at = now(),
    confirmed_by = auth.uid()
  where id = p_donation_id
  returning * into donation_row;

  update comunhao.wallet_ledger_entries
  set
    status = 'reversed',
    description = 'Contribuicao rejeitada pela igreja.'
  where reference_table = 'donations'
    and reference_id = p_donation_id
    and status = 'pending';

  update comunhao.member_wallet_ledger_entries
  set
    status = 'reversed',
    description = 'Contribuicao rejeitada pela igreja.'
  where reference_table = 'donations'
    and reference_id = p_donation_id
    and status = 'pending';

  update comunhao.member_wallet_accounts mwa
  set
    pending_balance = greatest(mwa.pending_balance - donation_row.amount, 0),
    updated_at = now()
  where mwa.profile_id = donation_row.profile_id;

  return donation_row;
end;
$function$
$obj145$;
