    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'reject_member_donation(p_donation_id uuid, p_notes text)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj146$CREATE OR REPLACE FUNCTION comunhao.report_community_post(p_post_id uuid, p_reason text, p_details text DEFAULT NULL::text)
 RETURNS community_post_reports
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  report_row comunhao.community_post_reports%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Authentication required.';
  end if;

  if not exists (
    select 1
    from comunhao.community_posts p
    join comunhao.memberships m on m.church_id = p.church_id
    where p.id = p_post_id
      and p.status = 'approved'
      and m.profile_id = auth.uid()
      and m.status = 'active'
  ) then
    raise exception 'Community post not available.';
  end if;

  insert into comunhao.community_post_reports (
    post_id,
    reporter_profile_id,
    reason,
    details,
    status
  )
  values (
    p_post_id,
    auth.uid(),
    coalesce(nullif(trim(p_reason), ''), 'inappropriate'),
    nullif(trim(coalesce(p_details, '')), ''),
    'open'
  )
  on conflict (post_id, reporter_profile_id) do update
  set
    reason = excluded.reason,
    details = excluded.details,
    status = 'open',
    reviewed_by = null,
    reviewed_at = null
  returning * into report_row;

  return report_row;
end;
