  BEGIN
    EXECUTE $obj147$CREATE OR REPLACE FUNCTION comunhao.request_phone_auth_otp(p_phone text, p_purpose text DEFAULT 'signup'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions', 'auth', 'extensions'
AS $function$
declare
  normalized_phone text := comunhao.normalize_phone_auth_number(p_phone);
  user_row record;
  existing_pending comunhao.phone_auth_otps%rowtype;
  otp_code text;
  otp_hash text;
begin
  if normalized_phone = '' then
    raise exception 'Numero de telefone invalido.';
  end if;

  if p_purpose not in ('signup', 'login') then
    raise exception 'Tipo de OTP invalido.';
  end if;

  select
    u.id,
    u.phone,
    u.deleted_at,
    p.phone as profile_phone
  into user_row
  from auth.users u
  left join comunhao.profiles p
    on p.id = u.id
  where (
      u.phone = normalized_phone
      or p.phone = normalized_phone
      or coalesce(u.raw_user_meta_data->>'phone', '') = normalized_phone
    )
    and u.deleted_at is null
  order by u.created_at desc
  limit 1;

  if not found then
    raise exception 'Nao existe nenhuma conta associada a este numero.';
  end if;

  select *
  into existing_pending
  from comunhao.phone_auth_otps
  where phone = normalized_phone
    and status = 'pending'
  order by created_at desc
  limit 1
  for update;

  if found and existing_pending.last_sent_at > now() - interval '30 seconds' then
    raise exception 'Aguarde alguns segundos antes de pedir um novo codigo.';
  end if;

  update comunhao.phone_auth_otps
  set status = case
        when expires_at < now() then 'expired'
        else 'cancelled'
      end
  where phone = normalized_phone
    and status = 'pending';

  otp_code := lpad((floor(random() * 1000000))::int::text, 6, '0');
  otp_hash := encode(
    extensions.digest(normalized_phone || ':' || otp_code, 'sha256'),
    'hex'
  );

  insert into comunhao.phone_auth_otps (
    auth_user_id,
    phone,
    purpose,
    otp_hash,
    attempts,
    status,
    last_sent_at,
    expires_at
  )
  values (
    user_row.id,
    normalized_phone,
    p_purpose,
    otp_hash,
    0,
    'pending',
    now(),
    now() + interval '10 minutes'
  );

  perform comunhao.send_sms_via_mozesms(
    normalized_phone,
    format('Comunhao OTP: %s', otp_code)
  );

  return jsonb_build_object(
    'phone', normalized_phone,
    'purpose', p_purpose,
    'expires_in_seconds', 600,
    'sent_at', now()
  );
end;
