    EXECUTE $obj149$CREATE OR REPLACE FUNCTION comunhao.reset_church_workspace(p_church_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  deleted_announcements integer := 0;
  deleted_events integer := 0;
  deleted_prayer_requests integer := 0;
  deleted_campaigns integer := 0;
begin
  if not comunhao.is_super_admin(auth.uid()) then
    raise exception 'Only super admins can reset church workspaces.';
  end if;

  if not exists (
    select 1
    from comunhao.churches
    where id = p_church_id
  ) then
    raise exception 'Church not found.';
  end if;

  delete from comunhao.announcements
  where church_id = p_church_id;
  get diagnostics deleted_announcements = row_count;

  delete from comunhao.events
  where church_id = p_church_id;
  get diagnostics deleted_events = row_count;

  delete from comunhao.prayer_requests
  where church_id = p_church_id;
  get diagnostics deleted_prayer_requests = row_count;

  delete from comunhao.donation_campaigns
  where church_id = p_church_id;
  get diagnostics deleted_campaigns = row_count;

  update comunhao.church_settings
  set updated_at = now()
  where church_id = p_church_id;

  return jsonb_build_object(
    'announcements_deleted', deleted_announcements,
    'events_deleted', deleted_events,
    'prayer_requests_deleted', deleted_prayer_requests,
    'campaigns_deleted', deleted_campaigns
  );
end;
