    EXECUTE $obj150$CREATE OR REPLACE FUNCTION comunhao.resolve_executive_alert(p_alert_id uuid, p_resolution text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  alert_row comunhao.executive_alerts%rowtype;
begin
  select * into alert_row
  from comunhao.executive_alerts
  where id = p_alert_id
  limit 1;

  if alert_row.id is null then
    raise exception 'Alert not found.';
  end if;

  if not comunhao.user_can_access_organization(alert_row.organization_id, 'goals.manage', auth.uid()) then
    raise exception 'Not allowed to resolve this alert.';
  end if;

  update comunhao.executive_alerts
  set
    status = 'resolved',
    resolution = p_resolution,
    resolved_by_profile_id = auth.uid(),
    resolved_at = now()
  where id = p_alert_id;

  perform comunhao.create_organization_audit_log(
    alert_row.organization_id,
    'alert.resolved',
    'executive_alert',
    p_alert_id,
    alert_row.church_id,
    'Alerta executivo resolvido.',
    jsonb_build_object('resolution', p_resolution),
    false
  );

  return p_alert_id;
end;
