    EXECUTE $obj151$CREATE OR REPLACE FUNCTION comunhao.respond_church_join_request(p_request_id uuid, p_member_response text)
 RETURNS church_join_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  request_row comunhao.church_join_requests%rowtype;
begin
  update comunhao.church_join_requests
  set
    member_response = trim(coalesce(p_member_response, '')),
    status = case
      when status = 'more_information_required' then 'under_review'
      else status
    end
  where id = p_request_id
    and profile_id = auth.uid()
    and status in ('pending', 'under_review', 'more_information_required')
  returning * into request_row;

  if request_row.id is null then
    raise exception 'Join request not available.';
  end if;

  insert into comunhao.church_request_timeline (
    church_id,
    request_table,
    request_id,
    actor_profile_id,
    action,
    public_message
  )
  values (
    request_row.church_id,
    'church_join_requests',
    request_row.id,
    auth.uid(),
    'member_response',
    'O membro enviou informacoes adicionais.'
  );

  return request_row;
end;
