    EXECUTE $obj153$CREATE OR REPLACE FUNCTION comunhao.review_administrative_request(p_request_id uuid, p_status text, p_response text DEFAULT NULL::text, p_internal_note text DEFAULT NULL::text, p_assigned_membership_id uuid DEFAULT NULL::uuid)
 RETURNS administrative_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  request_row comunhao.administrative_requests%rowtype;
begin
  select * into request_row
  from comunhao.administrative_requests
  where id = p_request_id
  for update;

  if request_row.id is null then
    raise exception 'Administrative request not found.';
  end if;

  if not comunhao.has_church_role(
    request_row.church_id,
    array['pastor', 'church_admin', 'leader']::text[],
    auth.uid()
  ) then
    raise exception 'Not authorized.';
  end if;

  update comunhao.administrative_requests
  set
    status = p_status,
    response = coalesce(nullif(trim(coalesce(p_response, '')), ''), response),
    internal_notes = coalesce(nullif(trim(coalesce(p_internal_note, '')), ''), internal_notes),
    assigned_membership_id = coalesce(p_assigned_membership_id, assigned_membership_id)
  where id = p_request_id
  returning * into request_row;

  insert into comunhao.church_request_timeline (
    church_id,
    request_table,
    request_id,
    actor_profile_id,
    action,
    public_message,
    internal_note
  )
  values (
    request_row.church_id,
    'administrative_requests',
    request_row.id,
    auth.uid(),
    p_status,
    p_response,
    p_internal_note
  );

  return request_row;
end;
