  BEGIN
    EXECUTE $obj154$CREATE OR REPLACE FUNCTION comunhao.review_church_application(p_application_id uuid, p_decision text, p_review_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  application_row comunhao.church_applications%rowtype;
  new_church_id uuid;
  new_slug text;
  new_join_code text;
begin
  if not comunhao.is_super_admin(auth.uid()) then
    raise exception 'Only super admins can review church applications.';
  end if;

  if p_decision not in ('approved', 'changes_requested', 'rejected') then
    raise exception 'Invalid review decision: %', p_decision;
  end if;

  select *
  into application_row
  from comunhao.church_applications
  where id = p_application_id
  for update;

  if not found then
    raise exception 'Church application not found.';
  end if;

  if application_row.status <> 'submitted' then
    raise exception 'Only submitted applications can be reviewed. Current status: %', application_row.status;
  end if;

  if p_decision = 'approved' then
    new_slug := comunhao.generate_unique_church_slug(application_row.church_name);
    new_join_code := comunhao.generate_unique_join_code(application_row.church_name);

    insert into comunhao.churches (
      name,
      slug,
      join_code,
      app_name,
      tagline,
      hero_title,
      hero_subtitle,
      logo_url,
      primary_color,
      secondary_color,
      phone,
      email,
      city,
      country,
      active,
      subscription_status
    )
    values (
      application_row.church_name,
      new_slug,
      new_join_code,
      application_row.church_name,
      coalesce(application_row.tagline, 'Powered by Comunhao'),
      application_row.church_name,
      'Comunidade ativa, organizada e ligada em um so lugar.',
      application_row.logo_url,
      application_row.primary_color,
      application_row.secondary_color,
      application_row.phone,
      application_row.email,
      application_row.city,
      application_row.country,
      true,
      'trial'
    )
    returning id
    into new_church_id;

    insert into comunhao.church_settings (
      church_id,
      source_application_id,
      owner_profile_id,
      member_join_mode,
      join_link,
      require_member_approval
    )
    values (
      new_church_id,
      application_row.id,
      application_row.pastor_profile_id,
      'open',
      'https://comunhao.app/join/' || new_join_code,
      false
    )
    on conflict (church_id) do update
      set
        source_application_id = excluded.source_application_id,
        owner_profile_id = excluded.owner_profile_id,
        join_link = excluded.join_link,
        require_member_approval = excluded.require_member_approval;

    if nullif(trim(coalesce(application_row.mpesa, '')), '') is not null then
      insert into comunhao.church_payment_settings (
        church_id,
        provider,
        account_name,
        account_number,
        instructions,
        is_primary
      )
      values (
        new_church_id,
        'mpesa',
        application_row.church_name,
        application_row.mpesa,
        'Recebe dizimos e ofertas por M-Pesa.',
        true
      )
      on conflict (church_id, provider) do update
        set
          account_name = excluded.account_name,
          account_number = excluded.account_number,
          instructions = excluded.instructions,
          is_primary = excluded.is_primary;
    end if;

    if nullif(trim(coalesce(application_row.emola, '')), '') is not null then
      insert into comunhao.church_payment_settings (
        church_id,
        provider,
        account_name,
        account_number,
        instructions,
        is_primary
      )
      values (
        new_church_id,
        'emola',
        application_row.church_name,
        application_row.emola,
        'Recebe dizimos e ofertas por e-Mola.',
        false
      )
      on conflict (church_id, provider) do update
        set
          account_name = excluded.account_name,
          account_number = excluded.account_number,
          instructions = excluded.instructions,
          is_primary = excluded.is_primary;
    end if;

    insert into comunhao.memberships (
      church_id,
      profile_id,
      role,
      status
    )
    values (
      new_church_id,
      application_row.pastor_profile_id,
      'pastor',
      'active'
    )
    on conflict (church_id, profile_id) do update
      set
        role = excluded.role,
        status = 'active';

    perform comunhao.provision_church_trial_subscription(new_church_id, 30);
    perform comunhao.sync_church_subscription_state(new_church_id);
    perform comunhao.ensure_wallet_accounts(
      'church',
      new_church_id,
      application_row.church_name
    );

    update comunhao.church_applications
    set
      status = 'approved',
      reviewed_at = now(),
      reviewed_by = auth.uid(),
      review_notes = p_review_notes,
      approved_church_id = new_church_id,
      updated_at = now()
    where id = p_application_id;

    perform comunhao.create_internal_notification(
      application_row.pastor_profile_id,
      'Igreja aprovada',
      'A sua igreja foi aprovada. O trial Plus de 30 dias ja esta ativo.',
      'church_approved',
      new_church_id,
      auth.uid(),
      'high',
      'churches',
      new_church_id,
      '/dashboard',
      jsonb_build_object(
        'church_id', new_church_id,
        'church_name', application_row.church_name,
        'trial_days', 30
      )
    );

    return new_church_id;
  end if;

  update comunhao.church_applications
  set
    status = p_decision,
    reviewed_at = now(),
    reviewed_by = auth.uid(),
    review_notes = p_review_notes,
    updated_at = now()
  where id = p_application_id;

  perform comunhao.create_internal_notification(
    application_row.pastor_profile_id,
    case
      when p_decision = 'changes_requested' then 'Correcoes solicitadas'
      else 'Pedido da igreja rejeitado'
    end,
    case
      when p_decision = 'changes_requested'
        then 'A equipa Comunhao pediu correcoes no perfil da igreja. Abre o pedido para ajustar e reenviar.'
      else 'O pedido da igreja foi rejeitado. Abre o pedido para ver a observacao da equipa Comunhao.'
    end,
    case
      when p_decision = 'changes_requested'
        then 'church_corrections_requested'
      else 'church_rejected'
    end,
    null,
    auth.uid(),
    case when p_decision = 'changes_requested' then 'high' else 'normal' end,
    'church_applications',
    p_application_id,
    '/application-status',
    jsonb_build_object(
      'application_id', p_application_id,
      'decision', p_decision,
      'notes', p_review_notes
    )
  );

  return null;
end;
$function$
$obj154$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'review_church_application(p_application_id uuid, p_decision text, p_review_notes text)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj155$CREATE OR REPLACE FUNCTION comunhao.review_church_join_request(p_request_id uuid, p_status text, p_notes text DEFAULT NULL::text)
 RETURNS church_join_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  request_row comunhao.church_join_requests%rowtype;
  normalized_status text;
begin
  normalized_status := lower(trim(coalesce(p_status, '')));

  if normalized_status not in ('under_review', 'more_information_required', 'approved', 'rejected') then
    raise exception 'Invalid join request status.';
  end if;

  select *
  into request_row
  from comunhao.church_join_requests
  where id = p_request_id
  for update;

  if request_row.id is null then
    raise exception 'Join request not found.';
  end if;

  if not comunhao.has_church_role(
    request_row.church_id,
    array['pastor', 'church_admin', 'leader']::text[],
    auth.uid()
  ) then
    raise exception 'Only church leaders can review join requests.';
  end if;

  if normalized_status = 'approved' then
    insert into comunhao.memberships (
      church_id,
      profile_id,
      role,
      status,
      approved_at,
      entry_date,
      neighborhood,
      gender
    )
    values (
      request_row.church_id,
      request_row.profile_id,
      'member',
      'active',
      now(),
      current_date,
      request_row.neighborhood,
      request_row.gender
    )
    on conflict (church_id, profile_id) do update
    set
      status = 'active',
      approved_at = coalesce(comunhao.memberships.approved_at, now()),
      entry_date = coalesce(comunhao.memberships.entry_date, current_date),
      neighborhood = coalesce(excluded.neighborhood, comunhao.memberships.neighborhood),
      gender = coalesce(excluded.gender, comunhao.memberships.gender),
      role = case
        when comunhao.memberships.role in ('pastor', 'church_admin', 'leader') then comunhao.memberships.role
        else 'member'
      end;
  end if;

  update comunhao.church_join_requests
  set
    status = normalized_status,
    reviewed_by = auth.uid(),
    reviewed_at = case when normalized_status in ('approved', 'rejected') then now() else reviewed_at end,
    review_notes = case when normalized_status in ('approved', 'rejected') then p_notes else review_notes end,
    information_requested = case when normalized_status = 'more_information_required' then p_notes else information_requested end,
    decision_reason = case when normalized_status = 'rejected' then p_notes else decision_reason end
  where id = p_request_id
  returning * into request_row;

  insert into comunhao.church_request_timeline (
    church_id,
    request_table,
    request_id,
    actor_profile_id,
    action,
    public_message,
    internal_note
  )
  values (
    request_row.church_id,
    'church_join_requests',
    request_row.id,
    auth.uid(),
    normalized_status,
    case
      when normalized_status = 'approved' then 'Pedido aprovado.'
      when normalized_status = 'rejected' then 'Pedido rejeitado.'
      when normalized_status = 'more_information_required' then 'A igreja solicitou mais informacoes.'
      else 'Pedido em analise.'
    end,
    p_notes
  );

  perform comunhao.create_internal_notification(
    request_row.profile_id,
    case
      when normalized_status = 'approved' then 'Pedido aprovado'
      when normalized_status = 'rejected' then 'Pedido rejeitado'
      when normalized_status = 'more_information_required' then 'Mais informacoes solicitadas'
      else 'Pedido em analise'
    end,
    case
      when normalized_status = 'approved' then 'A tua entrada na igreja foi aprovada.'
      when normalized_status = 'rejected' then 'A tua entrada na igreja foi rejeitada.'
      when normalized_status = 'more_information_required' then 'A igreja pediu mais informacoes para continuar a analise.'
      else 'A lideranca iniciou a analise do teu pedido.'
    end,
    'join_request',
    request_row.church_id,
    auth.uid(),
    'normal',
    'church_join_requests',
    request_row.id,
    '/requests/join/' || request_row.id::text,
    jsonb_build_object('status', normalized_status)
  );

  return request_row;
end;
