    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'review_church_join_request(p_request_id uuid, p_status text, p_notes text)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj156$CREATE OR REPLACE FUNCTION comunhao.review_subscription_request(p_request_id uuid, p_decision text, p_period_days integer DEFAULT 30, p_review_notes text DEFAULT NULL::text)
 RETURNS church_subscriptions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  request_row comunhao.church_subscription_requests%rowtype;
  result comunhao.church_subscriptions;
begin
  if not comunhao.is_super_admin(auth.uid()) then
    raise exception 'Only super admins can review subscription requests.';
  end if;

  if p_decision not in ('approved', 'rejected') then
    raise exception 'Invalid subscription review decision: %', p_decision;
  end if;

  select *
  into request_row
  from comunhao.church_subscription_requests
  where id = p_request_id
  for update;

  if not found then
    raise exception 'Subscription request not found.';
  end if;

  if request_row.status <> 'pending' then
    raise exception 'Only pending subscription requests can be reviewed.';
  end if;

  update comunhao.church_subscription_requests
  set
    status = case when p_decision = 'approved' then 'approved' else 'rejected' end,
    reviewed_at = now(),
    reviewed_by = auth.uid(),
    review_notes = p_review_notes
  where id = p_request_id;

  if p_decision = 'rejected' then
    return null;
  end if;

  result := comunhao.admin_update_church_subscription(
    request_row.church_id,
    'active',
    request_row.requested_plan_code,
    p_period_days,
    7,
    coalesce(
      p_review_notes,
      'Subscricao ativada apos confirmacao de pagamento.'
    )
  );

  perform comunhao.record_subscription_payment_to_platform(p_request_id);

  return result;
end;
$function$
$obj156$;
