    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'review_subscription_request(p_request_id uuid, p_decision text, p_period_days integer, p_review_notes text)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj157$CREATE OR REPLACE FUNCTION comunhao.review_wallet_withdrawal_request(p_request_id uuid, p_status text, p_notes text DEFAULT NULL::text)
 RETURNS wallet_withdrawal_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  request_row comunhao.wallet_withdrawal_requests%rowtype;
  debit_entry_id uuid;
  available_balance numeric;
  balance_after_value numeric;
  result comunhao.wallet_withdrawal_requests;
begin
  select *
  into request_row
  from comunhao.wallet_withdrawal_requests
  where id = p_request_id
  for update;

  if not found then
    raise exception 'Withdrawal request not found.';
  end if;

  if request_row.owner_type = 'platform' then
    if not comunhao.is_super_admin(auth.uid()) then
      raise exception 'Only super admins can review platform withdrawals.';
    end if;
  elsif not comunhao.user_has_finance_permission(request_row.church_id, 'finance.approve_withdrawal', auth.uid()) then
    raise exception 'You cannot review withdrawals for this church.';
  end if;

  if p_status not in ('approved', 'processing', 'paid', 'completed', 'rejected', 'failed', 'cancelled') then
    raise exception 'Invalid withdrawal status: %', p_status;
  end if;

  if request_row.status in ('paid', 'completed') then
    raise exception 'Withdrawal request is already paid.';
  end if;

  if p_status in ('paid', 'completed') then
    available_balance := comunhao.finance_wallet_balance(request_row.wallet_account_id);
    if available_balance < request_row.amount then
      raise exception 'Insufficient balance to complete the withdrawal.';
    end if;
    balance_after_value := available_balance - request_row.amount;

    insert into comunhao.wallet_ledger_entries (
      wallet_account_id,
      church_id,
      created_by,
      direction,
      entry_type,
      amount,
      currency,
      status,
      description,
      reference_table,
      reference_id,
      metadata,
      posted_at,
      balance_before,
      balance_after,
      idempotency_key,
      is_demo
    )
    values (
      request_row.wallet_account_id,
      request_row.church_id,
      auth.uid(),
      'debit',
      'withdrawal',
      request_row.amount,
      request_row.currency,
      'posted',
      coalesce(p_notes, request_row.notes, 'Levantamento pago.'),
      'wallet_withdrawal_requests',
      request_row.id,
      jsonb_build_object('provider', request_row.provider, 'destination_number', request_row.destination_number),
      now(),
      available_balance,
      balance_after_value,
      coalesce(request_row.idempotency_key, 'withdrawal:' || request_row.id::text || ':paid'),
      request_row.is_demo
    )
    returning id into debit_entry_id;

    update comunhao.wallet_withdrawal_requests
    set
      status = 'paid',
      notes = coalesce(p_notes, notes),
      processed_at = now(),
      processed_by = auth.uid(),
      completed_at = now(),
      ledger_entry_id = debit_entry_id,
      reserved_amount = 0,
      updated_at = now()
    where id = p_request_id
    returning * into result;

    return result;
  end if;

  update comunhao.wallet_withdrawal_requests
  set
    status = p_status,
    notes = coalesce(p_notes, notes),
    processed_at = case when p_status in ('processing', 'failed', 'rejected', 'cancelled') then now() else processed_at end,
    processed_by = auth.uid(),
    approved_by = case when p_status in ('approved', 'processing') then auth.uid() else approved_by end,
    approved_at = case when p_status in ('approved', 'processing') then now() else approved_at end,
    reserved_amount = case when p_status in ('failed', 'rejected', 'cancelled') then 0 else reserved_amount end,
    updated_at = now()
  where id = p_request_id
  returning * into result;

  return result;
end;
