  BEGIN
    EXECUTE $obj162$CREATE OR REPLACE FUNCTION comunhao.seed_vida_nova_operations_demo()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  vida_id uuid;
  sara_profile_id uuid;
  member_profile_id uuid;
  sara_membership_id uuid;
  member_membership_id uuid;
  louvor_id uuid;
  jovens_id uuid;
  infantil_id uuid;
  social_id uuid;
  group_oracao_id uuid;
  group_jovens_id uuid;
  protocolo_id uuid;
  sala_id uuid;
  asset_id uuid;
  project_id uuid;
  inventory_id uuid;
begin
  select id into vida_id
  from comunhao.churches
  where slug in ('vida-nova', 'igreja-vida-nova')
     or regexp_replace(coalesce(phone, ''), '\D', '', 'g') in ('877688695', '258877688695')
     or lower(trim(name)) in ('vida nova', 'igreja vida nova')
  limit 1;

  if vida_id is null then
    return jsonb_build_object('seeded', false, 'reason', 'Vida Nova not found');
  end if;

  sara_profile_id := comunhao.profile_id_by_phone('877688695');
  member_profile_id := comunhao.profile_id_by_phone('827688695');

  select id into sara_membership_id from comunhao.memberships where church_id = vida_id and profile_id = sara_profile_id limit 1;
  select id into member_membership_id from comunhao.memberships where church_id = vida_id and profile_id = member_profile_id limit 1;

  delete from comunhao.inventory_movements where church_id = vida_id and is_demo = true;
  delete from comunhao.inventory_items where church_id = vida_id and is_demo = true;
  delete from comunhao.purchase_requests where church_id = vida_id and is_demo = true;
  delete from comunhao.church_documents where church_id = vida_id and is_demo = true;
  delete from comunhao.room_reservations where church_id = vida_id and is_demo = true;
  delete from comunhao.church_rooms where church_id = vida_id and is_demo = true;
  delete from comunhao.maintenance_requests where church_id = vida_id and is_demo = true;
  delete from comunhao.asset_movements where church_id = vida_id and is_demo = true;
  delete from comunhao.service_rosters where church_id = vida_id and is_demo = true;
  delete from comunhao.task_comments where task_id in (select id from comunhao.operational_tasks where church_id = vida_id and is_demo = true);
  delete from comunhao.task_checklist_items where task_id in (select id from comunhao.operational_tasks where church_id = vida_id and is_demo = true);
  delete from comunhao.operational_tasks where church_id = vida_id and is_demo = true;
