  BEGIN
    EXECUTE $obj163$CREATE OR REPLACE FUNCTION comunhao.send_birthday_internal_message(p_church_id uuid, p_profile_id uuid, p_message text)
 RETURNS birthday_messages
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  notification_id uuid;
  result comunhao.birthday_messages;
begin
  if not comunhao.user_has_calendar_permission(p_church_id, 'birthday.communicate', auth.uid()) then
    raise exception 'You cannot send birthday messages for this church.';
  end if;

  if nullif(trim(coalesce(p_message, '')), '') is null then
    raise exception 'Message is required.';
  end if;

  notification_id := comunhao.create_internal_notification(
    p_profile_id,
    'Feliz aniversario',
    trim(p_message),
    'birthday',
    p_church_id,
    auth.uid(),
    'normal',
    'profiles',
    p_profile_id,
    '/birthdays',
    '{}'::jsonb
  );

  insert into comunhao.birthday_messages (
    church_id,
    profile_id,
    created_by,
    message,
    birthday_year,
    channel,
    status,
    notification_id
  )
  values (
    p_church_id,
    p_profile_id,
    auth.uid(),
    trim(p_message),
    extract(year from current_date)::int,
    'internal',
    'sent_internal',
    notification_id
  )
  on conflict (church_id, profile_id, birthday_year, channel) do update
    set message = excluded.message,
        notification_id = excluded.notification_id
  returning * into result;

  return result;
end;
