  BEGIN
    EXECUTE $obj167$CREATE OR REPLACE FUNCTION comunhao.set_community_post_pinned(p_post_id uuid, p_pinned boolean)
 RETURNS community_posts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  post_row comunhao.community_posts%rowtype;
begin
  select *
  into post_row
  from comunhao.community_posts
  where id = p_post_id;

  if not found then
    raise exception 'Community post not found.';
  end if;

  if not comunhao.can_manage_community_feed(post_row.church_id, auth.uid()) then
    raise exception 'Permission denied.';
  end if;

  update comunhao.community_posts
  set
    pinned_at = case when p_pinned then now() else null end,
    pinned_by = case when p_pinned then auth.uid() else null end
  where id = p_post_id
  returning * into post_row;

  return post_row;
end;
