  BEGIN
    EXECUTE $obj168$CREATE OR REPLACE FUNCTION comunhao.set_community_post_saved(p_post_id uuid, p_saved boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'Authentication required.';
  end if;

  if not exists (
    select 1
    from comunhao.community_posts p
    join comunhao.memberships m on m.church_id = p.church_id
    where p.id = p_post_id
      and p.status = 'approved'
      and m.profile_id = auth.uid()
      and m.status = 'active'
  ) then
    raise exception 'Community post not available.';
  end if;

  if p_saved then
    insert into comunhao.community_post_saved (post_id, profile_id)
    values (p_post_id, auth.uid())
    on conflict (post_id, profile_id) do nothing;
  else
    delete from comunhao.community_post_saved
    where post_id = p_post_id
      and profile_id = auth.uid();
  end if;
end;
