  BEGIN
    EXECUTE $obj175$CREATE OR REPLACE FUNCTION comunhao.submit_subscription_plan_request(p_church_id uuid, p_plan_code text, p_payment_provider text DEFAULT NULL::text, p_payer_phone text DEFAULT NULL::text, p_payment_reference text DEFAULT NULL::text, p_payment_notes text DEFAULT NULL::text)
 RETURNS church_subscription_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  result comunhao.church_subscription_requests;
  selected_plan comunhao.subscription_plans%rowtype;
  normalized_reference text := nullif(trim(coalesce(p_payment_reference, '')), '');
  normalized_provider text := nullif(trim(coalesce(p_payment_provider, '')), '');
begin
  if not comunhao.has_church_role(
    p_church_id,
    array['pastor', 'church_admin']::text[]
  ) then
    raise exception 'Only church admins can request a plan for this church.';
  end if;

  select *
  into selected_plan
  from comunhao.subscription_plans
  where code = p_plan_code
    and is_public = true;

  if not found then
    raise exception 'Unknown subscription plan: %', p_plan_code;
  end if;

  if selected_plan.price_mzn > 0 and normalized_provider is null then
    raise exception 'Selecione M-Pesa ou E-Mola para confirmar o pagamento.';
  end if;

  if normalized_provider is not null
    and normalized_provider not in ('mpesa', 'emola') then
    raise exception 'Invalid payment provider: %', normalized_provider;
  end if;

  update comunhao.church_subscription_requests
  set
    status = 'cancelled',
    reviewed_at = now(),
    reviewed_by = auth.uid(),
    review_notes = 'Substituido por um pedido mais recente.'
  where church_id = p_church_id
    and status = 'pending';

  insert into comunhao.church_subscription_requests (
    church_id,
    requested_plan_code,
    requested_by,
    status,
    payment_provider,
    payer_phone,
    payment_reference,
    payment_notes,
    expected_amount_mzn,
    payment_submitted_at
  )
  values (
    p_church_id,
    p_plan_code,
    auth.uid(),
    'pending',
    normalized_provider,
    nullif(trim(coalesce(p_payer_phone, '')), ''),
    normalized_reference,
    nullif(trim(coalesce(p_payment_notes, '')), ''),
    selected_plan.price_mzn,
    case
      when normalized_provider is null then null
      else now()
    end
  )
  returning *
  into result;

  return result;
end;
$function$
$obj175$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'submit_subscription_plan_request(p_church_id uuid, p_plan_code text, p_payment_provider text, p_payer_phone text, p_payment_reference text, p_payment_notes text)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj176$CREATE OR REPLACE FUNCTION comunhao.subscription_effective_status(p_status text, p_plan_code text, p_trial_ends_at timestamp with time zone, p_current_period_ends_at timestamp with time zone, p_grace_period_ends_at timestamp with time zone, p_grace_days integer DEFAULT 0)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  effective_grace_days integer := greatest(coalesce(p_grace_days, 0), 0);
  implied_grace_end timestamptz;
begin
  if p_status is null or trim(p_status) = '' then
    return 'active';
  end if;

  if p_status in ('cancelled', 'suspended') then
    return p_status;
  end if;

  if p_status = 'trial' then
    if p_trial_ends_at is null or p_trial_ends_at >= now() then
      return 'trial';
    end if;

    implied_grace_end := coalesce(
      p_grace_period_ends_at,
      p_trial_ends_at + make_interval(days => effective_grace_days)
    );

    if effective_grace_days > 0 and implied_grace_end >= now() then
      return 'grace_period';
    end if;

    return 'suspended';
  end if;

  if p_status = 'grace_period' then
    implied_grace_end := coalesce(
      p_grace_period_ends_at,
      case
        when p_current_period_ends_at is not null
          then p_current_period_ends_at + make_interval(days => effective_grace_days)
        when p_trial_ends_at is not null
          then p_trial_ends_at + make_interval(days => effective_grace_days)
        else null
      end
    );

    if effective_grace_days > 0
      and (implied_grace_end is null or implied_grace_end >= now()) then
      return 'grace_period';
    end if;

    return 'suspended';
  end if;

  if p_status = 'active' then
    if p_current_period_ends_at is null or p_current_period_ends_at >= now() then
      return 'active';
    end if;

    implied_grace_end := coalesce(
      p_grace_period_ends_at,
      p_current_period_ends_at + make_interval(days => effective_grace_days)
    );

    if effective_grace_days > 0 and implied_grace_end >= now() then
      return 'grace_period';
    end if;

    return 'suspended';
  end if;

  return p_status;
end;
$function$
$obj176$;
