    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'subscription_effective_status(p_status text, p_plan_code text, p_trial_ends_at timestamp with time zone, p_current_period_ends_at timestamp with time zone, p_grace_period_ends_at timestamp with time zone, p_grace_days integer)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj177$CREATE OR REPLACE FUNCTION comunhao.sync_church_content_publication()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  publication_id uuid;
  publication_type text;
  publication_title text;
  publication_summary text;
  publication_content text;
  publication_image text;
  publication_status text;
  publication_priority text := 'normal';
  actor_id uuid;
  existing_publication_id uuid;
begin
  if TG_TABLE_NAME = 'announcements' then
    publication_type := case when coalesce(new.pinned, false) then 'urgent_notice' else 'announcement' end;
    publication_title := new.title;
    publication_summary := left(coalesce(new.body, ''), 220);
    publication_content := coalesce(new.body, '');
    publication_image := new.image_url;
    publication_status := case when new.published_at is null then 'draft' else 'published' end;
    actor_id := coalesce(new.created_by, auth.uid());
  elsif TG_TABLE_NAME = 'events' then
    publication_type := 'announcement';
    publication_title := new.title;
    publication_summary := concat_ws(' - ', new.event_type, new.location);
    publication_content := concat_ws(E'\n', coalesce(new.description, ''), 'Marcado para ' || new.starts_at::text);
    publication_image := new.cover_image_url;
    publication_status := case
      when coalesce(new.status, 'draft') in (
        'published',
        'confirmed',
        'scheduled',
        'ongoing',
        'completed'
      ) then 'published'
      else 'draft'
    end;
    actor_id := coalesce(new.created_by, auth.uid());
  elsif TG_TABLE_NAME = 'donation_campaigns' then
    publication_type := 'announcement';
    publication_title := new.title;
    publication_summary := left(coalesce(new.description, ''), 220);
    publication_content := coalesce(new.description, '');
    publication_image := new.image_url;
    publication_status := case when coalesce(new.active, false) then 'published' else 'draft' end;
    actor_id := coalesce(new.created_by, auth.uid());
  else
    return new;
  end if;

  if publication_status = 'published' then
    select publication.id
      into existing_publication_id
    from comunhao.pastoral_publications publication
    where publication.source_table = TG_TABLE_NAME
      and publication.source_id = new.id
    limit 1;

    publication_id := coalesce(
      new.pastoral_publication_id,
      existing_publication_id,
      gen_random_uuid()
    );

    insert into comunhao.pastoral_publications (
      id,
      church_id,
      author_user_id,
      title,
      slug,
      summary,
      content,
      publication_type,
      category,
      cover_image_url,
      status,
      visibility,
      priority,
      published_at,
      allow_comments,
      allow_reactions,
      allow_sharing,
      send_notification,
      is_featured,
      is_pinned,
      source_table,
      source_id
    )
    values (
      publication_id,
      new.church_id,
      actor_id,
      publication_title,
      left(
        lower(regexp_replace(coalesce(publication_title, 'publicacao'), '[^a-zA-Z0-9]+', '-', 'g')),
        72
      ) || '-' || left(new.id::text, 8),
      publication_summary,
      publication_content,
      publication_type,
      'geral',
      publication_image,
      publication_status,
      'all',
      publication_priority,
      now(),
      true,
      true,
      true,
      false,
      false,
      false,
      TG_TABLE_NAME,
      new.id
    )
    on conflict (id) do update set
      title = excluded.title,
      slug = excluded.slug,
      summary = excluded.summary,
      content = excluded.content,
      publication_type = excluded.publication_type,
      category = excluded.category,
      cover_image_url = excluded.cover_image_url,
      status = excluded.status,
      source_table = excluded.source_table,
      source_id = excluded.source_id,
      updated_at = now();
    new.pastoral_publication_id := publication_id;
  end if;

  return new;
end;
$function$
$obj177$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'sync_church_content_publication()', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj178$CREATE OR REPLACE FUNCTION comunhao.sync_church_subscription_state(p_church_id uuid)
 RETURNS churches
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  subscription_row comunhao.church_subscriptions%rowtype;
  effective_status text;
  church_row comunhao.churches%rowtype;
begin
  select *
  into subscription_row
  from comunhao.church_subscriptions
  where church_id = p_church_id
  limit 1;

  if not found then
    update comunhao.churches
    set
      subscription_status = coalesce(subscription_status, 'trial'),
      updated_at = now()
    where id = p_church_id
    returning * into church_row;

    return church_row;
  end if;

  effective_status := comunhao.subscription_effective_status(
    subscription_row.status,
    subscription_row.plan_code,
    subscription_row.trial_ends_at,
    subscription_row.current_period_ends_at,
    subscription_row.grace_period_ends_at,
    0
  );

  update comunhao.churches
  set
    subscription_status = comunhao.map_church_subscription_status(effective_status),
    trial_ends_at = subscription_row.trial_ends_at,
    subscription_ends_at = case
      when effective_status = 'trial' then subscription_row.trial_ends_at
      else coalesce(
        subscription_row.current_period_ends_at,
        subscription_row.trial_ends_at
      )
    end,
    updated_at = now()
  where id = p_church_id
  returning * into church_row;

  return church_row;
end;
$function$
$obj178$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'sync_church_subscription_state(p_church_id uuid)', SQLERRM);
  END;
