    EXECUTE $obj180$CREATE OR REPLACE FUNCTION comunhao.toggle_pastoral_publication_saved(p_publication_id uuid, p_saved boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'Authentication required.';
  end if;

  if not comunhao.can_view_pastoral_publication(p_publication_id, auth.uid()) then
    raise exception 'Publication not available.';
  end if;

  if p_saved then
    insert into comunhao.pastoral_publication_saved (publication_id, profile_id)
    values (p_publication_id, auth.uid())
    on conflict (publication_id, profile_id) do nothing;
  else
    delete from comunhao.pastoral_publication_saved
    where publication_id = p_publication_id
      and profile_id = auth.uid();
  end if;

  return p_saved;
end;
