  BEGIN
    EXECUTE $obj182$CREATE OR REPLACE FUNCTION comunhao.transfer_church_owner(p_church_id uuid, p_new_owner_profile_id uuid, p_new_role text DEFAULT 'pastor'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  church_exists boolean;
begin
  if not comunhao.is_super_admin(auth.uid()) then
    raise exception 'Only super admins can transfer church ownership.';
  end if;

  if p_new_role not in ('pastor', 'church_admin') then
    raise exception 'Invalid owner role: %', p_new_role;
  end if;

  select exists(
    select 1
    from comunhao.churches
    where id = p_church_id
  )
  into church_exists;

  if not church_exists then
    raise exception 'Church not found.';
  end if;

  if not exists (
    select 1
    from comunhao.profiles
    where id = p_new_owner_profile_id
  ) then
    raise exception 'Profile not found for the new owner.';
  end if;

  insert into comunhao.memberships (
    church_id,
    profile_id,
    role,
    status
  )
  values (
    p_church_id,
    p_new_owner_profile_id,
    p_new_role,
    'active'
  )
  on conflict (church_id, profile_id) do update
    set
      role = excluded.role,
      status = 'active';

  insert into comunhao.church_settings (
    church_id,
    owner_profile_id
  )
  values (
    p_church_id,
    p_new_owner_profile_id
  )
  on conflict (church_id) do update
    set
      owner_profile_id = excluded.owner_profile_id,
      updated_at = now();

  return p_new_owner_profile_id;
end;
