    EXECUTE $obj183$CREATE OR REPLACE FUNCTION comunhao.update_launch_checklist_item(p_item_key text, p_status text, p_notes text DEFAULT NULL::text, p_responsible text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  result jsonb;
begin
  if not comunhao.has_platform_role(array['super_admin', 'support_agent', 'developer', 'auditor']::text[], auth.uid()) then
    raise exception 'Only platform admins can update launch checklist.';
  end if;

  update comunhao.launch_checklist_items
  set
    status = p_status,
    notes = coalesce(p_notes, notes),
    responsible = coalesce(p_responsible, responsible),
    updated_by_profile_id = auth.uid()
  where item_key = p_item_key
  returning to_jsonb(launch_checklist_items.*) into result;

  if result is null then
    raise exception 'Checklist item not found.';
  end if;

  perform comunhao.create_platform_audit_log(
    'launch_checklist.updated',
    'launch_checklist_item',
    null,
    null,
    'Checklist de lancamento atualizado: ' || p_item_key,
    jsonb_build_object('item_key', p_item_key, 'status', p_status)
  );

  return result;
end;
