    EXECUTE $obj185$CREATE OR REPLACE FUNCTION comunhao.update_own_community_post(p_post_id uuid, p_title text, p_body text, p_image_url text DEFAULT NULL::text, p_community_space text DEFAULT NULL::text)
 RETURNS community_posts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  post_row comunhao.community_posts%rowtype;
  normalized_space text := nullif(trim(coalesce(p_community_space, '')), '');
begin
  if auth.uid() is null then
    raise exception 'Authentication required.';
  end if;

  if length(trim(coalesce(p_title, ''))) < 3 then
    raise exception 'Title is too short.';
  end if;

  if length(trim(coalesce(p_body, ''))) < 5 then
    raise exception 'Body is too short.';
  end if;

  update comunhao.community_posts
  set
    title = trim(p_title),
    body = trim(p_body),
    image_url = nullif(trim(coalesce(p_image_url, '')), ''),
    community_space = coalesce(normalized_space, community_space, 'general')
  where id = p_post_id
    and author_profile_id = auth.uid()
    and status = 'approved'
  returning * into post_row;

  if not found then
    raise exception 'Community post not editable.';
  end if;

  return post_row;
end;
