    EXECUTE $obj186$CREATE OR REPLACE FUNCTION comunhao.update_own_community_post(p_post_id uuid, p_title text, p_body text, p_image_url text DEFAULT NULL::text, p_community_space text DEFAULT NULL::text, p_media_url text DEFAULT NULL::text, p_media_type text DEFAULT NULL::text, p_media_mime_type text DEFAULT NULL::text)
 RETURNS community_posts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  post_row comunhao.community_posts%rowtype;
  normalized_space text := nullif(trim(coalesce(p_community_space, '')), '');
  normalized_media_type text := nullif(trim(coalesce(p_media_type, '')), '');
begin
  if auth.uid() is null then
    raise exception 'Authentication required.';
  end if;

  if normalized_media_type is not null
     and normalized_media_type not in (
       'image',
       'video',
       'audio',
       'document',
       'external_link',
       'live_stream'
     ) then
    raise exception 'Unsupported community media type.';
  end if;

  update comunhao.community_posts
  set
    title = trim(p_title),
    body = trim(p_body),
    image_url = nullif(trim(coalesce(p_image_url, '')), ''),
    community_space = coalesce(normalized_space, community_space, 'general'),
    media_url = nullif(trim(coalesce(p_media_url, '')), ''),
    media_type = normalized_media_type,
    media_mime_type = nullif(trim(coalesce(p_media_mime_type, '')), ''),
    updated_at = now()
  where id = p_post_id
    and author_profile_id = auth.uid()
    and status = 'approved'
  returning * into post_row;

  if not found then
    raise exception 'Post not found or cannot be edited.';
  end if;

  return post_row;
end;
