  BEGIN
    EXECUTE $obj187$CREATE OR REPLACE FUNCTION comunhao.update_pastoral_request_status(p_request_id uuid, p_status text, p_public_response text DEFAULT NULL::text, p_internal_note text DEFAULT NULL::text, p_assigned_membership_id uuid DEFAULT NULL::uuid)
 RETURNS pastoral_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  request_row comunhao.pastoral_requests%rowtype;
begin
  select *
  into request_row
  from comunhao.pastoral_requests
  where id = p_request_id
  for update;

  if request_row.id is null then
    raise exception 'Pastoral request not found.';
  end if;

  if not comunhao.has_church_role(
    request_row.church_id,
    array['pastor', 'church_admin', 'leader']::text[],
    auth.uid()
  ) then
    raise exception 'Not authorized.';
  end if;

  update comunhao.pastoral_requests
  set
    status = p_status,
    assigned_membership_id = coalesce(p_assigned_membership_id, assigned_membership_id),
    assigned_by = case when p_assigned_membership_id is not null then auth.uid() else assigned_by end,
    assigned_at = case when p_assigned_membership_id is not null then now() else assigned_at end,
    resolved_at = case when p_status = 'resolved' then now() else resolved_at end,
    closed_at = case when p_status in ('closed', 'cancelled') then now() else closed_at end
  where id = p_request_id
  returning * into request_row;

  if nullif(trim(coalesce(p_public_response, '')), '') is not null then
    insert into comunhao.pastoral_request_responses (
      pastoral_request_id,
      responder_profile_id,
      body,
      internal_only
    )
    values (request_row.id, auth.uid(), trim(p_public_response), false);
  end if;

  if nullif(trim(coalesce(p_internal_note, '')), '') is not null then
    insert into comunhao.pastoral_request_responses (
      pastoral_request_id,
      responder_profile_id,
      body,
      internal_only
    )
    values (request_row.id, auth.uid(), trim(p_internal_note), true);
  end if;

  insert into comunhao.church_request_timeline (
    church_id,
    request_table,
    request_id,
    actor_profile_id,
    action,
    public_message,
    internal_note
  )
  values (
    request_row.church_id,
    'pastoral_requests',
    request_row.id,
    auth.uid(),
    p_status,
    p_public_response,
    p_internal_note
  );

  if p_assigned_membership_id is not null then
    perform comunhao.create_internal_notification(
      (select profile_id from comunhao.memberships where id = p_assigned_membership_id),
      'Pedido pastoral atribuido',
      'Existe um pedido pastoral que requer acompanhamento.',
      'pastoral_request_assigned',
      request_row.church_id,
      auth.uid(),
      request_row.urgency,
      'pastoral_requests',
      request_row.id,
      '/requests/pastoral/' || request_row.id::text,
      jsonb_build_object('status', p_status)
    );
  end if;

  return request_row;
end;
$function$
$obj187$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'update_pastoral_request_status(p_request_id uuid, p_status text, p_public_response text, p_internal_note text, p_assigned_membership_id uuid)', SQLERRM);
  END;
