    EXECUTE $obj188$CREATE OR REPLACE FUNCTION comunhao.user_can_access_church(p_church_id uuid, p_permission text DEFAULT NULL::text, p_user uuid DEFAULT auth.uid())
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
  select
    coalesce(auth.role(), '') = 'service_role'
    or comunhao.has_platform_role(array['super_admin', 'support_agent', 'auditor']::text[], coalesce(p_user, auth.uid()))
    or exists (
      select 1
      from comunhao.memberships m
      where m.profile_id = coalesce(p_user, auth.uid())
        and m.church_id = p_church_id
        and m.status = 'active'
    )
    or exists (
      select 1
      from comunhao.churches c
      where c.id = p_church_id
        and c.organization_id is not null
        and comunhao.user_can_access_organization(c.organization_id, p_permission, coalesce(p_user, auth.uid()))
    );
$function$
$obj188$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
