  END;
  BEGIN
    EXECUTE $obj189$CREATE OR REPLACE FUNCTION comunhao.user_can_access_organization(p_organization_id uuid, p_permission text DEFAULT NULL::text, p_user uuid DEFAULT auth.uid())
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
  select
    coalesce(auth.role(), '') = 'service_role'
    or comunhao.has_platform_role(array['super_admin', 'support_agent', 'auditor']::text[], coalesce(p_user, auth.uid()))
    or exists (
      select 1
      from comunhao.memberships m
      join comunhao.churches c on c.id = m.church_id
      where m.profile_id = coalesce(p_user, auth.uid())
        and m.status = 'active'
        and c.organization_id = p_organization_id
        and (
          m.role in ('pastor', 'church_admin')
          or coalesce(p_permission, '') = ''
        )
    )
    or exists (
      select 1
      from comunhao.church_unit_leaderships l
      where l.profile_id = coalesce(p_user, auth.uid())
        and l.organization_id = p_organization_id
        and l.status = 'active'
        and (
          coalesce(p_permission, '') = ''
          or p_permission = any(l.permissions)
        )
    );
