  BEGIN
    EXECUTE $obj194$CREATE OR REPLACE FUNCTION comunhao.verify_phone_auth_otp(p_phone text, p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions', 'auth', 'extensions'
AS $function$
declare
  normalized_phone text := comunhao.normalize_phone_auth_number(p_phone);
  normalized_token text := comunhao.normalize_phone_auth_number(p_token);
  otp_row comunhao.phone_auth_otps%rowtype;
  expected_hash text;
  verified_user_id uuid;
  merged_metadata jsonb;
begin
  if normalized_phone = '' then
    raise exception 'Numero de telefone invalido.';
  end if;

  if char_length(normalized_token) <> 6 then
    raise exception 'O codigo OTP deve ter 6 digitos.';
  end if;

  update comunhao.phone_auth_otps
  set status = 'expired'
  where phone = normalized_phone
    and status = 'pending'
    and expires_at < now();

  select *
  into otp_row
  from comunhao.phone_auth_otps
  where phone = normalized_phone
    and status = 'pending'
  order by created_at desc
  limit 1
  for update;

  if not found then
    raise exception 'Nao existe nenhum codigo ativo para este numero.';
  end if;

  expected_hash := encode(
    extensions.digest(normalized_phone || ':' || normalized_token, 'sha256'),
    'hex'
  );

  if otp_row.otp_hash <> expected_hash then
    update comunhao.phone_auth_otps
    set
      attempts = attempts + 1,
      status = case
        when attempts + 1 >= 5 then 'cancelled'
        else status
      end
    where id = otp_row.id;

    raise exception 'Codigo OTP invalido.';
  end if;

  update comunhao.phone_auth_otps
  set
    attempts = attempts + 1,
    status = 'verified',
    verified_at = now()
  where id = otp_row.id
  returning auth_user_id
  into verified_user_id;

  select coalesce(raw_user_meta_data, '{}'::jsonb)
  into merged_metadata
  from auth.users
  where id = verified_user_id
  limit 1;

  merged_metadata := merged_metadata
    || jsonb_build_object(
      'phone', normalized_phone,
      'phone_verified', true,
      'phone_verified_at', now()
    );

  update auth.users
  set
    phone = normalized_phone,
    phone_confirmed_at = now(),
    raw_user_meta_data = merged_metadata,
    updated_at = now()
  where id = verified_user_id;

  update auth.identities
  set
    provider_id = normalized_phone,
    identity_data = coalesce(identity_data, '{}'::jsonb)
      || jsonb_build_object(
        'phone', normalized_phone,
        'phone_verified', true,
        'phone_verified_at', now()
      ),
    updated_at = now()
  where user_id = verified_user_id
    and provider = 'phone';

  update comunhao.profiles
  set phone = normalized_phone
  where id = verified_user_id;

  update comunhao.phone_auth_otps
  set status = 'cancelled'
  where phone = normalized_phone
    and status = 'pending'
    and id <> otp_row.id;

  return jsonb_build_object(
    'user_id', verified_user_id,
    'phone', normalized_phone,
    'verified_at', now()
  );
end;
$function$
$obj194$;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO core.migration_programmability_issues (
      migration_name, object_kind, object_name, error_message
    ) VALUES ('309_comunhao_programmability_and_rls', 'function', 'verify_phone_auth_otp(p_phone text, p_token text)', SQLERRM);
  END;
  BEGIN
    EXECUTE $obj195$CREATE OR REPLACE FUNCTION comunhao.wallet_account_balance(p_wallet_account_id uuid)
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
  select coalesce(
    sum(
      case
        when direction = 'credit' and status = 'posted' then amount
        when direction = 'debit' and status = 'posted' then -amount
        else 0
      end
    ),
    0
  )
  from comunhao.wallet_ledger_entries
  where wallet_account_id = p_wallet_account_id;
