 SECURITY DEFINER
 SET search_path TO 'comunhao', 'public', 'auth', 'extensions'
AS $function$
declare
  post_row comunhao.community_posts%rowtype;
begin
  select *
  into post_row
  from comunhao.community_posts
  where id = p_post_id;

  if not found then
    raise exception 'Community post not found.';
  end if;

  if not comunhao.can_manage_community_feed(post_row.church_id, auth.uid()) then
    raise exception 'Permission denied.';
  end if;

  insert into comunhao.community_member_warnings (
    church_id,
    profile_id,
    post_id,
    warning_type,
    note,
    issued_by
  )
  values (
    post_row.church_id,
    post_row.author_profile_id,
    p_post_id,
    case when p_suspend then 'suspension' else 'warning' end,
    nullif(trim(coalesce(p_note, '')), ''),
    auth.uid()
  );

  if p_suspend then
    update comunhao.memberships
    set status = 'blocked'
    where church_id = post_row.church_id
      and profile_id = post_row.author_profile_id;
  end if;
end;
