GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA comunhao TO anon, authenticated, service_role;
ALTER DEFAULT PRIVILEGES IN SCHEMA comunhao GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO anon, authenticated, service_role;
ALTER DEFAULT PRIVILEGES IN SCHEMA comunhao GRANT EXECUTE ON FUNCTIONS TO anon, authenticated, service_role;
ALTER ROLE authenticator SET pgrst.db_schemas = 'public,graphql_public,core,deligo,sarca,taomoz,comunhao';
NOTIFY pgrst, 'reload config';
NOTIFY pgrst, 'reload schema';
COMMIT;
